import React, { useEffect, useRef, useState } from 'react';

export const OwlMascot: React.FC = () => {
  const [pupilPos, setPupilPos] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!containerRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();
      const owlCenterX = rect.left + rect.width / 2;
      const owlCenterY = rect.top + rect.height / 2;

      const angle = Math.atan2(e.clientY - owlCenterY, e.clientX - owlCenterX);
      const distance = Math.min(
        10,
        Math.hypot(e.clientX - owlCenterX, e.clientY - owlCenterY) / 10
      );

      setPupilPos({
        x: Math.cos(angle) * distance,
        y: Math.sin(angle) * distance,
      });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div ref={containerRef} className="w-48 h-48 relative mx-auto mb-8">
      {/* Body */}
      <svg viewBox="0 0 200 200" className="w-full h-full drop-shadow-2xl">
        <defs>
          <linearGradient id="bodyGrad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#4ADE80" />
            <stop offset="100%" stopColor="#22C55E" />
          </linearGradient>
        </defs>

        {/* Main Body */}
        <ellipse cx="100" cy="110" rx="70" ry="80" fill="url(#bodyGrad)" />
        {/* Ears */}
        <path d="M40 60 L30 30 L70 50 Z" fill="#22C55E" />
        <path d="M160 60 L170 30 L130 50 Z" fill="#22C55E" />

        {/* Belly */}
        <ellipse cx="100" cy="130" rx="45" ry="50" fill="#DCFCE7" opacity="0.8" />

        {/* Eyes Container (Whites) */}
        <g className="eyes">
          <circle cx="75" cy="85" r="25" fill="white" stroke="#166534" strokeWidth="2" />
          <circle cx="125" cy="85" r="25" fill="white" stroke="#166534" strokeWidth="2" />
        </g>

        {/* Pupils (Moving Parts) */}
        <g style={{ transform: `translate(${pupilPos.x}px, ${pupilPos.y}px)` }}>
          <circle cx="75" cy="85" r="10" fill="#1e293b" />
          <circle cx="77" cy="83" r="3" fill="white" opacity="0.8" />

          <circle cx="125" cy="85" r="10" fill="#1e293b" />
          <circle cx="127" cy="83" r="3" fill="white" opacity="0.8" />
        </g>

        {/* Beak */}
        <path d="M90 105 L110 105 L100 120 Z" fill="#F59E0B" stroke="#B45309" strokeWidth="1" />

        {/* Feet */}
        <path d="M70 180 L60 190 L80 190 Z" fill="#F59E0B" />
        <path d="M130 180 L120 190 L140 190 Z" fill="#F59E0B" />
      </svg>
    </div>
  );
};

import React, { useState } from 'react';
import { Moon, Sun } from 'lucide-react';

interface LampSwitchProps {
  isDark: boolean;
  toggleTheme: () => void;
}

export const LampSwitch: React.FC<LampSwitchProps> = ({ isDark, toggleTheme }) => {
  const [isPulling, setIsPulling] = useState(false);

  const handlePull = () => {
    setIsPulling(true);
    // Play generic click sound simulation
    const audio = new Audio('https://assets.mixkit.co/sfx/preview/mixkit-light-switch-pull-2579.mp3'); 
    audio.volume = 0.5;
    audio.play().catch(() => {}); // Ignore errors if no user interaction yet

    setTimeout(() => {
      toggleTheme();
      setIsPulling(false);
    }, 300);
  };

  return (
    <div className="flex flex-col items-center justify-center p-8 bg-slate-100 dark:bg-slate-800 rounded-2xl shadow-inner transition-colors duration-500">
      <h3 className="mb-4 text-xl font-bold text-slate-700 dark:text-slate-200">Ambient Lighting</h3>
      <div className="relative h-64 w-32 flex justify-center">
        {/* Lamp Cord Base */}
        <div className="absolute top-0 w-1 h-32 bg-gray-400 dark:bg-gray-600 origin-top transition-transform duration-300"
             style={{ transform: isPulling ? 'scaleY(1.1)' : 'scaleY(1)' }}></div>

        {/* Pull Handle */}
        <button
          onClick={handlePull}
          className={`absolute top-32 -ml-[2px] w-8 h-8 rounded-full shadow-lg flex items-center justify-center
            transition-all duration-300 z-10 hover:scale-110 active:scale-90
            ${isDark ? 'bg-yellow-400 shadow-yellow-400/50' : 'bg-slate-700 shadow-slate-900/50'}
            ${isPulling ? 'translate-y-4' : 'translate-y-0'}
          `}
        >
          {isDark ? <Moon size={16} className="text-white" /> : <Sun size={16} className="text-yellow-300" />}
        </button>

        {/* Light Cone Effect (CSS) */}
        {isDark ? null : (
             <div className="absolute top-10 w-64 h-64 bg-yellow-400/20 rounded-full blur-3xl -z-10 animate-pulse"></div>
        )}
      </div>
      <p className="mt-4 text-sm text-slate-500 dark:text-slate-400">Pull to switch mode</p>
    </div>
  );
};

