        audio.play().catch(() => {});

        setTimeout(() => {
            onLogin();
        }, 800); // Wait for animation to finish
    }, 1000);
  };

  return (
    <div className={`min-h-screen w-full flex items-center justify-center bg-slate-50 dark:bg-[#0f1014] transition-colors p-4 overflow-hidden ${isExiting ? 'pointer-events-none' : ''}`}>
