const App: React.FC = () => {
  const [isDark, setIsDark] = useState(true);
  const [view, setView] = useState<ViewState>('login');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const notificationRef = useRef<HTMLDivElement>(null);

  // Theme Handling
  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  // Click Outside Handler for Notifications
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleTheme = () => setIsDark(!isDark);

  const handleLogin = () => {
    new Audio('https://assets.mixkit.co/sfx/preview/mixkit-sci-fi-positive-notification-266.mp3').play().catch(() => {});
    setIsLoggedIn(true);
    setView('dashboard');
  };

  const handleLogout = () => {
      setIsLoggedIn(false);
  };

  const toggleNotifications = () => {
    const newState = !showNotifications;
    setShowNotifications(newState);
    if (newState) {
        new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {});
    }
  };

  if (!isLoggedIn) {
    return <LoginView onLogin={handleLogin} />;
  }

  const renderContent = () => {
    switch (view) {
      case 'dashboard': return <StatsDashboard />;
      case 'voice': return <VoiceChat />;
      case 'social': return <BrowseView />;
      case 'friends': return <FriendsView />;
      case 'tasks': return <TasksView />;
      case 'settings': 
        return <SettingsView isDark={isDark} toggleTheme={toggleTheme} onLogout={handleLogout} />;
      default: return <StatsDashboard />;
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#09090b] text-white transition-colors overflow-hidden font-sans relative selection:bg-purple-500 selection:text-white">

      {/* --- Global Background Animation --- */}
      <div className="absolute inset-0 z-0 opacity-40 pointer-events-none overflow-hidden">
        <div className="absolute top-[-20%] left-[-20%] w-[60%] h-[60%] bg-purple-900/30 rounded-full blur-[120px] animate-blob mix-blend-screen"></div>
        <div className="absolute bottom-[-20%] right-[-20%] w-[60%] h-[60%] bg-blue-900/30 rounded-full blur-[120px] animate-blob animation-delay-2000 mix-blend-screen"></div>
        <div className="absolute top-[20%] right-[20%] w-[40%] h-[40%] bg-pink-900/20 rounded-full blur-[100px] animate-blob animation-delay-4000 mix-blend-screen"></div>
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-5 brightness-150 contrast-150"></div>
      </div>

      {/* Sidebar Navigation */}
      <nav className="w-20 lg:w-24 h-full bg-[#121216]/80 backdrop-blur-xl flex flex-col items-center py-8 z-20 border-r border-white/5 relative">
        <div className="w-12 h-12 bg-gradient-to-br from-purple-500 via-indigo-500 to-blue-500 rounded-xl mb-12 flex items-center justify-center text-white font-black text-xl shadow-[0_0_25px_rgba(168,85,247,0.4)] relative group cursor-pointer hover:scale-110 transition-transform">
          <span className="z-10">N</span>
          <div className="absolute inset-0 bg-white/20 rounded-xl blur-lg opacity-0 group-hover:opacity-100 transition-opacity"></div>
        </div>

        <div className="flex-1 w-full flex flex-col items-center">
          <SidebarItem icon={LayoutDashboard} active={view === 'dashboard'} onClick={() => setView('dashboard')} />
          <SidebarItem icon={Mic} active={view === 'voice'} onClick={() => setView('voice')} badge={2} />
          <SidebarItem icon={Video} active={view === 'social'} onClick={() => setView('social')} />
          <SidebarItem icon={Users} active={view === 'friends'} onClick={() => setView('friends')} badge={3} />
          <SidebarItem icon={Gamepad2} active={view === 'tasks'} onClick={() => setView('tasks')} />
          <SidebarItem icon={Settings} active={view === 'settings'} onClick={() => setView('settings')} />
        </div>

        <button 
            onClick={handleLogout} 
            className="mb-8 w-12 h-12 flex items-center justify-center rounded-2xl text-slate-500 hover:text-red-500 hover:bg-red-500/10 transition-all hover:scale-105"
        >
          <LogOut size={20} />
        </button>
      </nav>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 relative z-10">

        {/* Top Header */}
        <header className="h-20 px-8 flex items-center justify-between z-10 sticky top-0">
          <div className="flex items-center gap-4 bg-white/5 backdrop-blur-md px-4 py-2.5 rounded-2xl border border-white/5 w-full max-w-md hover:bg-white/10 transition-colors focus-within:border-purple-500/50 focus-within:bg-white/10 group">
            <Search className="text-slate-500 group-focus-within:text-purple-400 transition-colors" size={18} />
            <input 
              type="text" 
              placeholder="Search Nexus..." 
              className="bg-transparent outline-none flex-1 text-white placeholder-slate-500 font-medium"
            />
          </div>

          <div className="flex items-center gap-6">

            {/* Notification Dropdown */}
            <div className="relative" ref={notificationRef}>
                <button 
                    onClick={toggleNotifications}
                    className={`relative w-10 h-10 rounded-full flex items-center justify-center transition-all duration-300
                      ${showNotifications 
                        ? 'bg-gradient-to-tr from-purple-600 to-indigo-600 text-white shadow-[0_0_15px_rgba(147,51,234,0.5)] scale-110' 
                        : 'bg-white/5 text-slate-400 hover:bg-white/10 hover:text-white hover:scale-105'}
                    `}
                >
                    <Bell size={18} className={`transition-transform duration-500 ${showNotifications ? 'rotate-[360deg]' : ''}`} />
                    {!showNotifications && (
                        <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-[#09090b] animate-pulse"></span>
                    )}
                </button>

                {showNotifications && (
                    <div className="absolute top-16 right-0 w-80 sm:w-96 bg-[#18181b]/95 backdrop-blur-xl rounded-2xl shadow-[0_0_50px_rgba(0,0,0,0.5)] border border-white/10 overflow-hidden origin-top-right animate-notificationPop z-50">
                        <div className="p-4 border-b border-white/5 flex justify-between items-center bg-white/5">
                            <h3 className="font-bold text-white">Notifications</h3>
                            <button className="text-xs font-bold text-purple-400 hover:text-purple-300">Mark all read</button>
                        </div>
                        <div className="max-h-[400px] overflow-y-auto custom-scrollbar p-2">
                            {NOTIFICATIONS.map((notif, i) => (
                            <div key={notif.id} className="flex gap-4 p-3 hover:bg-white/5 rounded-xl transition-colors cursor-pointer group animate-slideIn" style={{animationDelay: `${i * 75}ms`, animationFillMode: 'both'}}>
