import React, { useEffect, useRef, useState } from 'react';

export const OwlMascot: React.FC = () => {
  const [pupilPos, setPupilPos] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!containerRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();
      const owlCenterX = rect.left + rect.width / 2;
      const owlCenterY = rect.top + rect.height / 2;

      const angle = Math.atan2(e.clientY - owlCenterY, e.clientX - owlCenterX);
      const distance = Math.min(
        10,
        Math.hypot(e.clientX - owlCenterX, e.clientY - owlCenterY) / 10
      );

      setPupilPos({
        x: Math.cos(angle) * distance,
        y: Math.sin(angle) * distance,
      });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div ref={containerRef} className="w-48 h-48 relative mx-auto mb-8">
      {/* Body */}
      <svg viewBox="0 0 200 200" className="w-full h-full drop-shadow-2xl overflow-visible">
        <defs>
          <linearGradient id="bodyGrad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#4ADE80" />
            <stop offset="100%" stopColor="#22C55E" />
          </linearGradient>
        </defs>

        {/* Wings (Static) */}
        {/* Left Wing */}
        <g className="origin-[40px_110px] rotate-[10deg] translate-y-1">
           <path d="M40 100 C 0 90, -30 60, -30 30 C -10 70, 30 110, 50 120 Z" fill="#22C55E" stroke="#166534" strokeWidth="2" />
        </g>

        {/* Right Wing */}
        <g className="origin-[160px_110px] -rotate-[10deg] translate-y-1">
           <path d="M160 100 C 200 90, 230 60, 230 30 C 210 70, 170 110, 150 120 Z" fill="#22C55E" stroke="#166534" strokeWidth="2" />
        </g>

        {/* Main Body */}
        <ellipse cx="100" cy="110" rx="70" ry="80" fill="url(#bodyGrad)" />
        {/* Ears */}
        <path d="M40 60 L30 30 L70 50 Z" fill="#22C55E" />
        <path d="M160 60 L170 30 L130 50 Z" fill="#22C55E" />

        {/* Belly */}
        <ellipse cx="100" cy="130" rx="45" ry="50" fill="#DCFCE7" opacity="0.8" />

        {/* Eyes Container (Whites) */}
        <g className="eyes">
          <circle cx="75" cy="85" r="25" fill="white" stroke="#166534" strokeWidth="2" />
