        </p>

        <form className="space-y-4" onSubmit={handleLogin}>
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase tracking-wider text-slate-500 ml-4">Email</label>
            <input 
              type="email" 
              defaultValue="gamer@nexus.com" 
              className="w-full h-14 px-6 rounded-2xl bg-slate-100 dark:bg-black/30 border-2 border-transparent focus:border-purple-500 focus:bg-white dark:focus:bg-black outline-none transition-all font-medium text-slate-800 dark:text-white"
            />
          </div>

          <div className="space-y-2">
             <label className="text-xs font-bold uppercase tracking-wider text-slate-500 ml-4">Password</label>
            <input 
              type="password" 
              defaultValue="password123" 
              className="w-full h-14 px-6 rounded-2xl bg-slate-100 dark:bg-black/30 border-2 border-transparent focus:border-purple-500 focus:bg-white dark:focus:bg-black outline-none transition-all font-medium text-slate-800 dark:text-white"
            />
          </div>

          <button 
            type="submit"
            disabled={isLoading}
            className="w-full h-14 mt-4 bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 active:scale-95 text-white font-bold rounded-2xl shadow-lg shadow-purple-600/30 transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed overflow-hidden relative"
          >
            {isLoading ? <Loader2 className="animate-spin relative z-10" /> : <span className="relative z-10">Enter Nexus</span>}
            {isLoading && <div className="absolute inset-0 bg-white/20 animate-pulse"></div>}
