        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/10 rounded-full blur-3xl animate-pulse delay-1000"></div>
      </div>

      <style>{`
        @keyframes warpSpeed {
            0% { transform: scale(1) translateZ(0); opacity: 1; }
