import React, { useState, useEffect, useRef } from 'react';

export const OwlMascot: React.FC = () => {
  const [error, setError] = useState(false);
  const leftEyeRef = useRef<HTMLDivElement>(null);
  const rightEyeRef = useRef<HTMLDivElement>(null);

  // Mouse tracking logic
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!leftEyeRef.current || !rightEyeRef.current) return;

      [leftEyeRef.current, rightEyeRef.current].forEach((eye) => {
        const rect = eye.getBoundingClientRect();
        const eyeCenterX = rect.left + rect.width / 2;
        const eyeCenterY = rect.top + rect.height / 2;

        // Calculate angle
        const angle = Math.atan2(e.clientY - eyeCenterY, e.clientX - eyeCenterX);

        // Calculate distance (clamped to keep pupil inside eye)
        // We limit the movement to make it look realistic (not popping out of socket)
        const maxDist = eye.clientWidth / 5; 
        const dist = Math.min(maxDist, Math.hypot(e.clientX - eyeCenterX, e.clientY - eyeCenterY) / 10);

        const x = Math.cos(angle) * dist;
        const y = Math.sin(angle) * dist;

        const pupil = eye.querySelector('.pupil') as HTMLElement;
        if (pupil) {
          pupil.style.transform = `translate(${x}px, ${y}px)`;
        }
      });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div className="w-48 h-48 relative mx-auto mb-8 flex items-center justify-center group select-none">
      {!error ? (
        <>
            {/* Base Static Image */}
            <img 
              src="https://raw.githubusercontent.com/Tarikul-Islam-Anik/Animated-Fluent-Emojis/master/Emojis/Animals/Owl.png" 
              alt="Owl Mascot" 
              onError={() => setError(true)}
              className="w-full h-full object-contain drop-shadow-2xl transition-transform duration-300 group-hover:scale-105 z-10 relative pointer-events-none"
            />

            {/* Left Eye Overlay */}
            {/* Manually positioned to cover the static eyes of this specific PNG */}
            <div 
                ref={leftEyeRef}
                className="absolute w-[23%] h-[23%] rounded-full bg-gradient-to-b from-[#ffdf6c] to-[#ffc526] z-20 flex items-center justify-center overflow-hidden"
                style={{ top: '35%', left: '25%', boxShadow: 'inset 2px 2px 4px rgba(255,255,255,0.4), inset -1px -1px 4px rgba(0,0,0,0.1)' }}
            >
                {/* Pupil */}
                <div className="pupil w-[55%] h-[55%] bg-[#3d2e26] rounded-full relative transition-transform duration-75 ease-out shadow-sm">
                    {/* Reflection */}
                    <div className="absolute top-[20%] right-[20%] w-[25%] h-[25%] bg-white rounded-full opacity-90"></div>
                </div>
            </div>

            {/* Right Eye Overlay */}
            <div 
                ref={rightEyeRef}
                className="absolute w-[23%] h-[23%] rounded-full bg-gradient-to-b from-[#ffdf6c] to-[#ffc526] z-20 flex items-center justify-center overflow-hidden"
                style={{ top: '35%', right: '25%', boxShadow: 'inset 2px 2px 4px rgba(255,255,255,0.4), inset -1px -1px 4px rgba(0,0,0,0.1)' }}
            >
                {/* Pupil */}
                <div className="pupil w-[55%] h-[55%] bg-[#3d2e26] rounded-full relative transition-transform duration-75 ease-out shadow-sm">
                    {/* Reflection */}
                    <div className="absolute top-[20%] right-[20%] w-[25%] h-[25%] bg-white rounded-full opacity-90"></div>
                </div>
            </div>
        </>
      ) : (
        <div className="text-8xl animate-bounce filter drop-shadow-lg cursor-default">🦉</div>
      )}
    </div>
  );
};

