  { id: '1', username: 'Nelly', avatar: 'https://picsum.photos/100/100?random=10', status: 'online' },
  { id: '2', username: 'Mallow', avatar: 'https://picsum.photos/100/100?random=11', status: 'online' },
  { id: '3', username: 'Graggle', avatar: 'https://picsum.photos/100/100?random=12', status: 'online' },
  { id: '4', username: 'Phibi', avatar: 'https://picsum.photos/100/100?random=13', status: 'dnd' },
  { id: '5', username: 'Locke', avatar: 'https://picsum.photos/100/100?random=14', status: 'idle' },
];

export const VoiceChat: React.FC = () => {
  const [muted, setMuted] = useState(false);
  const [deafened, setDeafened] = useState(false);
  const [camera, setCamera] = useState(false);
  const [sharing, setSharing] = useState(false);

  // Manage remote participants state for dynamic UI
  const [participants, setParticipants] = useState(INITIAL_USERS.map(u => ({
    ...u,
    isMuted: Math.random() > 0.8, // Random initial mute state
    isTalking: false,
    isCamOn: Math.random() > 0.4 // Random camera state
  })));

  // Simulate talking activity
  useEffect(() => {
    const interval = setInterval(() => {
        setParticipants(prev => prev.map(p => {
            // If muted, cannot talk
            if (p.isMuted) return { ...p, isTalking: false };

            // Random talking toggle
            // If currently talking, 60% chance to stop. If not talking, 30% chance to start.
            const willTalk = p.isTalking ? Math.random() > 0.6 : Math.random() > 0.7;

            return {
                ...p,
                isTalking: willTalk
            };
        }));
    }, 1200); // Update every 1.2s for smoother pacing

    return () => clearInterval(interval);
  }, []);

  const playSound = (type: 'join' | 'leave' | 'mute' | 'unmute') => {
    let src = '';
    switch(type) {
        case 'join': src = 'https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3'; break;
        case 'leave': src = 'https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3'; break;
        case 'mute': src = 'https://assets.mixkit.co/sfx/preview/mixkit-interface-click-1126.mp3'; break;
        case 'unmute': src = 'https://assets.mixkit.co/sfx/preview/mixkit-sci-fi-click-900.mp3'; break;
    }
    if(src) new Audio(src).play().catch(() => {});
  };

  const toggleMute = () => {
    const newState = !muted;
    setMuted(newState);
    playSound(newState ? 'mute' : 'unmute');
  };

  return (
    <div className="flex flex-col h-full bg-[#0a0a0c] text-white overflow-hidden animate-fadeIn">

      {/* Header Channel Info */}
      <div className="h-16 border-b border-white/5 flex items-center justify-between px-6 bg-white/[0.02]">
         <div className="flex items-center gap-3">
             <Signal className="text-green-500" />
             <div>
                 <h2 className="font-bold text-lg leading-tight">General Voice</h2>
                 <p className="text-xs text-slate-500">RTC Connected • 14ms Ping</p>
             </div>
         </div>
         <div className="flex -space-x-3">
             {/* Show current user avatar too */}
             <div className="w-8 h-8 rounded-full border-2 border-[#0a0a0c] overflow-hidden">
                <img src="https://picsum.photos/50/50?random=99" className="w-full h-full object-cover" />
             </div>
             {participants.slice(0,3).map(u => (
                 <img key={u.id} src={u.avatar} className="w-8 h-8 rounded-full border-2 border-[#0a0a0c]" />
             ))}
             <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-xs font-bold border-2 border-[#0a0a0c]">{participants.length + 1}</div>
         </div>
      </div>

      {/* Main Stage - Grid of Users */}
      <div className="flex-1 p-6 grid grid-cols-2 md:grid-cols-3 gap-6 overflow-y-auto custom-scrollbar content-start">

        {/* Local User Tile */}
        <div className="relative aspect-video bg-[#18181b] rounded-3xl flex flex-col items-center justify-center group overflow-hidden transition-all hover:scale-[1.02] shadow-xl border border-white/5">
            {/* Camera Feed or Avatar */}
            {camera ? (
                <div className="absolute inset-0 bg-slate-800">
                    <img src="https://images.unsplash.com/photo-1595152772835-219674b2a8a6?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover opacity-80" alt="Camera Feed" />
                    <div className="absolute top-2 right-2 bg-red-600 w-3 h-3 rounded-full animate-pulse"></div>
                </div>
            ) : (
                <div className="relative z-10">
                    <div className={`relative w-24 h-24 rounded-full mb-4 ring-2 ring-white/10`}>
                        <img src="https://picsum.photos/100/100?random=99" alt="You" className="w-full h-full rounded-full object-cover" />
                        {muted && (
                            <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-red-500">
                                <MicOff size={16} />
                            </div>
                        )}
                    </div>
                </div>
            )}

            <div className="absolute bottom-4 left-4 z-20">
                <span className="font-bold text-white text-sm bg-black/50 px-3 py-1 rounded-lg backdrop-blur-md">You {muted && '(Muted)'}</span>
            </div>
        </div>

        {/* Remote Participants */}
        {participants.map((user) => {
            return (
              <div key={user.id} className="relative aspect-video bg-[#18181b] rounded-3xl flex flex-col items-center justify-center group overflow-hidden transition-all hover:scale-[1.02] shadow-xl border border-white/5">

                {/* Talking Indicator Glow (Only if not muted and talking) */}
                <div className={`absolute inset-0 bg-green-500/10 transition-opacity duration-300 ${user.isTalking ? 'opacity-100' : 'opacity-0'}`}></div>
                <div className={`absolute bottom-0 left-0 right-0 h-1 bg-green-500 transition-transform duration-100 ${user.isTalking ? 'scale-x-100' : 'scale-x-0'}`}></div>

                {user.isCamOn ? (
                     <div className="absolute inset-0">
                         {/* Fake camera feed images based on ID to be consistent */}
                        <img 
