                            <img src={user.avatar} alt={user.username} className="w-full h-full rounded-full object-cover" />

                            {/* Show MicOff if muted, or Mic if talking. Nothing if idle. */}
                            {user.isMuted && (
                                <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-red-500">
                                    <MicOff size={16} />
                                </div>
                            )}
                            {user.isTalking && !user.isMuted && (
                                <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-green-500">
                                    <Mic size={16} />
                                </div>
                            )}
                        </div>
                    </div>
                )}

                <div className="absolute bottom-4 left-4 z-20 flex flex-col items-start">
                    <span className="font-bold text-white text-sm bg-black/50 px-3 py-1 rounded-lg backdrop-blur-md flex items-center gap-2">
                        {user.username}
                        {user.isMuted && <MicOff size={12} className="text-red-400"/>}
                    </span>
                </div>

                {/* Animated Background Audio Waves (Fake) - Only if no cam */}
                {!user.isCamOn && user.isTalking && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20">
                        <div className="w-32 h-32 rounded-full border-2 border-green-500 animate-ping absolute"></div>
