                <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity z-20">
                    <button className="p-2 bg-black/50 hover:bg-black/80 rounded-full text-white"><MoreHorizontal size={16} /></button>
                </div>
              </div>
            );
        })}

        {/* Empty Placeholder for "Invite" */}
        <div className="aspect-video border-2 border-dashed border-white/10 rounded-3xl flex flex-col items-center justify-center cursor-pointer hover:bg-white/5 hover:border-white/20 transition-all group">
