import React, { useState, useEffect, useRef } from 'react';

export const OwlMascot: React.FC = () => {
  const [error, setError] = useState(false);
  const [eyePosition, setEyePosition] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!containerRef.current) return;

      const { left, top, width, height } = containerRef.current.getBoundingClientRect();
      const centerX = left + width / 2;
      const centerY = top + height / 2;

      const deltaX = e.clientX - centerX;
      const deltaY = e.clientY - centerY;

      // Calculate angle
      const angle = Math.atan2(deltaY, deltaX);

      // Limit movement radius (max pixels the pupil can move from center)
      const maxRadius = 8; 

      // Calculate distance (clamped) to ensure pupil stays within sclera
      const dist = Math.min(Math.hypot(deltaX, deltaY) / 12, maxRadius);

      const x = Math.cos(angle) * dist;
      const y = Math.sin(angle) * dist;

      setEyePosition({ x, y });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div ref={containerRef} className="w-48 h-48 relative mx-auto mb-8 flex items-center justify-center select-none hover:scale-105 transition-transform duration-300">
      {!error ? (
        <div className="relative w-full h-full">
            {/* Base Image */}
            <img 
              src="https://raw.githubusercontent.com/Tarikul-Islam-Anik/Animated-Fluent-Emojis/master/Emojis/Animals/Owl.png" 
              alt="Owl Mascot" 
              onError={() => setError(true)}
              className="w-full h-full object-contain drop-shadow-2xl relative z-10 pointer-events-none"
            />

            {/* Left Eye Container */}
            <div className="absolute top-[32%] left-[23%] w-[22%] h-[22%] bg-white rounded-full z-20 flex items-center justify-center overflow-hidden shadow-inner ring-1 ring-black/5">
                {/* Pupil */}
                <div 
                    className="w-[55%] h-[55%] bg-[#1a1a1a] rounded-full transition-transform duration-75 ease-out shadow-sm"
                    style={{ transform: `translate(${eyePosition.x}px, ${eyePosition.y}px)` }}
                />
                {/* Shine/Reflection */}
                <div className="absolute top-[20%] right-[20%] w-[25%] h-[25%] bg-white rounded-full opacity-90 z-30 pointer-events-none blur-[0.5px]"></div>
            </div>

            {/* Right Eye Container */}
            <div className="absolute top-[32%] right-[23%] w-[22%] h-[22%] bg-white rounded-full z-20 flex items-center justify-center overflow-hidden shadow-inner ring-1 ring-black/5">
                 {/* Pupil */}
                 <div 
                    className="w-[55%] h-[55%] bg-[#1a1a1a] rounded-full transition-transform duration-75 ease-out shadow-sm"
                    style={{ transform: `translate(${eyePosition.x}px, ${eyePosition.y}px)` }}
                />
                {/* Shine/Reflection */}
                <div className="absolute top-[20%] right-[20%] w-[25%] h-[25%] bg-white rounded-full opacity-90 z-30 pointer-events-none blur-[0.5px]"></div>
            </div>
        </div>
      ) : (
        <div className="text-8xl animate-bounce filter drop-shadow-lg cursor-default">🦉</div>
      )}
    </div>
  );
};

