  const messagesEndRef = useRef<HTMLDivElement>(null);
  const dmEndRef = useRef<HTMLDivElement>(null);

  // Determine mode
  const isDM = !!initialFriend;

  const scrollToBottom = () => {
    if (isDM) {
        dmEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    } else {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, dmMessages, typingUsers, isDM]); 

  // Simulate typing activity (Channel Mode)
  useEffect(() => {
    if (isDM) return;

    const interval = setInterval(() => {
      // 30% chance to start typing if no one is typing, or add another typer
      if (Math.random() > 0.7) {
         // Pick random member excluding current user (ID '1')
         const candidates = MEMBERS.filter(m => m.id !== '1' && !typingUsers.includes(m.username));
         if (candidates.length === 0) return;

         const randomMember = candidates[Math.floor(Math.random() * candidates.length)];

         setTypingUsers(prev => [...prev, randomMember.username]);

         // Stop typing after random delay (2-5s)
         setTimeout(() => {
             setTypingUsers(prev => prev.filter(u => u !== randomMember.username));
         }, 2000 + Math.random() * 3000);
      }
    }, 2000);

    return () => clearInterval(interval);
