            const reply: Message = {
                id: (Date.now() + 1).toString(),
                userId: 'dm_friend',
                content: 'Bet! LFG 🚀',
                timestamp: 'Just now'
            };
            setDmMessages(prev => [...prev, reply]);
            new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {});
