        return <div className="text-xs text-[#949ba4]">{boldNames([typingUsers[0]])}, {boldNames([typingUsers[1]])}, and {boldNames([typingUsers[2]])} are typing...</div>;
    }
    return <div className="text-xs text-[#949ba4]">{boldNames([typingUsers[0]])}, {boldNames([typingUsers[1]])}, and {typingUsers.length - 2} others are typing...</div>;
