                                    >
                                        <MessageSquare size={16} />
                                    </button>
                                    <button className="w-9 h-9 rounded-full bg-slate-100 dark:bg-[#1e1f24] flex items-center justify-center text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-200 dark:hover:bg-white/10">
                                        <MoreVertical size={16} />
                                    </button>
