  const [inputValue, setInputValue] = useState('');
  const [typingUsers, setTypingUsers] = useState<string[]>([]);

  // Modal State
  const [showCreateGroup, setShowCreateGroup] = useState(false);
  const [newGroupName, setNewGroupName] = useState('');
  const [newGroupMembers, setNewGroupMembers] = useState<string[]>([]);

  const scrollRef = useRef<HTMLDivElement>(null);

  // Sync props with state
  useEffect(() => {
    if (initialFriend) {
        setActiveMode('DM');
        setSelectedDmUserId(initialFriend.id);
        setSelectedGroupId(null);
    }
  }, [initialFriend]);

  // Scroll to bottom on new message
  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [channelMsgs, dmMsgs, groupMsgs, activeMode, selectedChannelId, selectedDmUserId, selectedGroupId, typingUsers]);

  // --- ALGORITHM: Create Group ---
  const handleCreateGroup = () => {
      if (!newGroupName.trim() || newGroupMembers.length === 0) return;

      const newGroup: GroupChat = {
          id: `g${Date.now()}`,
          name: newGroupName,
          members: ['1', ...newGroupMembers], // Always include self
          iconColor: `bg-${['purple','blue','green','pink','orange'][Math.floor(Math.random()*5)]}-500`,
          unread: 0,
          lastMessage: 'Group created',
          time: 'Now'
      };

      setGroups(prev => [newGroup, ...prev]);
      setShowCreateGroup(false);
      setNewGroupName('');
      setNewGroupMembers([]);

      // Switch to new group
      setActiveMode('GROUP');
      setSelectedGroupId(newGroup.id);
      setSelectedDmUserId(null);
      setGroupMsgs([{ id: 'sys', userId: '1', content: `Created group "${newGroup.name}"`, timestamp: 'Now', type: 'text' }]);
  };

  const toggleGroupMember = (userId: string) => {
      setNewGroupMembers(prev => 
        prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId]
      );
  };

  // --- ALGORITHM: Simulated Real-time Reply ---
  const simulateResponse = (mode: ChatMode, contextId: string | null) => {
      if (mode === 'CHANNEL') return; // Don't simulate channel for now

      let possibleResponders: string[] = [];

      if (mode === 'DM' && selectedDmUserId) {
          possibleResponders = [selectedDmUserId];
      } else if (mode === 'GROUP' && selectedGroupId) {
          const group = groups.find(g => g.id === selectedGroupId);
          if (group) {
              // Get members who are NOT me
              possibleResponders = group.members.filter(id => id !== '1');
          }
      }

      if (possibleResponders.length === 0) return;

      // Determine how many people reply (1 for DM, chance for more in Group)
      const numResponders = (mode === 'GROUP' && possibleResponders.length > 1 && Math.random() > 0.6) 
          ? Math.floor(Math.random() * Math.min(3, possibleResponders.length)) + 1 
          : 1;

      const chosenResponders = possibleResponders.sort(() => 0.5 - Math.random()).slice(0, numResponders);

      chosenResponders.forEach((responderId) => {
          const responderName = USERS[responderId].username;

          // 1. Start Typing Animation (Random delay between 0.5s and 2s to start)
          const typingStartDelay = Math.random() * 1500 + 500;

          setTimeout(() => {
              setTypingUsers(prev => {
                  if (prev.includes(responderName)) return prev;
                  return [...prev, responderName];
              });

              // 2. Stop Typing and Send Message (after 2-4 seconds of typing)
              const typingDuration = Math.random() * 2000 + 2000;

              setTimeout(() => {
                  setTypingUsers(prev => prev.filter(u => u !== responderName));

                  const replies = [
                      "That's crazy!", "For sure.", "Let's gooooo", "ggs", 
                      "Wait, really?", "I'm down.", "LMAO", "check this out",
                      "anyone got a heal?", "rush B don't stop", "bet", "no way", "fr?",
                      "getting on in 5", "invite me"
                  ];
                  const randomContent = replies[Math.floor(Math.random() * replies.length)];

                  const incomingMsg: Message = {
                      id: Date.now().toString() + Math.random().toString(),
                      userId: responderId,
                      content: randomContent,
                      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                      type: 'text'
                  };

                  if (mode === 'DM') setDmMsgs(prev => [...prev, incomingMsg]);
                  else if (mode === 'GROUP') setGroupMsgs(prev => [...prev, incomingMsg]);

                  // Sound
                  new Audio('https://assets.mixkit.co/sfx/preview/mixkit-message-pop-alert-2354.mp3').play().catch(() => {});

              }, typingDuration);

          }, typingStartDelay);
      });
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim()) return;

    const newMessage: Message = {
        id: Date.now().toString(),
        userId: '1', // Current user
        content: inputValue,
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        type: 'text'
    };

    if (activeMode === 'CHANNEL') {
        setChannelMsgs(prev => [...prev, newMessage]);
    } else if (activeMode === 'DM') {
        setDmMsgs(prev => [...prev, newMessage]);
        simulateResponse('DM', selectedDmUserId);
    } else if (activeMode === 'GROUP') {
        setGroupMsgs(prev => [...prev, newMessage]);
        simulateResponse('GROUP', selectedGroupId);
    }

    setInputValue('');
    new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {});
  };

  const getActiveMessages = () => {
      if (activeMode === 'CHANNEL') return channelMsgs;
      if (activeMode === 'GROUP') return groupMsgs;
      return dmMsgs;
  };

  const getTypingText = () => {
      const count = typingUsers.length;
      if (count === 0) return '';
      if (count === 1) return `${typingUsers[0]} is typing...`;
      if (count === 2) return `${typingUsers[0]} and ${typingUsers[1]} are typing...`;
      if (count === 3) return `${typingUsers[0]}, ${typingUsers[1]}, and ${typingUsers[2]} are typing...`;
      return `${typingUsers[0]}, ${typingUsers[1]}, and ${count - 2} others are typing...`;
  };

  return (
    <div className="flex h-full bg-[#09090b] text-white overflow-hidden animate-fadeIn p-4 gap-4 relative">

      {/* --- CREATE GROUP MODAL --- */}
      {showCreateGroup && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm animate-fadeIn">
              <div className="w-96 bg-[#121216] rounded-3xl border border-white/10 shadow-2xl overflow-hidden animate-zoomIn">
                  <div className="p-6 border-b border-white/5 flex justify-between items-center bg-[#18181b]">
                      <h3 className="text-lg font-bold text-white">Create Group Chat</h3>
                      <button onClick={() => setShowCreateGroup(false)} className="text-slate-400 hover:text-white"><X size={20} /></button>
                  </div>
                  <div className="p-6 space-y-4">
                      <div>
                          <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Group Name</label>
                          <input 
                              value={newGroupName}
                              onChange={(e) => setNewGroupName(e.target.value)}
                              placeholder="e.g. Ranked Squad"
                              className="w-full bg-[#09090b] border border-white/10 rounded-xl px-4 py-3 outline-none focus:border-purple-500 transition-colors"
                          />
                      </div>
                      <div>
                          <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Select Members</label>
                          <div className="max-h-48 overflow-y-auto custom-scrollbar space-y-1">
                              {Object.values(USERS).filter(u => u.id !== '1').map(u => (
                                  <div 
                                    key={u.id} 
                                    onClick={() => toggleGroupMember(u.id)}
                                    className={`flex items-center gap-3 p-2 rounded-xl cursor-pointer border transition-all ${newGroupMembers.includes(u.id) ? 'bg-purple-500/10 border-purple-500' : 'bg-transparent border-transparent hover:bg-white/5'}`}
                                  >
                                      <img src={u.avatar} className="w-8 h-8 rounded-full" />
                                      <span className="text-sm font-medium flex-1">{u.username}</span>
                                      {newGroupMembers.includes(u.id) && <CheckCircle2 size={16} className="text-purple-500" />}
                                  </div>
                              ))}
                          </div>
                      </div>
                      <button 
                        onClick={handleCreateGroup}
                        disabled={!newGroupName || newGroupMembers.length === 0}
                        className="w-full py-3 bg-purple-600 hover:bg-purple-500 disabled:bg-slate-700 disabled:cursor-not-allowed text-white font-bold rounded-xl transition-colors"
                      >
                          Create Group
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* --- 1. LEFT SIDEBAR (Floating Card) --- */}
      <div className="w-72 flex flex-col shrink-0 bg-[#121216] rounded-[2rem] border border-white/5 shadow-2xl overflow-hidden">

        {/* Sidebar Header */}
        <div className="p-4 border-b border-white/5 bg-[#18181b]/50">
            <div className="flex bg-[#09090b] p-1 rounded-2xl border border-white/5">
                <button 
                    onClick={() => setActiveMode('CHANNEL')}
                    className={`flex-1 text-xs font-bold py-2.5 rounded-xl transition-all flex items-center justify-center gap-2 ${activeMode === 'CHANNEL' ? 'bg-[#1e1f24] text-white shadow-md' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Hash size={14} /> Channels
                </button>
                <button 
                    onClick={() => setActiveMode('DM')}
                    className={`flex-1 text-xs font-bold py-2.5 rounded-xl transition-all flex items-center justify-center gap-2 ${(activeMode === 'DM' || activeMode === 'GROUP') ? 'bg-[#1e1f24] text-white shadow-md' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Users size={14} /> Messages
                </button>
            </div>
        </div>

        {/* Sidebar List */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-3 space-y-2">

            {activeMode === 'CHANNEL' ? (
                // CHANNEL LIST
                <>
                    {['Lobby', 'Gaming', 'Content'].map(cat => (
                        <div key={cat} className="mb-4">
                            <div className="flex items-center justify-between px-3 mb-2 text-[10px] font-black text-slate-500 uppercase tracking-widest group cursor-pointer hover:text-purple-400 transition-colors">
                                {cat} <Plus size={10} className="opacity-0 group-hover:opacity-100" />
                            </div>
                            <div className="space-y-1">
                                {CHANNELS.filter(c => c.category === cat).map(channel => (
                                    <div 
                                        key={channel.id}
                                        onClick={() => setSelectedChannelId(channel.id)}
                                        className={`group flex items-center justify-between px-3 py-2.5 rounded-xl cursor-pointer transition-all duration-200
                                            ${selectedChannelId === channel.id 
                                                ? 'bg-purple-600 text-white shadow-lg shadow-purple-600/20 translate-x-1' 
                                                : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'}
                                        `}
                                    >
                                        <div className="flex items-center gap-3">
                                            <HashIcon size={16} className={selectedChannelId === channel.id ? 'text-white' : 'text-slate-600 group-hover:text-slate-400'} />
                                            <span className="font-bold text-sm truncate">{channel.name}</span>
                                        </div>
                                        {channel.unread > 0 && selectedChannelId !== channel.id && (
                                            <span className="bg-red-500 text-white text-[10px] font-bold h-5 w-5 flex items-center justify-center rounded-full shadow-sm">{channel.unread}</span>
                                        )}
                                    </div>
                                ))}
                            </div>
                        </div>
                    ))}
                </>
            ) : (
                // DM & GROUP LIST
                <>
                    <div className="relative mb-4 px-1">
                        <Search className="absolute left-4 top-2.5 text-slate-500" size={14} />
                        <input 
                            placeholder="Search..." 
                            className="w-full bg-[#09090b] border border-white/5 rounded-xl py-2 pl-9 pr-4 text-xs font-medium text-slate-200 placeholder-slate-600 focus:outline-none focus:border-purple-500/50 transition-colors"
                        />
                    </div>

                    {/* Groups Section */}
                    <div className="mb-4">
                        <div className="flex items-center justify-between px-3 mb-2 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                             <span>Groups</span>
                             <button onClick={() => setShowCreateGroup(true)} className="hover:text-white transition-colors"><Plus size={12} /></button>
                        </div>
                        {groups.map(group => (
                             <div 
                                key={group.id}
                                onClick={() => { setActiveMode('GROUP'); setSelectedGroupId(group.id); setSelectedDmUserId(null); }}
                                className={`flex items-center gap-3 p-2 rounded-xl cursor-pointer transition-all duration-200
                                    ${(activeMode === 'GROUP' && selectedGroupId === group.id) ? 'bg-white/10' : 'hover:bg-white/5'}
                                `}
                             >
                                <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white font-bold text-xs ${group.iconColor} shadow-md`}>
                                    {group.name.substring(0,2).toUpperCase()}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between items-center">
                                        <span className={`font-bold text-sm truncate ${(selectedGroupId === group.id) ? 'text-white' : 'text-slate-300'}`}>{group.name}</span>
                                    </div>
                                    <p className="text-[10px] text-slate-500 truncate">{group.lastMessage}</p>
                                </div>
                             </div>
                        ))}
                    </div>

                    {/* Direct Messages Section */}
                    <div className="px-3 mb-2 text-[10px] font-black text-slate-500 uppercase tracking-widest">Direct Messages</div>
                    {DM_THREADS.map(thread => {
                        const user = USERS[thread.userId];
                        const isSelected = activeMode === 'DM' && selectedDmUserId === user.id;
                        return (
                            <div 
                                key={thread.id}
                                onClick={() => { setActiveMode('DM'); setSelectedDmUserId(user.id); setSelectedGroupId(null); }}
                                className={`flex items-center gap-3 p-3 rounded-2xl cursor-pointer transition-all duration-200
                                    ${isSelected ? 'bg-gradient-to-br from-purple-900/50 to-blue-900/50 border border-white/10 shadow-lg' : 'hover:bg-white/5 border border-transparent'}
                                `}
                            >
                                <div className="relative">
                                    <img src={user.avatar} className="w-10 h-10 rounded-xl object-cover" />
                                    <div className={`absolute -bottom-1 -right-1 w-3.5 h-3.5 border-2 border-[#121216] rounded-full ${user.status === 'online' ? 'bg-green-500' : 'bg-slate-500'}`}></div>
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between items-center mb-0.5">
                                        <span className={`font-bold text-sm truncate ${isSelected ? 'text-white' : 'text-slate-300'}`}>{user.username}</span>
                                        <span className="text-[10px] text-slate-500">{thread.time}</span>
                                    </div>
                                    <p className={`text-xs truncate ${thread.unread ? 'text-white font-bold' : 'text-slate-500'}`}>
                                        {thread.lastMessage}
                                    </p>
                                </div>
                                {thread.unread > 0 && <div className="w-2 h-2 bg-purple-500 rounded-full"></div>}
                            </div>
                        )
                    })}
                </>
            )}
        </div>

        {/* Sidebar Footer */}
        <div className="p-4 bg-[#09090b]/50 border-t border-white/5 backdrop-blur-md">
             <div className="flex items-center gap-3 p-2 rounded-xl bg-[#1e1f24] border border-white/5 hover:border-white/10 cursor-pointer transition-all group">
                 <div className="relative">
                     <img src={USERS['1'].avatar} className="w-8 h-8 rounded-lg object-cover" />
                     <div className="absolute -bottom-1 -right-1 w-2.5 h-2.5 bg-green-500 border-2 border-[#1e1f24] rounded-full"></div>
                 </div>
                 <div className="flex-1 min-w-0">
                     <div className="font-bold text-xs text-white truncate">{USERS['1'].username}</div>
                     <div className="text-[10px] text-slate-500">Online</div>
                 </div>
                 <Settings size={16} className="text-slate-500 group-hover:text-white transition-colors" />
             </div>
        </div>
      </div>

      {/* --- 2. MAIN CHAT AREA (Floating Card) --- */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#121216] rounded-[2rem] border border-white/5 shadow-2xl overflow-hidden relative">

         {/* Top Bar - Integrated with Content */}
         <div className="h-20 flex items-center justify-between px-8 shrink-0 bg-gradient-to-b from-[#18181b] to-transparent z-10">
            <div className="flex items-center gap-4">
                {activeMode === 'CHANNEL' ? (
                    <>
                        <div className="w-10 h-10 rounded-xl bg-purple-500/10 flex items-center justify-center text-purple-400">
                            <Hash size={20} />
                        </div>
                        <div>
                            <h3 className="font-black text-white text-xl tracking-tight leading-none">{selectedChannelId}</h3>
                            <p className="text-xs font-bold text-slate-500 mt-1 uppercase tracking-wider">Text Channel</p>
                        </div>
                    </>
                ) : activeMode === 'GROUP' && selectedGroupId ? (
                     <>
                        <div className="w-10 h-10 rounded-xl bg-orange-500/10 flex items-center justify-center text-orange-400">
                            <Users size={20} />
                        </div>
                        <div>
                            <h3 className="font-bold text-white text-lg leading-tight">{groups.find(g => g.id === selectedGroupId)?.name}</h3>
                            <p className="text-xs text-slate-500">{groups.find(g => g.id === selectedGroupId)?.members.length} Members</p>
                        </div>
                     </>
                ) : selectedDmUserId ? (
                     <>
                        <div className="relative">
                                <img src={USERS[selectedDmUserId].avatar} className="w-10 h-10 rounded-xl" />
                                <div className={`absolute -bottom-1 -right-1 w-3 h-3 border-2 border-[#18181b] rounded-full ${USERS[selectedDmUserId].status === 'online' ? 'bg-green-500' : 'bg-slate-500'}`}></div>
                        </div>
                        <div>
                                <h3 className="font-bold text-white text-lg leading-tight">{USERS[selectedDmUserId].username}</h3>
                                <p className="text-xs text-slate-500 flex items-center gap-1">
                                    {USERS[selectedDmUserId].status === 'online' ? 'Active Now' : 'Offline'}
                                </p>
                        </div>
                     </>
                ) : null}
            </div>

            <div className="flex items-center gap-1 bg-[#09090b] p-1 rounded-xl border border-white/5">
                <button className="p-2 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white transition-colors"><Phone size={18} /></button>
                <button className="p-2 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white transition-colors"><Video size={18} /></button>
                <div className="w-[1px] h-5 bg-white/10 mx-1"></div>
                <button className="p-2 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white transition-colors"><Search size={18} /></button>
            </div>
         </div>

         {/* Chat History */}
         <div className="flex-1 overflow-y-auto custom-scrollbar px-8 pb-4 space-y-6">
             {/* Dynamic Welcome Message */}
             <div className="py-10 flex flex-col items-center justify-center opacity-60">
                <div className="w-24 h-24 rounded-[2rem] bg-gradient-to-tr from-purple-500/20 to-blue-500/20 flex items-center justify-center mb-6 shadow-[0_0_30px_rgba(168,85,247,0.1)]">
                    {activeMode === 'CHANNEL' ? <Hash size={48} className="text-purple-400" /> : <Gift size={48} className="text-blue-400" />}
                </div>
                <h2 className="text-2xl font-black text-white mb-2">
                    {activeMode === 'CHANNEL' ? '#' + selectedChannelId : activeMode === 'GROUP' ? groups.find(g => g.id === selectedGroupId)?.name : USERS[selectedDmUserId || '2'].username}
                </h2>
                <p className="text-slate-400 text-sm max-w-md text-center">
                    This is the start of your history.
                </p>
             </div>

             {getActiveMessages().map((msg, index, arr) => {
                 const isMe = msg.userId === '1';
                 const user = USERS[msg.userId];
                 const prevMsg = arr[index - 1];
                 const isSequence = prevMsg && prevMsg.userId === msg.userId && (parseInt(msg.id) - parseInt(prevMsg.id) < 600000);

                 // --- RENDER STYLE: CHANNEL (Distinct Cards) ---
                 if (activeMode === 'CHANNEL') {
                     return (
                         <div key={msg.id} className={`group flex gap-4 ${isSequence ? 'mt-1' : 'mt-6'} transition-colors`}>
                             {!isSequence ? (
                                 <div className="flex-shrink-0">
                                    <img src={user.avatar} className="w-10 h-10 rounded-xl cursor-pointer hover:scale-105 transition-transform shadow-sm" />
                                 </div>
                             ) : (
                                 <div className="w-10 text-[10px] text-slate-600 opacity-0 group-hover:opacity-100 text-right self-start pt-1 font-mono">
                                     {msg.timestamp.split(' ')[0]}
                                 </div>
                             )}
                             <div className="flex-1 min-w-0">
                                 {!isSequence && (
                                     <div className="flex items-center gap-2 mb-1">
                                         <span className={`font-bold hover:underline cursor-pointer text-sm ${user.color || 'text-white'}`}>{user.username}</span>
                                         {user.role === 'Admin' && <span className="bg-yellow-500/10 text-yellow-500 px-1.5 py-0.5 rounded text-[10px] font-bold flex items-center gap-1"><Crown size={10} /> ADMIN</span>}
                                         {user.role === 'Mod' && <span className="bg-blue-500/10 text-blue-500 px-1.5 py-0.5 rounded text-[10px] font-bold flex items-center gap-1"><Shield size={10} /> MOD</span>}
                                         <span className="text-xs text-slate-500 ml-1 opacity-60">{msg.timestamp}</span>
                                     </div>
                                 )}
                                 <div className={`text-slate-200 leading-relaxed ${!isSequence ? 'bg-white/[0.03] p-3 rounded-2xl rounded-tl-none inline-block' : ''}`}>
                                     {msg.content}
                                 </div>
                             </div>
                         </div>
                     );
                 } 

                 // --- RENDER STYLE: DM & GROUP (Floating Bubbles) ---
                 else {
                     return (
                         <div key={msg.id} className={`flex w-full ${isMe ? 'justify-end' : 'justify-start'} animate-slideUp`}>
                             {/* Avatar only for them */}
                             {!isMe && !isSequence && (
                                 <img src={user.avatar} className="w-8 h-8 rounded-xl mr-3 self-end mb-1 shadow-sm" title={user.username} />
                             )}
                             {!isMe && isSequence && <div className="w-11" />} {/* Spacer */}

                             <div className="max-w-[75%]">
                                 {!isMe && !isSequence && activeMode === 'GROUP' && (
                                     <div className="text-[10px] text-slate-400 ml-1 mb-1">{user.username}</div>
                                 )}
                                 <div className={`
                                     px-5 py-3 text-[15px] leading-relaxed relative shadow-lg
                                     ${isMe 
                                         ? 'bg-gradient-to-br from-purple-600 to-indigo-600 text-white rounded-2xl rounded-br-sm' 
                                         : 'bg-[#1e1f24] text-slate-200 border border-white/5 rounded-2xl rounded-bl-sm'
                                     }
                                     ${isSequence ? 'mb-1' : 'mb-4'}
                                 `}>
                                     {msg.content}
                                 </div>
                             </div>
                         </div>
                     );
                 }
             })}
             <div ref={scrollRef} />
         </div>

         {/* Floating Input Area */}
         <div className="p-6 relative z-20">
             <div className="bg-[#09090b] rounded-[1.5rem] p-2 border border-white/10 flex flex-col gap-2 shadow-2xl focus-within:border-purple-500/50 focus-within:ring-1 focus-within:ring-purple-500/20 transition-all">
                 <form onSubmit={handleSendMessage} className="flex items-center gap-2">
                     <button type="button" className="p-3 text-slate-400 hover:text-white hover:bg-white/10 rounded-full transition-colors">
                         <Plus size={20} />
                     </button>
                     <input 
                        value={inputValue}
                        onChange={(e) => setInputValue(e.target.value)}
                        placeholder={`Message ${activeMode === 'CHANNEL' ? '#' + selectedChannelId : activeMode === 'GROUP' ? groups.find(g => g.id === selectedGroupId)?.name : USERS[selectedDmUserId || '2'].username}`}
                        className="flex-1 bg-transparent text-slate-200 placeholder-slate-600 outline-none font-medium px-2 py-3"
                     />
                     <div className="flex items-center gap-2 pr-2">
                        {!inputValue && (
                             <>
                                <button type="button" className="p-2 text-slate-400 hover:text-white hover:bg-white/10 rounded-xl transition-colors"><Gift size={20} /></button>
                                <button type="button" className="p-2 text-slate-400 hover:text-white hover:bg-white/10 rounded-xl transition-colors"><Sticker size={20} /></button>
                             </>
                        )}
                        <button type="submit" className={`p-2.5 rounded-xl transition-all ${inputValue ? 'bg-purple-600 text-white shadow-lg hover:bg-purple-500' : 'bg-white/5 text-slate-500'}`}>
                            {inputValue ? <ArrowUp size={20} strokeWidth={3} /> : <Mic size={20} />}
                        </button>
                     </div>
                 </form>
             </div>

             {/* Dynamic Typing Indicator */}
             <div className="absolute top-1 left-8 h-5 flex items-center pointer-events-none">
                 {typingUsers.length > 0 && (
                     <div className="flex items-center gap-2 text-[10px] font-bold text-purple-400 bg-purple-500/10 px-3 py-1 rounded-full animate-fadeIn transition-all">
                         <div className="flex gap-1">
                             <div className="w-1 h-1 bg-purple-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                             <div className="w-1 h-1 bg-purple-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                             <div className="w-1 h-1 bg-purple-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                         </div>
                         <span>{getTypingText()}</span>
                     </div>
                 )}
             </div>
         </div>
      </div>

      {/* --- 3. RIGHT SIDEBAR (Floating Card) --- */}
      <div className="w-64 bg-[#121216] rounded-[2rem] border border-white/5 hidden xl:flex flex-col shrink-0 shadow-2xl overflow-hidden">
         {activeMode === 'CHANNEL' ? (
             // CHANNEL MEMBERS
             <>
                <div className="p-4 border-b border-white/5 bg-[#18181b]/30">
                    <h3 className="font-black text-slate-400 text-xs uppercase tracking-widest">Members — 12</h3>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
                    {['Admin', 'Mod', 'Member'].map(role => {
                         const roleMembers = Object.values(USERS).filter(u => u.role === role);
                         if (!roleMembers.length) return null;
                         return (
                             <div key={role}>
                                 <h4 className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-3 pl-1 flex items-center gap-1">
                                     {role} {role === 'Admin' && <Crown size={10} />}
                                 </h4>
                                 <div className="space-y-2">
                                    {roleMembers.map(u => (
                                        <div key={u.id} className="flex items-center gap-3 p-2 rounded-xl hover:bg-white/5 cursor-pointer opacity-80 hover:opacity-100 transition-all group">
                                            <div className="relative">
                                                <img src={u.avatar} className="w-9 h-9 rounded-xl object-cover" />
                                                <div className={`absolute -bottom-1 -right-1 w-3 h-3 border-2 border-[#121216] rounded-full ${u.status === 'online' ? 'bg-green-500' : 'bg-slate-500'}`}></div>
                                            </div>
                                            <div>
                                                <div className={`text-sm font-bold ${u.color || 'text-slate-300'}`}>{u.username}</div>
                                                <div className="text-[10px] text-slate-500">{u.status === 'online' ? 'Playing Valo' : 'Offline'}</div>
                                            </div>
                                        </div>
                                    ))}
                                 </div>
                             </div>
                         )
                    })}
                </div>
             </>
         ) : (
             // DM/GROUP DETAILS
             <>
                {(selectedDmUserId || selectedGroupId) && (
                    <div className="flex flex-col h-full">
                        <div className="p-6 flex flex-col items-center bg-gradient-to-b from-[#1e1f24] to-transparent">
                            {selectedDmUserId ? (
                                <>
                                    <div className="relative mb-4 group cursor-pointer">
                                        <img src={USERS[selectedDmUserId].avatar} className="w-24 h-24 rounded-[1.5rem] shadow-2xl" />
                                    </div>
                                    <h2 className="text-xl font-black text-white">{USERS[selectedDmUserId].username}</h2>
                                    <p className="text-slate-500 font-medium text-xs">@{USERS[selectedDmUserId].username.toLowerCase()}</p>
                                </>
                            ) : (
                                <>
                                    <div className={`w-24 h-24 rounded-[1.5rem] shadow-2xl flex items-center justify-center text-4xl font-bold text-white mb-4 ${groups.find(g => g.id === selectedGroupId)?.iconColor}`}>
                                        {groups.find(g => g.id === selectedGroupId)?.name.substring(0,2).toUpperCase()}
                                    </div>
                                    <h2 className="text-xl font-black text-white text-center">{groups.find(g => g.id === selectedGroupId)?.name}</h2>
                                    <p className="text-slate-500 font-medium text-xs">Group Chat</p>
                                </>
                            )}

                            <div className="flex gap-2 mt-6 w-full">
                                <button className="flex-1 bg-white/5 hover:bg-white/10 py-2.5 rounded-xl text-xs font-bold transition-colors border border-white/5">Files</button>
                                <button className="flex-1 bg-white/5 hover:bg-white/10 py-2.5 rounded-xl text-xs font-bold transition-colors border border-white/5">Settings</button>
                            </div>
                        </div>

                        {activeMode === 'GROUP' && selectedGroupId && (
                            <div className="flex-1 overflow-y-auto p-4">
                                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3">Group Members</h4>
                                <div className="space-y-2">
                                    {groups.find(g => g.id === selectedGroupId)?.members.map(memberId => (
                                        <div key={memberId} className="flex items-center gap-3 p-2 rounded-xl hover:bg-white/5">
                                            <img src={USERS[memberId].avatar} className="w-8 h-8 rounded-full" />
                                            <span className="text-sm font-bold text-slate-300">{USERS[memberId].username}</span>
                                            {memberId === '1' && <span className="text-[10px] bg-white/10 px-2 py-0.5 rounded text-slate-400">You</span>}
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {activeMode === 'DM' && (
                             <div className="flex-1 overflow-y-auto p-4 space-y-6">
                                <div>
                                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3">Shared Media</h4>
                                    <div className="grid grid-cols-3 gap-2">
                                        {[1,2,3].map(i => (
                                            <div key={i} className="aspect-square rounded-lg bg-white/5 overflow-hidden border border-white/5">
                                                <img src={`https://picsum.photos/100/100?random=${i + 200}`} className="w-full h-full object-cover" />
                                            </div>
                                        ))}
                                    </div>
                                </div>
                             </div>
                        )}
                    </div>
                )}
             </>
         )}
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background-color: #27272a;
          border-radius: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background-color: transparent;
        }
        @keyframes slideUp {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-slideUp {
            animation: slideUp 0.3s ease-out forwards;
        }
        @keyframes zoomIn {
             from { opacity: 0; transform: scale(0.9); }
             to { opacity: 1; transform: scale(1); }
        }
        .animate-zoomIn {
             animation: zoomIn 0.2s cubic-bezier(0.16, 1, 0.3, 1);
        }
        @keyframes fadeIn {
            from { opacity: 0; }
            to { opacity: 1; }
        }
        .animate-fadeIn {
            animation: fadeIn 0.2s ease-out;
        }
      `}</style>
    </div>
  );
};

