```typescript
const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setCropState(prev => ({
      ...prev,
      x: e.clientX - dragStart.current.x,
      y: e.clientY - dragStart.current.y
    }));
  };

  const handleMouseUp = () => setIsDragging(false);

  const handleSaveCrop = () => {
    // 1. Create a canvas
    const canvas = document.createElement('canvas');
    const size = 300; // Output Resolution
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');

    if (ctx && imgRef.current) {
        // 2. Draw background
        ctx.fillStyle = '#121216';
        ctx.fillRect(0, 0, size, size);

        // 3. Transform context to match user interaction
        // Center the coordinate system
        ctx.translate(size / 2, size / 2);
        // Apply user's pan
        ctx.translate(cropState.x, cropState.y);
        // Apply user's zoom
        ctx.scale(cropState.zoom, cropState.zoom);

        // 4. Draw image centered
        const img = imgRef.current;
        // Calculate the position to center the image
        const imgWidth = img.naturalWidth * cropState.zoom;
        const imgHeight = img.naturalHeight * cropState.zoom;
        const x = -imgWidth / 2;
        const y = -imgHeight / 2;
        ctx.drawImage(img, x, y, imgWidth, imgHeight);

        // 5. Convert to data url and preview
        const dataUrl = canvas.toDataURL('image/png');
        setPreview(dataUrl);
    }
  };

