        </div>

        {/* Remote Participants */}
        {participants.map((user) => {
            const isSpeaking = user.isTalking && !user.isMuted;

            return (
              <div key={user.id} className={`relative aspect-video bg-[#18181b] rounded-3xl flex flex-col items-center justify-center group overflow-hidden transition-all hover:scale-[1.02] shadow-xl border-2 ${isSpeaking ? 'border-green-500 shadow-[0_0_20px_rgba(34,197,94,0.2)]' : 'border-transparent border-white/5'}`}>

                {/* Talking Indicator Glow (Only if not muted and talking) */}
                <div className={`absolute inset-0 bg-green-500/10 transition-opacity duration-300 ${isSpeaking ? 'opacity-100' : 'opacity-0'}`}></div>
