                     return (
                         <div key={msg.id} className={`flex w-full ${isMe ? 'justify-end' : 'justify-start'} ${isSequence ? 'mt-0.5' : 'mt-3'}`}>
                             {!isMe && !isSequence && <img src={user.avatar} className="w-8 h-8 rounded-full mr-2 self-end mb-1" />}
