                     );
                 }
             })}
         </div>

         {/* Scroll Down Button */}
         {showScrollButton && (
            <button onClick={() => scrollToBottom(true)} className="absolute bottom-20 right-4 z-20 p-3 bg-[#1e1f24] text-white rounded-full shadow-lg border border-white/10">
