                    <div className="flex-1 overflow-y-auto p-2 grid grid-cols-2 gap-2">
                        {filteredGifs.map(gif => (<div key={gif.id} onClick={() => handleGifSelect(gif.url)} className="aspect-video rounded overflow-hidden cursor-pointer"><img src={gif.url} className="w-full h-full object-cover" /></div>))}
                    </div>
                </div>
             )}

             {/* Typing Indicator */}
             {typingUsers.length > 0 && <div className="text-[10px] text-purple-400 font-bold mb-1 pl-4 animate-pulse">{getTypingText()}</div>}

             <div className="bg-[#1e1f24] rounded-2xl flex items-center p-1 border border-white/5">
                 <button onClick={() => fileInputRef.current?.click()} className="p-2 text-slate-400"><Paperclip size={20} /></button>
                 <button onClick={() => setShowGifPicker(!showGifPicker)} className="p-2 text-slate-400"><FileVideo size={20} /></button>
