                 <form onSubmit={handleSendMessage} className="flex-1 flex items-center">
                    <input value={inputValue} onChange={(e) => setInputValue(e.target.value)} placeholder="Message..." className="flex-1 bg-transparent text-white placeholder-slate-500 px-2 py-2 outline-none" />
