    bgm.loop = true;

    // Attempt playback (requires previous user interaction with document to work automatically)
    const playPromise = bgm.play();
    if (playPromise !== undefined) {
        playPromise.catch(e => {
            console.log("Audio autoplay blocked by browser policy (user interaction needed).", e);
        });
    }

    return () => {
        bgm.pause();
        bgm.currentTime = 0;
    };
