  const [showGroupSettings, setShowGroupSettings] = useState(false);
  const [editingGroup, setEditingGroup] = useState<{name: string, color: string} | null>(null);
  const [showRightSidebar, setShowRightSidebar] = useState(false);

  // Scrolling Logic
  const chatContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isAtBottomRef = useRef(true);
  const prevMessagesLengthRef = useRef(0);
  const typingTimeoutsRef = useRef<Record<string, any>>({});

  const getActiveMessages = () => {
      if (activeMode === 'CHANNEL') return channelMsgs;
      if (activeMode === 'GROUP') return groupMsgs;
      return dmMsgs;
  };

  const scrollToBottom = (smooth = true) => {
    if (chatContainerRef.current) {
        chatContainerRef.current.scrollTo({
            top: chatContainerRef.current.scrollHeight,
            behavior: smooth ? 'smooth' : 'auto'
        });
        if (!smooth) {
            setShowScrollButton(false);
            isAtBottomRef.current = true;
        }
    }
  };

  const handleScroll = () => {
    if (chatContainerRef.current) {
        const { scrollTop, scrollHeight, clientHeight } = chatContainerRef.current;
        const distanceToBottom = scrollHeight - scrollTop - clientHeight;
        // Using 100px threshold to determine if user is "at bottom"
        const isBottom = Math.abs(distanceToBottom) < 100;

        isAtBottomRef.current = isBottom;
        setShowScrollButton(!isBottom);
    }
  };

  // Sync props with state
  useEffect(() => {
    if (initialFriend) {
        setActiveMode('DM');
        setSelectedDmUserId(initialFriend.id);
        setSelectedGroupId(null);
        setIsMobileChatOpen(true);
    }
  }, [initialFriend]);

  // Effect: Scroll to bottom instantly when switching views
  useEffect(() => {
      scrollToBottom(false);
      isAtBottomRef.current = true;
      setShowScrollButton(false);
      // Reset length tracker on view switch so we don't skip logic
      prevMessagesLengthRef.current = getActiveMessages().length;

      // Clear typing users on switch
      setTypingUsers([]);
      Object.values(typingTimeoutsRef.current).forEach((t: any) => clearTimeout(t));
      typingTimeoutsRef.current = {};
  }, [activeMode, selectedChannelId, selectedDmUserId, selectedGroupId]);

  // Effect: Auto-scroll on new messages if at bottom or if message is from me
  useEffect(() => {
      const messages = getActiveMessages();

      // Only trigger if message count increased
      if (messages.length > prevMessagesLengthRef.current) {
          const lastMsg = messages[messages.length - 1];
          const isMyMessage = lastMsg?.userId === '1';

          if (isAtBottomRef.current || isMyMessage) {
              scrollToBottom(true);
          }
      }

      prevMessagesLengthRef.current = messages.length;
  }, [channelMsgs, dmMsgs, groupMsgs]); 

  // Cleanup timeouts on unmount
  useEffect(() => {
      return () => {
          Object.values(typingTimeoutsRef.current).forEach((t: any) => clearTimeout(t));
      };
  }, []);

  const handleOpenChat = (mode: ChatMode, id: string) => {
      setActiveMode(mode);
      if (mode === 'CHANNEL') setSelectedChannelId(id);
      else if (mode === 'DM') { setSelectedDmUserId(id); setSelectedGroupId(null); }
      else if (mode === 'GROUP') { setSelectedGroupId(id); setSelectedDmUserId(null); }

      setIsMobileChatOpen(true);
  };

  const handleBackToList = () => {
      setIsMobileChatOpen(false);
      if (onClearFriend) onClearFriend();
  };

  const handleCreateGroup = () => {
      if (!newGroupName.trim() || newGroupMembers.length === 0) return;
      const newGroup: GroupChat = { id: `g${Date.now()}`, name: newGroupName, members: ['1', ...newGroupMembers], iconColor: `bg-${['purple','blue','green','pink','orange'][Math.floor(Math.random()*5)]}-500`, unread: 0, lastMessage: 'Group created', time: 'Now' };
      setGroups(prev => [newGroup, ...prev]);
      setShowCreateGroup(false); setNewGroupName(''); setNewGroupMembers([]);
      handleOpenChat('GROUP', newGroup.id);
      setGroupMsgs([{ id: 'sys', userId: '1', content: `Created group "${newGroup.name}"`, timestamp: 'Now', type: 'text' }]);
  };
  const toggleGroupMember = (userId: string) => setNewGroupMembers(prev => prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId]);
  const handleOpenGroupSettings = () => { const group = groups.find(g => g.id === selectedGroupId); if (group) { setEditingGroup({ name: group.name, color: group.iconColor }); setShowGroupSettings(true); } };
  const handleUpdateGroup = () => { if (!selectedGroupId || !editingGroup || !editingGroup.name.trim()) return; setGroups(prev => prev.map(g => { if (g.id === selectedGroupId) return { ...g, name: editingGroup.name, iconColor: editingGroup.color }; return g; })); setShowGroupSettings(false); };

  const simulateResponse = (mode: ChatMode, contextId: string | null) => {
      if (mode === 'CHANNEL') return;
      let possibleResponders: string[] = [];
      if (mode === 'DM' && selectedDmUserId) possibleResponders = [selectedDmUserId];
      else if (mode === 'GROUP' && selectedGroupId) { const group = groups.find(g => g.id === selectedGroupId); if (group) possibleResponders = group.members.filter(id => id !== '1'); }
      if (possibleResponders.length === 0) return;
      const numResponders = (mode === 'GROUP' && possibleResponders.length > 1 && Math.random() > 0.6) ? Math.floor(Math.random() * Math.min(3, possibleResponders.length)) + 1 : 1;
      const chosenResponders = possibleResponders.sort(() => 0.5 - Math.random()).slice(0, numResponders);
      chosenResponders.forEach((responderId) => {
          const responderName = USERS[responderId].username;
          setTimeout(() => {
              // Only start typing if not already
              setTypingUsers(prev => prev.includes(responderName) ? prev : [...prev, responderName]);
              setTimeout(() => {
                  setTypingUsers(prev => prev.filter(u => u !== responderName));
                  const replies = ["That's crazy!", "For sure.", "Let's gooooo", "ggs", "Wait, really?", "I'm down.", "LMAO", "check this out", "anyone got a heal?", "rush B don't stop", "bet", "no way", "fr?", "getting on in 5", "invite me"];
                  const incomingMsg: Message = { id: Date.now().toString() + Math.random().toString(), userId: responderId, content: replies[Math.floor(Math.random() * replies.length)], timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), type: 'text' };
                  if (mode === 'DM') setDmMsgs(prev => [...prev, incomingMsg]); else if (mode === 'GROUP') setGroupMsgs(prev => [...prev, incomingMsg]);
                  new Audio('https://assets.mixkit.co/sfx/preview/mixkit-message-pop-alert-2354.mp3').play().catch(() => {});
              }, Math.random() * 2000 + 2000);
          }, Math.random() * 1500 + 500);
      });
  };

  const handleTypingSimulation = () => {
    // Logic to pick candidates to "start typing" when the user interacts
    let candidates: string[] = [];
    if (activeMode === 'CHANNEL') {
        candidates = Object.values(USERS).filter(u => u.id !== '1').map(u => u.username);
    } else if (activeMode === 'DM' && selectedDmUserId) {
        candidates = [USERS[selectedDmUserId].username];
    } else if (activeMode === 'GROUP' && selectedGroupId) {
        const group = groups.find(g => g.id === selectedGroupId);
        if (group) {
            candidates = group.members.filter(id => id !== '1').map(id => USERS[id].username);
        }
    }

    if (candidates.length === 0) return;

    // Chance to trigger typing from another user
    if (Math.random() < 0.4) {
        const typer = candidates[Math.floor(Math.random() * candidates.length)];

        if (!typingUsers.includes(typer)) {
            setTypingUsers(prev => [...prev, typer]);

            // Auto-remove after a few seconds of "inactivity"
            const timeout = setTimeout(() => {
                setTypingUsers(prev => prev.filter(u => u !== typer));
                delete typingTimeoutsRef.current[typer];
            }, 3000 + Math.random() * 3000);

            // Clear existing if necessary (though the check above handles basic duplication)
            if (typingTimeoutsRef.current[typer]) clearTimeout(typingTimeoutsRef.current[typer]);
            typingTimeoutsRef.current[typer] = timeout;
        }
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(e.target.value);
    if (e.target.value.trim().length > 0) {
        handleTypingSimulation();
    }
  };

  const handleSendMessage = (e: React.FormEvent) => { e.preventDefault(); if (!inputValue.trim()) return; const newMessage: Message = { id: Date.now().toString(), userId: '1', content: inputValue, timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), type: 'text' }; if (activeMode === 'CHANNEL') setChannelMsgs(prev => [...prev, newMessage]); else if (activeMode === 'DM') { setDmMsgs(prev => [...prev, newMessage]); simulateResponse('DM', selectedDmUserId); } else if (activeMode === 'GROUP') { setGroupMsgs(prev => [...prev, newMessage]); simulateResponse('GROUP', selectedGroupId); } setInputValue(''); new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {}); };
  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files && e.target.files[0]) { const url = URL.createObjectURL(e.target.files[0]); const newMessage: Message = { id: Date.now().toString(), userId: '1', content: url, timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), type: 'image' }; if (activeMode === 'CHANNEL') setChannelMsgs(prev => [...prev, newMessage]); else if (activeMode === 'DM') { setDmMsgs(prev => [...prev, newMessage]); simulateResponse('DM', selectedDmUserId); } else if (activeMode === 'GROUP') { setGroupMsgs(prev => [...prev, newMessage]); simulateResponse('GROUP', selectedGroupId); } new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {}); if (fileInputRef.current) fileInputRef.current.value = ''; } };
