const INITIAL_USERS = [
  { id: '1', username: 'Nelly', avatar: 'https://picsum.photos/100/100?random=10', status: 'online' },
  { id: '2', username: 'Mallow', avatar: 'https://picsum.photos/100/100?random=11', status: 'online' },
