                <div className={`absolute inset-0 bg-green-500/10 transition-opacity duration-300 ${isSpeaking ? 'opacity-100' : 'opacity-0'}`}></div>
                <div className={`absolute bottom-0 left-0 right-0 h-1 bg-green-500 transition-transform duration-100 ${isSpeaking ? 'scale-x-100' : 'scale-x-0'}`}></div>

                {user.isCamOn ? (
                     <div className="absolute inset-0">
                         {/* Fake camera feed images based on ID to be consistent */}
                        <img 
                            src={`https://images.unsplash.com/photo-${user.id === '1' ? '1534528741775-53994a69daeb' : user.id === '2' ? '1506794778202-cad84cf45f1d' : '1531427186611-ecfd6d936c79'}?auto=format&fit=crop&q=80&w=800`} 
                            className="w-full h-full object-cover opacity-90" 
                            alt="Cam" 
                        />
                     </div>
                ) : (
