                            {/* Status Indicator */}
                            <div className={`absolute bottom-1 right-1 w-6 h-6 rounded-full border-4 border-[#18181b] ${getStatusColor(user.status)} z-10`}></div>

                            {/* Show MicOff if muted, or Mic if talking. */}
                            {user.isMuted && (
                                <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-red-500 z-20">
                                    <MicOff size={16} />
                                </div>
                            )}
                            {isSpeaking && (
                                <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-green-500 z-20">
                                    <Mic size={16} />
                                </div>
                            )}
                        </div>
                    </div>
                )}

                <div className="absolute bottom-4 left-4 z-20 flex flex-col items-start">
                    <span className="font-bold text-white text-sm bg-black/50 px-3 py-1 rounded-lg backdrop-blur-md flex items-center gap-2">
                        {user.username}
                        {user.isMuted && <MicOff size={12} className="text-red-400"/>}
                    </span>
                </div>

                {/* Animated Background Audio Waves (Fake) - Only if no cam */}
                {!user.isCamOn && isSpeaking && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20">
                        <div className="w-32 h-32 rounded-full border-2 border-green-500 animate-ping absolute"></div>
                        <div className="w-40 h-40 rounded-full border border-green-500 animate-ping animation-delay-500 absolute"></div>
                    </div>
                )}

                <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity z-20">
                    <button className="p-2 bg-black/50 hover:bg-black/80 rounded-full text-white"><MoreHorizontal size={16} /></button>
                </div>
              </div>
            );
        })}

        {/* Invite to Call Button */}
        <div 
            onClick={() => setShowInviteModal(true)}
            className="aspect-video border-2 border-dashed border-white/10 rounded-3xl flex flex-col items-center justify-center cursor-pointer hover:bg-white/5 hover:border-white/20 transition-all group active:scale-95"
        >
            <div className="w-16 h-16 rounded-full bg-white/5 group-hover:bg-white/10 flex items-center justify-center mb-3 transition-colors">
                <UserPlus size={32} className="text-slate-500 group-hover:text-purple-400" />
            </div>
            <span className="text-slate-500 font-bold group-hover:text-white transition-colors">Invite to Call</span>
        </div>
      </div>

      {/* Bottom Controls */}
      <div className="h-24 bg-[#121215]/90 backdrop-blur-xl flex items-center justify-center px-8 border-t border-white/5 relative z-20">

        <div className="absolute left-8 flex items-center gap-4">
             <div className="relative">
                <img src="https://picsum.photos/50/50?random=99" className="w-12 h-12 rounded-2xl border border-white/10" />
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-[#121215]"></div>
             </div>
             <div className="hidden md:block">
                 <div className="font-bold text-white">You</div>
                 <div className="text-xs text-slate-400">Connected</div>
             </div>
        </div>

        <div className="flex items-center gap-4">
            <button 
                onClick={toggleMute} 
                className={`w-14 h-14 rounded-[20px] flex items-center justify-center transition-all duration-300 hover:scale-110 shadow-lg
                ${muted ? 'bg-red-500 text-white shadow-red-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}>
                {muted ? <MicOff size={24} /> : <Mic size={24} />}
            </button>
            <button 
                onClick={() => setDeafened(!deafened)} 
                className={`w-14 h-14 rounded-[20px] flex items-center justify-center transition-all duration-300 hover:scale-110 shadow-lg
                ${deafened ? 'bg-red-500 text-white shadow-red-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}>
                {deafened ? <Volume2 size={24} className="opacity-50" /> : <Headphones size={24} />}
            </button>
            <button 
                onClick={() => setCamera(!camera)} 
                className={`w-14 h-14 rounded-[20px] flex items-center justify-center transition-all duration-300 hover:scale-110 shadow-lg
                ${camera ? 'bg-green-500 text-white shadow-green-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}>
                {camera ? <Video size={24} /> : <VideoOff size={24} />}
            </button>
            <button 
                onClick={() => setSharing(!sharing)} 
                className={`w-14 h-14 rounded-[20px] flex items-center justify-center transition-all duration-300 hover:scale-110 shadow-lg
                ${sharing ? 'bg-blue-500 text-white shadow-blue-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}>
                <Monitor size={24} />
            </button>

             <div className="w-[1px] h-8 bg-white/10 mx-2"></div>

             <button 
                className="w-14 h-14 bg-red-600 hover:bg-red-700 rounded-[20px] text-white shadow-lg shadow-red-600/30 flex items-center justify-center hover:scale-110 transition-transform" 
                onClick={handleLeaveCall}
             >
                <PhoneOff size={24} />
             </button>
        </div>

        <div className="absolute right-8 hidden md:flex items-center gap-4">
             <button className="p-3 bg-white/5 hover:bg-white/10 rounded-xl text-slate-400 hover:text-white transition-colors">
                <Settings size={20} />
             </button>
        </div>
      </div>

      <style>{`
          .animation-delay-500 {
              animation-delay: 0.5s;
          }
          @keyframes zoomIn {
            from { opacity: 0; transform: scale(0.95); }
            to { opacity: 1; transform: scale(1); }
          }
          .animate-zoomIn {
            animation: zoomIn 0.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
          }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { LayoutDashboard, MessageSquare, Video, Gamepad2, Settings, LogOut, Bell, Search, Mic, Heart, Trophy, UserPlus, Gamepad, Users, BarChart2, Home, Menu } from 'lucide-react';
import { ViewState, User } from './types';
import { LoginView } from './views/Login';
import { StatsDashboard } from './views/StatsDashboard';
import { VoiceChat } from './views/VoiceChat';
import { TasksView } from './views/Tasks';
import { SettingsView } from './views/Settings';
import { FriendsView } from './views/Friends';
import { BrowseView } from './views/Browse';
import { HomeView } from './views/Home';
import { ChatView } from './views/Chat';

// --- Bottom Nav Component ---
const BottomNavItem = ({ icon: Icon, active, onClick, badge, label }: any) => (
  <button
    onClick={onClick}
    className={`flex flex-col items-center justify-center w-full py-3 gap-1 transition-all duration-300 relative
      ${active ? 'text-purple-500' : 'text-slate-500 hover:text-slate-300'}
    `}
  >
    <div className={`relative p-1 rounded-xl transition-all ${active ? 'bg-purple-500/10' : ''}`}>
        <Icon size={24} strokeWidth={active ? 2.5 : 2} className={`transition-transform duration-200 ${active ? 'scale-110' : ''}`} />
        {badge && (
        <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 border-2 border-[#121216] text-white text-[9px] font-bold flex items-center justify-center rounded-full animate-bounce">
            {badge}
        </span>
        )}
    </div>
    <span className={`text-[10px] font-medium ${active ? 'opacity-100' : 'opacity-0 hidden'}`}>{label}</span>
