    { id: '6', url: 'https://media.tenor.com/925_5l_7s70AAAAC/pepe-smoke.gif', title: 'Pepe' },
    { id: '7', url: 'https://media.tenor.com/Isn2q2k60w0AAAAC/cat-meme.gif', title: 'Cat Meme' },
    { id: '8', url: 'https://media.tenor.com/5a7USwwtZt8AAAAC/thumbs-up.gif', title: 'Thumbs Up' },
];

interface ChatViewProps {
    initialFriend?: User | null;
    onClearFriend?: () => void;
    onNavigate?: (view: ViewState) => void;
}

export const ChatView: React.FC<ChatViewProps> = ({ initialFriend, onClearFriend, onNavigate }) => {
  // State
  const [activeMode, setActiveMode] = useState<ChatMode>(initialFriend ? 'DM' : 'CHANNEL');
  const [selectedChannelId, setSelectedChannelId] = useState('general');
  const [selectedDmUserId, setSelectedDmUserId] = useState<string | null>(initialFriend?.id || null);
  const [selectedGroupId, setSelectedGroupId] = useState<string | null>(null);
  const [viewingUserProfileId, setViewingUserProfileId] = useState<string | null>(null);

  // Mobile View State: null means showing list, value means showing chat
  const [isMobileChatOpen, setIsMobileChatOpen] = useState(!!initialFriend);

  const [channelMsgs, setChannelMsgs] = useState(CHANNEL_MESSAGES);
  const [dmMsgs, setDmMsgs] = useState(DIRECT_MESSAGES);
  const [groupMsgs, setGroupMsgs] = useState(GROUP_MESSAGES);

  const [groups, setGroups] = useState<GroupChat[]>(INITIAL_GROUPS);

  // UI State
  const [inputValue, setInputValue] = useState('');
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const [showScrollButton, setShowScrollButton] = useState(false);

  // GIF Picker State
  const [showGifPicker, setShowGifPicker] = useState(false);
  const [gifSearch, setGifSearch] = useState('');

  // Modal State
  const [showCreateGroup, setShowCreateGroup] = useState(false);
  const [newGroupName, setNewGroupName] = useState('');
  const [newGroupMembers, setNewGroupMembers] = useState<string[]>([]);

  // Group Settings Modal State
  const [showGroupSettings, setShowGroupSettings] = useState(false);
  const [editingGroup, setEditingGroup] = useState<{name: string, color: string} | null>(null);
  const [showRightSidebar, setShowRightSidebar] = useState(false);

  // Scrolling Logic
  const chatContainerRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isAtBottomRef = useRef(true);
  const prevMessagesLengthRef = useRef(0);
  const typingTimeoutsRef = useRef<Record<string, any>>({});

  const getActiveMessages = () => {
      if (activeMode === 'CHANNEL') return channelMsgs;
      if (activeMode === 'GROUP') return groupMsgs;
      return dmMsgs;
  };

  const scrollToBottom = (smooth = true) => {
    if (chatContainerRef.current) {
        chatContainerRef.current.scrollTo({
            top: chatContainerRef.current.scrollHeight,
            behavior: smooth ? 'smooth' : 'auto'
        });
        if (!smooth) {
            setShowScrollButton(false);
            isAtBottomRef.current = true;
        }
    }
  };

  const handleScroll = () => {
    if (chatContainerRef.current) {
        const { scrollTop, scrollHeight, clientHeight } = chatContainerRef.current;
        const distanceToBottom = scrollHeight - scrollTop - clientHeight;
        // Using 100px threshold to determine if user is "at bottom"
        const isBottom = Math.abs(distanceToBottom) < 100;

        isAtBottomRef.current = isBottom;
        setShowScrollButton(!isBottom);
    }
  };

  // Sync props with state
  useEffect(() => {
    if (initialFriend) {
        setActiveMode('DM');
        setSelectedDmUserId(initialFriend.id);
        setSelectedGroupId(null);
        setIsMobileChatOpen(true);
    }
  }, [initialFriend]);

  // Effect: Scroll to bottom instantly when switching views
  useEffect(() => {
      scrollToBottom(false);
      isAtBottomRef.current = true;
      setShowScrollButton(false);
      // Reset length tracker on view switch so we don't skip logic
      prevMessagesLengthRef.current = getActiveMessages().length;

      // Clear typing users on switch
      setTypingUsers([]);
      Object.values(typingTimeoutsRef.current).forEach((t: any) => clearTimeout(t));
      typingTimeoutsRef.current = {};
  }, [activeMode, selectedChannelId, selectedDmUserId, selectedGroupId]);

  // Effect: Auto-scroll on new messages if at bottom or if message is from me
  useEffect(() => {
      const messages = getActiveMessages();

      // Only trigger if message count increased
      if (messages.length > prevMessagesLengthRef.current) {
          const lastMsg = messages[messages.length - 1];
          const isMyMessage = lastMsg?.userId === '1';

          if (isAtBottomRef.current || isMyMessage) {
              scrollToBottom(true);
          }
      }

      prevMessagesLengthRef.current = messages.length;
  }, [channelMsgs, dmMsgs, groupMsgs]); 

  // Cleanup timeouts on unmount
  useEffect(() => {
      return () => {
          Object.values(typingTimeoutsRef.current).forEach((t: any) => clearTimeout(t));
      };
  }, []);

  const handleOpenChat = (mode: ChatMode, id: string) => {
      setActiveMode(mode);
      if (mode === 'CHANNEL') setSelectedChannelId(id);
      else if (mode === 'DM') { setSelectedDmUserId(id); setSelectedGroupId(null); }
      else if (mode === 'GROUP') { setSelectedGroupId(id); setSelectedDmUserId(null); }

      setIsMobileChatOpen(true);
  };

  const handleOpenProfile = (e: React.MouseEvent, userId: string) => {
    e.stopPropagation();
    setViewingUserProfileId(userId);
  };

  const handleProfileMessage = () => {
    if (viewingUserProfileId) {
        handleOpenChat('DM', viewingUserProfileId);
        setViewingUserProfileId(null);
    }
  };

  const handleProfileCall = () => {
    if (onNavigate) {
        setViewingUserProfileId(null);
        onNavigate('voice');
    }
  };

  const handleBackToList = () => {
      setIsMobileChatOpen(false);
      if (onClearFriend) onClearFriend();
  };

  const handleCreateGroup = () => {
      if (!newGroupName.trim() || newGroupMembers.length === 0) return;
      const newGroup: GroupChat = { id: `g${Date.now()}`, name: newGroupName, members: ['1', ...newGroupMembers], iconColor: `bg-${['purple','blue','green','pink','orange'][Math.floor(Math.random()*5)]}-500`, unread: 0, lastMessage: 'Group created', time: 'Now' };
      setGroups(prev => [newGroup, ...prev]);
      setShowCreateGroup(false); setNewGroupName(''); setNewGroupMembers([]);
      handleOpenChat('GROUP', newGroup.id);
      setGroupMsgs([{ id: 'sys', userId: '1', content: `Created group "${newGroup.name}"`, timestamp: 'Now', type: 'text' }]);
  };
  const toggleGroupMember = (userId: string) => setNewGroupMembers(prev => prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId]);
  const handleOpenGroupSettings = () => { const group = groups.find(g => g.id === selectedGroupId); if (group) { setEditingGroup({ name: group.name, color: group.iconColor }); setShowGroupSettings(true); } };
  const handleUpdateGroup = () => { if (!selectedGroupId || !editingGroup || !editingGroup.name.trim()) return; setGroups(prev => prev.map(g => { if (g.id === selectedGroupId) return { ...g, name: editingGroup.name, iconColor: editingGroup.color }; return g; })); setShowGroupSettings(false); };

  const simulateResponse = (mode: ChatMode, contextId: string | null) => {
      if (mode === 'CHANNEL') return;
      let possibleResponders: string[] = [];
      if (mode === 'DM' && selectedDmUserId) possibleResponders = [selectedDmUserId];
      else if (mode === 'GROUP' && selectedGroupId) { const group = groups.find(g => g.id === selectedGroupId); if (group) possibleResponders = group.members.filter(id => id !== '1'); }
      if (possibleResponders.length === 0) return;
      const numResponders = (mode === 'GROUP' && possibleResponders.length > 1 && Math.random() > 0.6) ? Math.floor(Math.random() * Math.min(3, possibleResponders.length)) + 1 : 1;
      const chosenResponders = possibleResponders.sort(() => 0.5 - Math.random()).slice(0, numResponders);
      chosenResponders.forEach((responderId) => {
          const responderName = USERS[responderId].username;
          setTimeout(() => {
              // Only start typing if not already
              setTypingUsers(prev => prev.includes(responderName) ? prev : [...prev, responderName]);
              setTimeout(() => {
                  setTypingUsers(prev => prev.filter(u => u !== responderName));
                  const replies = ["That's crazy!", "For sure.", "Let's gooooo", "ggs", "Wait, really?", "I'm down.", "LMAO", "check this out", "anyone got a heal?", "rush B don't stop", "bet", "no way", "fr?", "getting on in 5", "invite me"];
                  const incomingMsg: Message = { id: Date.now().toString() + Math.random().toString(), userId: responderId, content: replies[Math.floor(Math.random() * replies.length)], timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), type: 'text' };
                  if (mode === 'DM') setDmMsgs(prev => [...prev, incomingMsg]); else if (mode === 'GROUP') setGroupMsgs(prev => [...prev, incomingMsg]);
                  new Audio('https://assets.mixkit.co/sfx/preview/mixkit-message-pop-alert-2354.mp3').play().catch(() => {});
              }, Math.random() * 2000 + 2000);
          }, Math.random() * 1500 + 500);
      });
  };

  const handleTypingSimulation = () => {
    // Logic to pick candidates to "start typing" when the user interacts
    let candidates: string[] = [];
    if (activeMode === 'CHANNEL') {
        candidates = Object.values(USERS).filter(u => u.id !== '1').map(u => u.username);
    } else if (activeMode === 'DM' && selectedDmUserId) {
        candidates = [USERS[selectedDmUserId].username];
    } else if (activeMode === 'GROUP' && selectedGroupId) {
        const group = groups.find(g => g.id === selectedGroupId);
        if (group) {
            candidates = group.members.filter(id => id !== '1').map(id => USERS[id].username);
        }
    }

    if (candidates.length === 0) return;

    // Chance to trigger typing from another user
    if (Math.random() < 0.4) {
        const typer = candidates[Math.floor(Math.random() * candidates.length)];

        if (!typingUsers.includes(typer)) {
            setTypingUsers(prev => [...prev, typer]);

            // Auto-remove after a few seconds of "inactivity"
            const timeout = setTimeout(() => {
                setTypingUsers(prev => prev.filter(u => u !== typer));
                delete typingTimeoutsRef.current[typer];
            }, 3000 + Math.random() * 3000);

            // Clear existing if necessary (though the check above handles basic duplication)
            if (typingTimeoutsRef.current[typer]) clearTimeout(typingTimeoutsRef.current[typer]);
            typingTimeoutsRef.current[typer] = timeout;
        }
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(e.target.value);
    if (e.target.value.trim().length > 0) {
        handleTypingSimulation();
    }
  };

  const handleSendMessage = (e: React.FormEvent) => { e.preventDefault(); if (!inputValue.trim()) return; const newMessage: Message = { id: Date.now().toString(), userId: '1', content: inputValue, timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), type: 'text' }; if (activeMode === 'CHANNEL') setChannelMsgs(prev => [...prev, newMessage]); else if (activeMode === 'DM') { setDmMsgs(prev => [...prev, newMessage]); simulateResponse('DM', selectedDmUserId); } else if (activeMode === 'GROUP') { setGroupMsgs(prev => [...prev, newMessage]); simulateResponse('GROUP', selectedGroupId); } setInputValue(''); new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {}); };
  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => { if (e.target.files && e.target.files[0]) { const url = URL.createObjectURL(e.target.files[0]); const newMessage: Message = { id: Date.now().toString(), userId: '1', content: url, timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), type: 'image' }; if (activeMode === 'CHANNEL') setChannelMsgs(prev => [...prev, newMessage]); else if (activeMode === 'DM') { setDmMsgs(prev => [...prev, newMessage]); simulateResponse('DM', selectedDmUserId); } else if (activeMode === 'GROUP') { setGroupMsgs(prev => [...prev, newMessage]); simulateResponse('GROUP', selectedGroupId); } new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {}); if (fileInputRef.current) fileInputRef.current.value = ''; } };
  const handleGifSelect = (url: string) => { const newMessage: Message = { id: Date.now().toString(), userId: '1', content: url, timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), type: 'image' }; if (activeMode === 'CHANNEL') setChannelMsgs(prev => [...prev, newMessage]); else if (activeMode === 'DM') { setDmMsgs(prev => [...prev, newMessage]); simulateResponse('DM', selectedDmUserId); } else if (activeMode === 'GROUP') { setGroupMsgs(prev => [...prev, newMessage]); simulateResponse('GROUP', selectedGroupId); } new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {}); setShowGifPicker(false); };

  const getTypingText = () => { 
    const count = typingUsers.length; 
    if (count === 0) return ''; 
    if (count === 1) return `${typingUsers[0]} is typing...`; 
    if (count === 2) return `${typingUsers[0]} and ${typingUsers[1]} are typing...`;
    if (count === 3) return `${typingUsers[0]}, ${typingUsers[1]}, and ${typingUsers[2]} are typing...`;
    return `${typingUsers[0]}, ${typingUsers[1]}, and ${count - 2} others are typing...`; 
  };

  const filteredGifs = MOCK_GIFS.filter(gif => gif.title.toLowerCase().includes(gifSearch.toLowerCase()));

  // Render Component
  return (
    <div className="flex h-full w-full bg-[#09090b] text-white relative">

      {/* Click-away listeners */}
      {showGifPicker && <div className="fixed inset-0 z-30" onClick={() => setShowGifPicker(false)}></div>}
      {showRightSidebar && <div className="fixed inset-0 z-30 bg-black/50 md:hidden" onClick={() => setShowRightSidebar(false)}></div>}

      {/* --- PROFILE OVERLAY MODAL --- */}
      {viewingUserProfileId && USERS[viewingUserProfileId] && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setViewingUserProfileId(null)}>
              <div 
                  className="relative w-full max-w-sm bg-[#18181b] rounded-[2rem] shadow-2xl overflow-hidden border border-white/10 animate-zoomIn"
                  onClick={(e) => e.stopPropagation()}
              >
                  {/* Banner */}
                  <div className="h-32 w-full relative">
                      <img src={USERS[viewingUserProfileId].banner || 'https://picsum.photos/600/200'} className="w-full h-full object-cover" alt="Banner" />
                      <div className="absolute inset-0 bg-gradient-to-b from-transparent to-[#18181b]/90"></div>
                      <button 
                          onClick={() => setViewingUserProfileId(null)}
                          className="absolute top-4 right-4 p-2 bg-black/50 hover:bg-black/70 rounded-full text-white transition-colors backdrop-blur-md"
                      >
                          <X size={20} />
                      </button>
                  </div>

                  {/* Content */}
                  <div className="px-6 pb-8 relative">
                      {/* Avatar */}
                      <div className="absolute -top-12 left-6">
                          <div className="relative">
                              <img 
                                  src={USERS[viewingUserProfileId].avatar} 
                                  className="w-24 h-24 rounded-3xl border-4 border-[#18181b] object-cover shadow-xl bg-[#202023]" 
                                  alt="Avatar" 
                              />
                              <div className={`absolute -bottom-1 -right-1 w-6 h-6 rounded-full border-4 border-[#18181b] 
                                  ${USERS[viewingUserProfileId].status === 'online' ? 'bg-green-500' : USERS[viewingUserProfileId].status === 'idle' ? 'bg-yellow-500' : 'bg-red-500'}`} 
                              />
                          </div>
                      </div>

                      {/* Header Info */}
                      <div className="pt-14 flex justify-between items-start mb-6">
                          <div>
                              <h2 className="text-2xl font-black text-white leading-none mb-1">{USERS[viewingUserProfileId].username}</h2>
                              <div className="flex items-center gap-2 text-sm font-medium">
                                  <span className={`
                                      ${USERS[viewingUserProfileId].status === 'online' ? 'text-green-400' : 
                                        USERS[viewingUserProfileId].status === 'idle' ? 'text-yellow-400' : 'text-slate-500'}
                                  `}>
                                      {USERS[viewingUserProfileId].status === 'online' ? 'Online' : 
                                       USERS[viewingUserProfileId].status === 'idle' ? 'Idle' : 'Offline'}
                                  </span>
                                  <span className="text-slate-600">•</span>
                                  <span className="text-purple-400">{USERS[viewingUserProfileId].role}</span>
                              </div>
                          </div>
                          {USERS[viewingUserProfileId].level && (
                              <div className="flex flex-col items-end">
                                  <div className="flex items-center gap-1 text-yellow-500 font-bold text-sm bg-yellow-500/10 px-2 py-0.5 rounded-lg border border-yellow-500/20">
                                      <Trophy size={12} /> Lvl {USERS[viewingUserProfileId].level}
                                  </div>
                              </div>
                          )}
                      </div>

                      {/* About Me */}
                      <div className="bg-[#202023] rounded-2xl p-4 mb-6 border border-white/5 relative group">
                          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">About Me</h3>
                          <p className="text-slate-300 text-sm leading-relaxed font-medium">"{USERS[viewingUserProfileId].bio || 'Just chilling in the Nexus.'}"</p>
                      </div>

                      {/* Actions Grid */}
                      <div className="grid grid-cols-2 gap-3 mb-2">
                          <button 
                              onClick={handleProfileMessage}
                              className="col-span-1 py-3 bg-purple-600 hover:bg-purple-500 text-white rounded-xl font-bold flex items-center justify-center gap-2 transition-all shadow-lg shadow-purple-600/20 active:scale-95"
                          >
                              <MessageSquare size={18} /> Text
                          </button>
                          <button 
                              onClick={handleProfileCall}
                              className="col-span-1 py-3 bg-[#202023] hover:bg-[#2b2b30] text-white rounded-xl font-bold flex items-center justify-center gap-2 transition-all border border-white/5 active:scale-95"
                          >
                              <Phone size={18} /> Call
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* --- CREATE GROUP MODAL --- */}
      {showCreateGroup && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
              <div className="w-full max-w-sm bg-[#121216] rounded-3xl border border-white/10 shadow-2xl overflow-hidden">
                  <div className="p-4 border-b border-white/5 flex justify-between items-center bg-[#18181b]">
                      <h3 className="text-lg font-bold text-white">Create Group</h3>
                      <button onClick={() => setShowCreateGroup(false)} className="text-slate-400 hover:text-white"><X size={20} /></button>
                  </div>
                  <div className="p-4 space-y-4">
                      <input 
                          value={newGroupName}
                          onChange={(e) => setNewGroupName(e.target.value)}
                          placeholder="Group Name"
                          className="w-full bg-[#09090b] border border-white/10 rounded-xl px-4 py-3 outline-none focus:border-purple-500"
                      />
                      <div className="max-h-48 overflow-y-auto custom-scrollbar space-y-1">
                          {Object.values(USERS).filter(u => u.id !== '1').map(u => (
                              <div key={u.id} onClick={() => toggleGroupMember(u.id)} className={`flex items-center gap-3 p-2 rounded-xl cursor-pointer border ${newGroupMembers.includes(u.id) ? 'bg-purple-500/10 border-purple-500' : 'border-transparent hover:bg-white/5'}`}>
                                  <img src={u.avatar} className="w-8 h-8 rounded-full" />
                                  <span className="text-sm font-medium flex-1">{u.username}</span>
                                  {newGroupMembers.includes(u.id) && <CheckCircle2 size={16} className="text-purple-500" />}
                              </div>
                          ))}
                      </div>
                      <button onClick={handleCreateGroup} disabled={!newGroupName || newGroupMembers.length === 0} className="w-full py-3 bg-purple-600 rounded-xl font-bold">Create</button>
                  </div>
              </div>
          </div>
      )}

      {/* --- GROUP SETTINGS MODAL --- */}
      {showGroupSettings && editingGroup && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
              <div className="w-full max-w-sm bg-[#121216] rounded-3xl border border-white/10 shadow-2xl">
                  <div className="p-4 border-b border-white/5 flex justify-between items-center bg-[#18181b]">
                      <h3 className="text-lg font-bold">Group Settings</h3>
                      <button onClick={() => setShowGroupSettings(false)} className="text-slate-400"><X size={20} /></button>
                  </div>
                  <div className="p-4 space-y-4">
                      <input value={editingGroup.name} onChange={(e) => setEditingGroup({...editingGroup, name: e.target.value})} className="w-full bg-[#09090b] rounded-xl px-4 py-3 outline-none border border-white/10" />
                      <div className="flex gap-2 justify-center">{['bg-purple-500', 'bg-blue-500', 'bg-green-500', 'bg-orange-500', 'bg-red-500'].map(c => (
                          <button key={c} onClick={() => setEditingGroup({...editingGroup, color: c})} className={`w-8 h-8 rounded-full ${c} ${editingGroup.color === c ? 'ring-2 ring-white' : ''}`}></button>
                      ))}</div>
                      <button onClick={handleUpdateGroup} className="w-full py-3 bg-purple-600 rounded-xl font-bold">Save</button>
                  </div>
              </div>
          </div>
      )}

      {/* --- 1. LIST VIEW (Mobile: Hidden when chat open / Desktop: Sidebar) --- */}
      <div className={`
        ${isMobileChatOpen ? 'hidden md:flex' : 'flex'} 
        md:w-72 w-full flex-col shrink-0 bg-[#09090b] md:bg-[#121216] md:rounded-[2rem] md:border border-white/5 md:shadow-2xl overflow-hidden z-10
      `}>

        {/* Sidebar Header */}
        <div className="p-4 border-b border-white/5 bg-[#09090b]">
            <div className="flex bg-[#1e1f24] p-1 rounded-xl border border-white/5">
                <button 
                    onClick={() => setActiveMode('CHANNEL')}
                    className={`flex-1 text-xs font-bold py-2.5 rounded-lg transition-all flex items-center justify-center gap-2 ${activeMode === 'CHANNEL' ? 'bg-[#2b2d31] text-white shadow-sm' : 'text-slate-500'}`}
                >
                    <Hash size={14} /> Channels
                </button>
                <button 
                    onClick={() => setActiveMode('DM')}
                    className={`flex-1 text-xs font-bold py-2.5 rounded-lg transition-all flex items-center justify-center gap-2 ${(activeMode === 'DM' || activeMode === 'GROUP') ? 'bg-[#2b2d31] text-white shadow-sm' : 'text-slate-500'}`}
                >
                    <Users size={14} /> DMs
                </button>
            </div>
        </div>

        {/* Sidebar List */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1">
            {activeMode === 'CHANNEL' ? (
                 CHANNELS.map(channel => (
                    <div 
                        key={channel.id}
                        onClick={() => handleOpenChat('CHANNEL', channel.id)}
                        className={`flex items-center justify-between px-4 py-3 rounded-xl cursor-pointer ${selectedChannelId === channel.id && isMobileChatOpen ? 'bg-purple-600/20 text-purple-400 border border-purple-500/50' : 'hover:bg-white/5 text-slate-400'}`}
                    >
                        <div className="flex items-center gap-3">
                            <HashIcon size={18} />
                            <span className="font-bold text-sm">{channel.name}</span>
                        </div>
                        {channel.unread > 0 && <span className="bg-red-500 w-2 h-2 rounded-full"></span>}
                    </div>
                 ))
            ) : (
                <>
                    <div className="flex items-center justify-between px-4 py-2">
                        <span className="text-xs font-bold text-slate-500 uppercase">Groups</span>
                        <button onClick={() => setShowCreateGroup(true)}><Plus size={16} className="text-slate-400" /></button>
                    </div>
                    {groups.map(group => (
                        <div key={group.id} onClick={() => handleOpenChat('GROUP', group.id)} className="flex items-center gap-3 p-3 rounded-xl hover:bg-white/5 cursor-pointer">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-sm ${group.iconColor}`}>{group.name.substring(0,2).toUpperCase()}</div>
                            <div className="flex-1 min-w-0">
                                <div className="font-bold text-sm text-white truncate">{group.name}</div>
                                <div className="text-xs text-slate-500 truncate">{group.lastMessage}</div>
                            </div>
                        </div>
                    ))}
                    <div className="px-4 py-2 text-xs font-bold text-slate-500 uppercase mt-2">Direct Messages</div>
                    {DM_THREADS.map(thread => {
                        const user = USERS[thread.userId];
                        return (
                            <div key={thread.id} onClick={() => handleOpenChat('DM', user.id)} className="flex items-center gap-3 p-3 rounded-xl hover:bg-white/5 cursor-pointer group">
                                <div className="relative">
                                    <img 
                                        src={user.avatar} 
                                        className="w-10 h-10 rounded-xl cursor-pointer hover:opacity-80 transition-opacity" 
                                        onClick={(e) => handleOpenProfile(e, user.id)}
                                    />
                                    <div className={`absolute -bottom-1 -right-1 w-3 h-3 border-2 border-[#09090b] rounded-full ${user.status === 'online' ? 'bg-green-500' : 'bg-slate-500'}`}></div>
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between"><span className="font-bold text-sm text-white">{user.username}</span><span className="text-[10px] text-slate-500">{thread.time}</span></div>
                                    <div className="text-xs text-slate-500 truncate">{thread.lastMessage}</div>
                                </div>
                            </div>
                        )
                    })}
                </>
            )}
        </div>
      </div>

      {/* --- 2. MAIN CHAT AREA (Mobile: Full screen when open / Desktop: Flex) --- */}
      <div className={`
         ${isMobileChatOpen ? 'flex' : 'hidden md:flex'} 
         flex-1 flex-col min-w-0 bg-[#09090b] md:bg-[#121216] md:rounded-[2rem] md:border border-white/5 md:shadow-2xl overflow-hidden relative
      `}>

         {/* Top Bar */}
         <div className="h-16 flex items-center justify-between px-4 shrink-0 bg-[#09090b]/90 backdrop-blur-md border-b border-white/5 z-20 sticky top-0">
            <div className="flex items-center gap-3">
                <button onClick={handleBackToList} className="md:hidden p-2 -ml-2 text-slate-400 hover:text-white"><ArrowLeft size={20}/></button>
                {activeMode === 'CHANNEL' ? (
                    <div className="flex items-center gap-3">
                        <Hash size={20} className="text-purple-400" />
                        <h3 className="font-bold text-white text-lg">{selectedChannelId}</h3>
                    </div>
                ) : activeMode === 'GROUP' && selectedGroupId ? (
                     <div className="flex items-center gap-3">
                        <div className={`w-8 h-8 rounded-lg ${groups.find(g => g.id === selectedGroupId)?.iconColor} flex items-center justify-center font-bold text-xs`}>{groups.find(g => g.id === selectedGroupId)?.name.substring(0,2)}</div>
                        <h3 className="font-bold text-white text-lg">{groups.find(g => g.id === selectedGroupId)?.name}</h3>
                     </div>
                ) : selectedDmUserId ? (
                     <div className="flex items-center gap-3 cursor-pointer hover:opacity-80 transition-opacity" onClick={(e) => handleOpenProfile(e, selectedDmUserId)}>
                        <img src={USERS[selectedDmUserId].avatar} className="w-8 h-8 rounded-lg" />
                        <div className="flex flex-col">
                            <h3 className="font-bold text-white leading-none">{USERS[selectedDmUserId].username}</h3>
                            <span className="text-[10px] text-slate-500">{USERS[selectedDmUserId].status}</span>
                        </div>
                     </div>
                ) : null}
            </div>

            <div className="flex items-center gap-1">
                <button className="p-2 text-slate-400 hover:text-white" onClick={() => onNavigate && onNavigate('voice')}><Phone size={20} /></button>
                {activeMode === 'GROUP' && <button onClick={handleOpenGroupSettings} className="p-2 text-slate-400 hover:text-white"><Settings size={20} /></button>}
                <button onClick={() => setShowRightSidebar(true)} className="p-2 text-slate-400 hover:text-white xl:hidden"><Users size={20} /></button>
            </div>
         </div>

         {/* Chat History */}
         <div 
            ref={chatContainerRef}
            onScroll={handleScroll}
            className="flex-1 overflow-y-auto custom-scrollbar px-4 pb-4 space-y-4 pt-4 bg-[#09090b]"
         >
             {/* Messages Rendering */}
             {getActiveMessages().map((msg, index, arr) => {
                 const isMe = msg.userId === '1';
                 const user = USERS[msg.userId];
                 const prevMsg = arr[index - 1];
                 const isSequence = prevMsg && prevMsg.userId === msg.userId && (parseInt(msg.id) - parseInt(prevMsg.id) < 600000);

                 if (activeMode === 'CHANNEL') {
                     return (
                         <div key={msg.id} className={`flex gap-3 ${isSequence ? 'mt-0.5' : 'mt-4'}`}>
                             {!isSequence ? <img src={user.avatar} className="w-10 h-10 rounded-xl mt-0.5 cursor-pointer hover:opacity-80 transition-opacity" onClick={(e) => handleOpenProfile(e, msg.userId)} /> : <div className="w-10" />}
                             <div className="flex-1 min-w-0">
                                 {!isSequence && (
                                     <div className="flex items-center gap-2 mb-0.5">
                                         <span className={`font-bold text-sm ${user.color || 'text-white'} cursor-pointer hover:underline`} onClick={(e) => handleOpenProfile(e, msg.userId)}>{user.username}</span>
                                         <span className="text-[10px] text-slate-500">{msg.timestamp}</span>
                                     </div>
                                 )}
                                 <div className="text-slate-200 text-[15px] leading-relaxed break-words">{msg.type === 'image' ? <img src={msg.content} className="rounded-xl max-w-full max-h-64 object-cover border border-white/10" /> : msg.content}</div>
                             </div>
                         </div>
                     );
                 } else {
                     return (
                         <div key={msg.id} className={`flex w-full ${isMe ? 'justify-end' : 'justify-start'} ${isSequence ? 'mt-0.5' : 'mt-3'}`}>
                             {!isMe && !isSequence && <img src={user.avatar} className="w-8 h-8 rounded-full mr-2 self-end mb-1 cursor-pointer hover:opacity-80 transition-opacity" onClick={(e) => handleOpenProfile(e, msg.userId)} />}
                             {!isMe && isSequence && <div className="w-10" />}
                             <div className={`max-w-[75%] px-4 py-2.5 rounded-2xl text-[15px] break-words ${isMe ? 'bg-purple-600 text-white rounded-br-sm' : 'bg-[#1e1f24] text-slate-200 rounded-bl-sm'}`}>
                                 {msg.type === 'image' ? <img src={msg.content} className="rounded-lg max-w-full" /> : msg.content}
                             </div>
                         </div>
                     );
                 }
             })}
         </div>

         {/* Scroll Down Button */}
         {showScrollButton && (
            <button onClick={() => scrollToBottom(true)} className="absolute bottom-20 right-4 z-20 p-3 bg-[#1e1f24] text-white rounded-full shadow-lg border border-white/10 animate-bounce">
                <ArrowDown size={20} />
            </button>
         )}

         {/* Input Area */}
         <div className="p-3 bg-[#09090b] border-t border-white/5 sticky bottom-0 z-20 pb-safe">
             {/* GIF Picker (Absolute positioned up) */}
             {showGifPicker && (
                <div className="absolute bottom-full left-0 w-full md:w-80 bg-[#18181b] border border-white/10 rounded-t-2xl md:rounded-2xl shadow-2xl z-40 h-64 flex flex-col animate-slideUp">
                    <div className="p-2 border-b border-white/5"><input autoFocus value={gifSearch} onChange={(e) => setGifSearch(e.target.value)} placeholder="Search GIFs..." className="w-full bg-[#09090b] rounded-lg py-2 px-3 text-xs text-white outline-none" /></div>
                    <div className="flex-1 overflow-y-auto p-2 grid grid-cols-2 gap-2">
                        {filteredGifs.map(gif => (<div key={gif.id} onClick={() => handleGifSelect(gif.url)} className="aspect-video rounded overflow-hidden cursor-pointer"><img src={gif.url} className="w-full h-full object-cover" /></div>))}
                    </div>
                </div>
             )}

             {/* Typing Indicator */}
             {typingUsers.length > 0 && <div className="text-[10px] text-purple-400 font-bold mb-1 pl-4 animate-pulse">{getTypingText()}</div>}

             <div className="bg-[#1e1f24] rounded-2xl flex items-center p-1 border border-white/5">
                 <button onClick={() => fileInputRef.current?.click()} className="p-2 text-slate-400"><Paperclip size={20} /></button>
                 <button onClick={() => setShowGifPicker(!showGifPicker)} className="p-2 text-slate-400"><FileVideo size={20} /></button>
                 <input type="file" ref={fileInputRef} onChange={handleFileSelect} className="hidden" accept="image/*" />

                 <form onSubmit={handleSendMessage} className="flex-1 flex items-center">
                    <input value={inputValue} onChange={handleInputChange} placeholder="Message..." className="flex-1 bg-transparent text-white placeholder-slate-500 px-2 py-2 outline-none" />
                    <button type="submit" className={`p-2 rounded-xl transition-all ${inputValue ? 'bg-purple-600 text-white' : 'text-slate-500'}`}>
                        {inputValue ? <ArrowUp size={20} /> : <Mic size={20} />}
                    </button>
                 </form>
             </div>
         </div>
      </div>

      {/* --- 3. RIGHT SIDEBAR (Members) --- */}
      <div className={`
         fixed inset-y-0 right-0 z-40 w-64 bg-[#121216] border-l border-white/5 transform transition-transform duration-300
         xl:relative xl:translate-x-0 xl:flex xl:flex-col
         ${showRightSidebar ? 'translate-x-0' : 'translate-x-full'}
      `}>
          <div className="p-4 border-b border-white/5 flex justify-between items-center bg-[#18181b]/50">
             <h3 className="font-bold text-xs uppercase text-slate-400">Details</h3>
             <button onClick={() => setShowRightSidebar(false)} className="xl:hidden text-slate-400"><X size={20} /></button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
            {activeMode === 'CHANNEL' ? (
                ['Admin', 'Mod', 'Member'].map(role => (
                    <div key={role} className="mb-6">
                        <h4 className="text-[10px] font-bold text-slate-600 uppercase mb-2">{role}</h4>
                        {Object.values(USERS).filter(u => u.role === role).map(u => (
                            <div key={u.id} className="flex items-center gap-3 py-1.5 opacity-80 cursor-pointer hover:opacity-100 transition-opacity" onClick={(e) => handleOpenProfile(e, u.id)}>
                                <div className="relative"><img src={u.avatar} className="w-8 h-8 rounded-lg" /><div className={`absolute -bottom-1 -right-1 w-2.5 h-2.5 rounded-full border-2 border-[#121216] ${u.status === 'online' ? 'bg-green-500' : 'bg-slate-500'}`}></div></div>
                                <div className={`text-sm font-bold ${u.color || 'text-slate-300'}`}>{u.username}</div>
                            </div>
                        ))}
                    </div>
                ))
            ) : (
                <div className="text-center mt-10">
                    <img src={selectedDmUserId ? USERS[selectedDmUserId].avatar : (groups.find(g=>g.id===selectedGroupId)?.iconColor ? '' : '')} className="w-24 h-24 rounded-full mx-auto mb-4 bg-white/5" />
                    <h3 className="text-xl font-bold">{selectedDmUserId ? USERS[selectedDmUserId].username : groups.find(g=>g.id===selectedGroupId)?.name}</h3>
                </div>
            )}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User as UserIcon, Search, Check, X, MessageSquare, MoreVertical, UserPlus, Ghost, Shield, Ban, Unlock, ShieldAlert } from 'lucide-react';
import { User } from '../types';

const INITIAL_REQUESTS = [
  { id: '101', username: 'NoobMaster69', avatar: 'https://picsum.photos/100/100?random=44', status: 'online', mutual: 3 },
  { id: '102', username: 'Jinx_Main', avatar: 'https://picsum.photos/100/100?random=45', status: 'offline', mutual: 12 },
  { id: '103', username: 'ViperLineup', avatar: 'https://picsum.photos/100/100?random=46', status: 'idle', mutual: 0 },
];

const INITIAL_FRIENDS: (User & { activity?: string })[] = [
  { id: '1', username: 'Nelly', avatar: 'https://picsum.photos/100/100?random=10', status: 'online', activity: 'Playing Valorant' },
  { id: '2', username: 'Mallow', avatar: 'https://picsum.photos/100/100?random=11', status: 'online', activity: 'Playing Minecraft' },
  { id: '3', username: 'Graggle', avatar: 'https://picsum.photos/100/100?random=12', status: 'online', activity: 'In Lobby' },
  { id: '4', username: 'Brimstone_Main', avatar: 'https://picsum.photos/100/100?random=13', status: 'online', activity: 'Competitive' },
  { id: '5', username: 'JettLagged', avatar: 'https://picsum.photos/100/100?random=14', status: 'idle', activity: 'Away' },
  { id: '6', username: 'Pixel_Panda', avatar: 'https://picsum.photos/100/100?random=15', status: 'dnd', activity: 'Do Not Disturb' },
  { id: '7', username: 'Sova_Main', avatar: 'https://picsum.photos/100/100?random=16', status: 'offline' },
  { id: '8', username: 'Sage_Res_Me', avatar: 'https://picsum.photos/100/100?random=17', status: 'offline' },
];

type Tab = 'online' | 'all' | 'pending' | 'blocked' | 'add';

interface FriendsViewProps {
    onOpenDM?: (user: User) => void;
}

export const FriendsView: React.FC<FriendsViewProps> = ({ onOpenDM }) => {
  const [activeTab, setActiveTab] = useState<Tab>('online');
  const [friends, setFriends] = useState(INITIAL_FRIENDS);
  const [requests, setRequests] = useState(INITIAL_REQUESTS);
  const [blockedUsers, setBlockedUsers] = useState<User[]>([
      { id: '999', username: 'ToxicPlayer', avatar: 'https://picsum.photos/100/100?random=99', status: 'offline' }
  ]);

  const [addFriendInput, setAddFriendInput] = useState('');
  const [showSuccess, setShowSuccess] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  // Menu & Modal State
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [userToBlock, setUserToBlock] = useState<User | null>(null);

  // Real-time status updates simulation
  useEffect(() => {
    const interval = setInterval(() => {
        setFriends(currentFriends => {
            const updatedFriends = [...currentFriends];
            // Pick 1 random friend to update
            const randomIndex = Math.floor(Math.random() * updatedFriends.length);
            const friend = updatedFriends[randomIndex];

            // Random chance for status change vs activity change
            const r = Math.random();

            let newStatus = friend.status;
            let newActivity = friend.activity;

            if (friend.status === 'offline') {
                // 30% chance to come online
                if (r > 0.7) {
                    newStatus = 'online';
                    newActivity = 'Just started Nexus';
                    // Optional: Play sound for friend coming online if we wanted
                }
            } else {
                // If currently online/idle/dnd
                if (r > 0.9) {
                    // Go offline
                    newStatus = 'offline';
                    newActivity = undefined;
                } else if (r > 0.75) {
                    // Go Idle
                    newStatus = 'idle';
                    newActivity = 'Away';
                } else if (r > 0.65) {
                    // Go DND
                    newStatus = 'dnd';
                    newActivity = 'In Queue';
                } else {
                    // Change Activity while Online
                    newStatus = 'online';
                    const activities = [
                        'Playing Valorant', 
                        'Playing Minecraft', 
                        'Playing Apex Legends', 
                        'Listening to Spotify', 
                        'Visual Studio Code',
                        'In Lobby',
                        'Competitive',
                        'Ranked Match'
                    ];
                    newActivity = activities[Math.floor(Math.random() * activities.length)];
                }
            }

            if (updatedFriends[randomIndex]) {
                updatedFriends[randomIndex] = {
                    ...updatedFriends[randomIndex],
                    status: newStatus,
                    activity: newActivity
                };
            }

            return updatedFriends;
        });
    }, 2500); 

    return () => clearInterval(interval);
  }, []);

  const handleAction = (id: string, action: 'accept' | 'decline') => {
    const audio = new Audio(
        action === 'accept' 
        ? 'https://assets.mixkit.co/sfx/preview/mixkit-positive-interface-beep-2586.mp3'
        : 'https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3'
    );
    audio.volume = 0.4;
    audio.play().catch(() => {});

    const el = document.getElementById(`request-${id}`);
    if (el) {
        if (action === 'accept') {
            el.style.transform = 'translateX(50px) scale(0.95)';
            el.style.opacity = '0';
            el.style.borderColor = '#22c55e'; 
            el.style.backgroundColor = 'rgba(34, 197, 94, 0.1)';
        } else {
            el.style.transform = 'translateX(-50px) scale(0.95)';
            el.style.opacity = '0';
            el.style.borderColor = '#ef4444'; 
            el.style.backgroundColor = 'rgba(239, 68, 68, 0.1)';
        }
    }

    setTimeout(() => {
        if (action === 'accept') {
            const req = requests.find(r => r.id === id);
            if (req) {
                // When accepting, give them a default activity
                setFriends(prev => [...prev, { ...req, status: 'online', activity: 'Online' }]);
            }
        }
        setRequests(requests.filter(r => r.id !== id));
    }, 300);
  };

  const sendFriendRequest = (e: React.FormEvent) => {
    e.preventDefault();
    if (!addFriendInput) return;
    setShowSuccess(true);
    new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {});
    setAddFriendInput('');
    setTimeout(() => setShowSuccess(false), 3000);
  };

  // --- BLOCKING LOGIC ---
  const handleBlockRequest = (user: User) => {
      setOpenMenuId(null);
      setUserToBlock(user);
  };

  const confirmBlock = () => {
      if (userToBlock) {
          // Remove from friends
          setFriends(prev => prev.filter(f => f.id !== userToBlock.id));
          // Add to blocked
          setBlockedUsers(prev => [...prev, { ...userToBlock, status: 'offline' }]);

          new Audio('https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3').play().catch(() => {});
          setUserToBlock(null);
      }
  };

  const handleUnblock = (id: string) => {
      const user = blockedUsers.find(u => u.id === id);
      if (user) {
          setBlockedUsers(prev => prev.filter(u => u.id !== id));
          setFriends(prev => [...prev, { ...user, status: 'online', activity: 'Online' }]);
          new Audio('https://assets.mixkit.co/sfx/preview/mixkit-positive-interface-beep-2586.mp3').play().catch(() => {});
      }
  };

  // Filter Logic
  const filteredFriends = friends.filter(friend => {
      const matchesSearch = friend.username.toLowerCase().includes(searchQuery.toLowerCase());
      if (activeTab === 'online') {
          return matchesSearch && friend.status !== 'offline';
      }
      return matchesSearch;
  });

  return (
    <div className="flex flex-col h-full bg-slate-100 dark:bg-[#1e1f24] transition-colors relative">

      {/* Click-away listener for dropdown */}
      {openMenuId && <div className="fixed inset-0 z-10" onClick={() => setOpenMenuId(null)}></div>}

      {/* --- CONFIRMATION MODAL --- */}
      {userToBlock && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fadeIn">
              <div className="bg-white dark:bg-[#121216] border border-slate-200 dark:border-white/10 rounded-3xl p-6 max-w-sm w-full shadow-2xl transform scale-100 animate-zoomIn">
                  <div className="flex items-center gap-3 mb-4 text-red-500">
                      <ShieldAlert size={32} />
                      <h3 className="text-xl font-bold text-slate-800 dark:text-white">Block User?</h3>
                  </div>
                  <p className="text-slate-500 dark:text-slate-400 text-sm mb-6 leading-relaxed">
                      Are you sure you want to block <strong className="text-slate-800 dark:text-white">{userToBlock.username}</strong>? 
                      They will be removed from your friends list and won't be able to message you.
                  </p>
                  <div className="flex gap-3">
                      <button 
                        onClick={() => setUserToBlock(null)} 
                        className="flex-1 py-3 rounded-xl font-bold text-slate-500 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-white/5 transition-colors"
                      >
                          Cancel
                      </button>
                      <button 
                        onClick={confirmBlock} 
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white rounded-xl font-bold transition-colors shadow-lg shadow-red-600/20 flex items-center justify-center gap-2"
                      >
                          <Ban size={16} /> Block
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Top Header Bar */}
      <div className="h-16 px-6 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-white dark:bg-[#1e1f24] shrink-0 sticky top-0 z-20">
        <div className="flex items-center gap-6 overflow-x-auto no-scrollbar">
          <div className="flex items-center gap-2 pr-4 border-r border-slate-200 dark:border-slate-700">
             <UserIcon className="text-slate-500" />
             <span className="font-bold text-slate-700 dark:text-white">Friends</span>
          </div>

          <div className="flex items-center gap-2">
            {['Online', 'All', 'Pending', 'Blocked'].map((tab) => {
                const tabKey = tab.toLowerCase() as Tab;
                const isPending = tabKey === 'pending';
                return (
                    <button
                        key={tab}
                        onClick={() => { setActiveTab(tabKey); setSearchQuery(''); }}
                        className={`px-3 py-1 rounded-lg font-medium text-sm transition-all relative
                            ${activeTab === tabKey 
                                ? 'bg-slate-200 dark:bg-white/10 text-slate-800 dark:text-white' 
                                : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-white/5 hover:text-slate-700 dark:hover:text-slate-200'}
                        `}
                    >
                        {tab}
                        {isPending && requests.length > 0 && (
                            <span className="ml-2 w-4 h-4 inline-flex items-center justify-center bg-red-500 text-white text-[10px] rounded-full">
                                {requests.length}
                            </span>
                        )}
                    </button>
                )
            })}
            <button
                onClick={() => { setActiveTab('add'); setSearchQuery(''); }}
                className={`ml-2 px-3 py-1 rounded-lg font-bold text-sm transition-all
                    ${activeTab === 'add' 
                        ? 'bg-transparent text-purple-500' 
                        : 'bg-purple-600 text-white hover:bg-purple-700 shadow-md shadow-purple-600/20'}
                `}
            >
                Add Friend
            </button>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-6 overflow-y-auto custom-scrollbar">

        {/* PENDING REQUESTS TAB */}
        {activeTab === 'pending' && (
            <div className="max-w-4xl mx-auto animate-fadeIn">
                <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wide mb-4">
                    Pending — {requests.length}
                </h3>

                {requests.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 text-center opacity-70">
                        <div className="w-40 h-40 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6">
                             <Ghost size={64} className="text-slate-400" />
                        </div>
                        <p className="text-slate-500 dark:text-slate-400">No pending friend requests. You're all caught up!</p>
                    </div>
                ) : (
                    <div className="space-y-2">
                        {requests.map((req) => (
                            <div 
                                key={req.id} 
                                id={`request-${req.id}`}
                                className="group flex items-center justify-between p-3 rounded-2xl bg-white dark:bg-[#2b2d31] hover:bg-slate-50 dark:hover:bg-[#35373c] border border-slate-200 dark:border-slate-800 transition-all duration-300"
                            >
                                <div className="flex items-center gap-4">
                                    <div className="relative">
                                        <img src={req.avatar} alt={req.username} className="w-12 h-12 rounded-2xl object-cover" />
                                        <div className={`absolute -bottom-1 -right-1 w-4 h-4 border-2 border-white dark:border-[#2b2d31] rounded-full 
                                            ${req.status === 'online' ? 'bg-green-500' : req.status === 'idle' ? 'bg-yellow-500' : 'bg-gray-500'}`} 
                                        />
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-slate-800 dark:text-white">{req.username}</h4>
                                        <p className="text-xs text-slate-500 dark:text-slate-400">
                                            {req.mutual > 0 ? `${req.mutual} mutual friends` : 'Incoming Friend Request'}
                                        </p>
                                    </div>
                                </div>

                                <div className="flex items-center gap-2">
                                    <button 
