export const VoiceChat: React.FC = () => {
  // Call State
  const [isConnected, setIsConnected] = useState(true);
  const [isExiting, setIsExiting] = useState(false);

  // Local Media State
  const [muted, setMuted] = useState(false);
  const [deafened, setDeafened] = useState(false);
  const [camera, setCamera] = useState(false);
  const [sharing, setSharing] = useState(false);

  // Modal State
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [invitedIds, setInvitedIds] = useState<string[]>([]);
  const [inviteSearch, setInviteSearch] = useState('');

  // Manage remote participants state for dynamic UI
  const [participants, setParticipants] = useState(INITIAL_USERS.map(u => ({
    ...u,
    isMuted: Math.random() > 0.8, // Random initial mute state
    isTalking: false,
    isCamOn: Math.random() > 0.4 // Random camera state
  })));

  // Simulate talking activity
  useEffect(() => {
    const interval = setInterval(() => {
        setParticipants(prev => prev.map(p => {
            // If muted, cannot talk
            if (p.isMuted) return { ...p, isTalking: false };

            // Random talking toggle
            const willTalk = p.isTalking ? Math.random() > 0.6 : Math.random() > 0.7;

            return {
                ...p,
                isTalking: willTalk
            };
        }));
    }, 1200); 

    return () => clearInterval(interval);
  }, []);

  const playSound = (type: 'join' | 'leave' | 'mute' | 'unmute') => {
    let src = '';
    switch(type) {
        case 'join': src = 'https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3'; break;
        case 'leave': src = 'https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3'; break;
        case 'mute': src = 'https://assets.mixkit.co/sfx/preview/mixkit-interface-click-1126.mp3'; break;
        case 'unmute': src = 'https://assets.mixkit.co/sfx/preview/mixkit-sci-fi-click-900.mp3'; break;
    }
    if(src) new Audio(src).play().catch(() => {});
  };

  const toggleMute = () => {
    const newState = !muted;
    setMuted(newState);
    playSound(newState ? 'mute' : 'unmute');
  };

  const handleLeaveCall = () => {
      // 1. Play sound
      playSound('leave');
      // 2. Start Animation
      setIsExiting(true);

      // 3. Wait for animation to finish then change state
      setTimeout(() => {
          setIsConnected(false);
          setIsExiting(false);
          // Reset local states
          setCamera(false);
          setSharing(false);
      }, 500);
  };

  const handleJoinCall = () => {
      playSound('join');
      setIsConnected(true);
  };

  const handleInvite = (friend: typeof FRIENDS_TO_INVITE[0]) => {
      if (invitedIds.includes(friend.id)) return;

      // UI Feedback: Mark as invited
      setInvitedIds(prev => [...prev, friend.id]);

      // Simulate invite sound
      new Audio('https://assets.mixkit.co/sfx/preview/mixkit-positive-interface-beep-2586.mp3').play().catch(() => {});

      // Simulate user joining after 1.5 seconds
      setTimeout(() => {
          setParticipants(prev => {
              // Check if already joined to prevent duplicates
              if (prev.find(p => p.id === friend.id)) return prev;

              return [...prev, {
                ...friend,
                isMuted: false,
                isTalking: false,
                isCamOn: Math.random() > 0.5 
            }];
          });
          playSound('join');
      }, 1500);
  };

  const getStatusColor = (status: string) => {
    switch(status) {
        case 'online': return 'bg-green-500';
        case 'idle': return 'bg-amber-500';
        case 'dnd': return 'bg-red-500';
        default: return 'bg-slate-500';
    }
  };

  // --- RENDER: JOIN SCREEN (Disconnected) ---
  if (!isConnected) {
      return (
        <div className="flex flex-col h-full items-center justify-center bg-[#0a0a0c] text-white p-6 animate-fadeIn">
            <div className="max-w-md w-full bg-[#121215] rounded-[2rem] p-8 border border-white/5 shadow-2xl text-center relative overflow-hidden group">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-purple-500 to-transparent opacity-50"></div>

                <div className="w-24 h-24 rounded-full bg-white/5 mx-auto mb-6 flex items-center justify-center relative">
                    <Signal size={40} className="text-green-500" />
                    <div className="absolute inset-0 rounded-full border border-white/5 animate-ping opacity-20"></div>
                </div>

                <h2 className="text-2xl font-black mb-2">General Voice</h2>
                <p className="text-slate-400 mb-8">{participants.length} friends are hanging out</p>

                <div className="flex justify-center -space-x-3 mb-8">
                    {participants.slice(0, 5).map(u => (
                        <img key={u.id} src={u.avatar} className="w-10 h-10 rounded-full border-2 border-[#121215]" alt={u.username} />
                    ))}
                    {participants.length > 5 && (
                        <div className="w-10 h-10 rounded-full bg-[#1e1f24] border-2 border-[#121215] flex items-center justify-center text-xs font-bold text-slate-400">
                            +{participants.length - 5}
                        </div>
                    )}
                </div>

                <button 
                    onClick={handleJoinCall}
                    className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-2xl transition-all hover:scale-[1.02] shadow-lg shadow-green-600/20 flex items-center justify-center gap-2 group/btn"
                >
                    <LogIn size={20} className="group-hover/btn:translate-x-1 transition-transform" /> Join Voice
                </button>
            </div>
        </div>
      );
  }

  // --- RENDER: CONNECTED SCREEN ---
  return (
    <div className={`flex flex-col h-full bg-[#0a0a0c] text-white overflow-hidden transition-all duration-500 ${isExiting ? 'scale-95 opacity-0 filter blur-sm' : 'scale-100 opacity-100'}`}>

      {/* --- INVITE MODAL --- */}
      {showInviteModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setShowInviteModal(false)}>
            <div className="w-full max-w-sm bg-[#18181b] rounded-3xl border border-white/10 shadow-2xl overflow-hidden animate-zoomIn" onClick={e => e.stopPropagation()}>
                <div className="p-4 border-b border-white/5 flex justify-between items-center bg-[#202023]">
                    <h3 className="font-bold text-white flex items-center gap-2">
                        <UserPlus size={18} className="text-purple-500"/> Invite Friends
                    </h3>
                    <button onClick={() => setShowInviteModal(false)} className="p-2 hover:bg-white/10 rounded-full text-slate-400 hover:text-white transition-colors">
                        <X size={20} />
                    </button>
                </div>

                <div className="p-4 max-h-[400px] overflow-y-auto custom-scrollbar space-y-2">
                    {/* Search Mock */}
                    <div className="relative mb-4">
                        <Search className="absolute left-3 top-2.5 text-slate-500" size={16} />
                        <input 
                            placeholder="Search friends..." 
                            value={inviteSearch}
                            onChange={(e) => setInviteSearch(e.target.value)}
                            className="w-full bg-[#0a0a0c] border border-white/10 rounded-xl py-2 pl-10 pr-4 text-sm text-white outline-none focus:border-purple-500" 
                        />
                    </div>

                    {FRIENDS_TO_INVITE
                        .filter(f => !participants.find(p => p.id === f.id))
                        .filter(f => f.username.toLowerCase().includes(inviteSearch.toLowerCase()))
                        .map(friend => {
                            const isInvited = invitedIds.includes(friend.id);
                            return (
                                <div key={friend.id} className="flex items-center justify-between p-3 hover:bg-white/5 rounded-xl transition-colors group">
                                    <div className="flex items-center gap-3">
                                        <div className="relative">
                                            <img src={friend.avatar} className="w-10 h-10 rounded-full" alt={friend.username} />
                                            <div className={`absolute -bottom-1 -right-1 w-3 h-3 border-2 border-[#18181b] rounded-full ${getStatusColor(friend.status)}`}></div>
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-sm text-white">{friend.username}</h4>
                                            <p className="text-[10px] text-slate-500 capitalize">{friend.status}</p>
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => handleInvite(friend)}
                                        disabled={isInvited}
                                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1 ${
                                            isInvited 
                                            ? 'bg-green-500/10 text-green-500' 
                                            : 'bg-white/10 hover:bg-purple-600 text-white'
                                        }`}
                                    >
                                        {isInvited ? <><Check size={12} /> Sent</> : 'Invite'}
                                    </button>
                                </div>
                            );
                    })}

                    {FRIENDS_TO_INVITE.every(f => participants.find(p => p.id === f.id)) && (
                        <div className="text-center py-8 text-slate-500 text-sm">
                            <p>Everyone is already here! 🎉</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
      )}

      {/* Header Channel Info */}
      <div className="h-16 border-b border-white/5 flex items-center justify-between px-6 bg-white/[0.02]">
         <div className="flex items-center gap-3">
             <Signal className="text-green-500" />
             <div>
                 <h2 className="font-bold text-lg leading-tight">General Voice</h2>
                 <p className="text-xs text-slate-500">RTC Connected • 14ms Ping</p>
             </div>
         </div>
         <div className="flex -space-x-3">
             {/* Show current user avatar too */}
             <div className="w-8 h-8 rounded-full border-2 border-[#0a0a0c] overflow-hidden relative">
                <img src="https://picsum.photos/50/50?random=99" className="w-full h-full object-cover" />
             </div>
             {participants.slice(0,3).map(u => (
                 <div key={u.id} className="relative">
                    <img src={u.avatar} className="w-8 h-8 rounded-full border-2 border-[#0a0a0c]" />
                    <div className={`absolute bottom-0 right-0 w-2.5 h-2.5 rounded-full border-2 border-[#0a0a0c] ${getStatusColor(u.status)}`}></div>
                 </div>
             ))}
             <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-xs font-bold border-2 border-[#0a0a0c]">{participants.length + 1}</div>
         </div>
      </div>

      {/* Main Stage - Grid of Users */}
      <div className="flex-1 p-6 grid grid-cols-2 md:grid-cols-3 gap-6 overflow-y-auto custom-scrollbar content-start">

        {/* Local User Tile */}
        <div className={`relative aspect-video bg-[#18181b] rounded-3xl flex flex-col items-center justify-center group overflow-hidden transition-all hover:scale-[1.02] shadow-xl border ${muted ? 'border-red-500/30' : 'border-white/5'}`}>
            {/* Camera Feed or Avatar */}
            {camera ? (
                <div className="absolute inset-0 bg-slate-800">
                    <img src="https://images.unsplash.com/photo-1595152772835-219674b2a8a6?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover opacity-80" alt="Camera Feed" />
                    <div className="absolute top-2 right-2 bg-red-600 w-3 h-3 rounded-full animate-pulse"></div>
                </div>
            ) : (
                <div className="relative z-10">
                    <div className={`relative w-24 h-24 rounded-full mb-4 ring-2 ring-white/10`}>
                        <img src="https://picsum.photos/100/100?random=99" alt="You" className="w-full h-full rounded-full object-cover" />
                        <div className={`absolute bottom-1 right-1 w-6 h-6 rounded-full border-4 border-[#18181b] ${getStatusColor('online')}`}></div>
                        {muted && (
                            <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-red-500 z-10">
                                <MicOff size={16} />
                            </div>
                        )}
                    </div>
                </div>
            )}

            <div className="absolute bottom-4 left-4 z-20">
                <span className="font-bold text-white text-sm bg-black/50 px-3 py-1 rounded-lg backdrop-blur-md">You {muted && '(Muted)'}</span>
            </div>
        </div>

        {/* Remote Participants */}
        {participants.map((user) => {
            const isSpeaking = user.isTalking && !user.isMuted;

            return (
              <div key={user.id} className={`relative aspect-video bg-[#18181b] rounded-3xl flex flex-col items-center justify-center group overflow-hidden transition-all hover:scale-[1.02] shadow-xl border-2 ${isSpeaking ? 'border-green-500 shadow-[0_0_20px_rgba(34,197,94,0.2)]' : 'border-transparent border-white/5'}`}>

                {/* Talking Indicator Glow (Only if not muted and talking) */}
                <div className={`absolute inset-0 bg-green-500/10 transition-opacity duration-300 ${isSpeaking ? 'opacity-100' : 'opacity-0'}`}></div>
                <div className={`absolute bottom-0 left-0 right-0 h-1 bg-green-500 transition-transform duration-100 ${isSpeaking ? 'scale-x-100' : 'scale-x-0'}`}></div>

                {user.isCamOn ? (
                     <div className="absolute inset-0">
                         {/* Fake camera feed images based on ID to be consistent */}
                        <img 
                            src={`https://images.unsplash.com/photo-${user.id === '2' ? '1534528741775-53994a69daeb' : user.id === '3' ? '1506794778202-cad84cf45f1d' : '1531427186611-ecfd6d936c79'}?auto=format&fit=crop&q=80&w=800`} 
                            className="w-full h-full object-cover opacity-90" 
                            alt="Cam" 
                        />
                     </div>
                ) : (
                    <div className="relative z-10">
                        <div className={`relative w-24 h-24 rounded-full mb-4 transition-all duration-300
                            ${isSpeaking ? 'ring-4 ring-green-500 shadow-[0_0_30px_rgba(34,197,94,0.4)] scale-105' : 'ring-2 ring-white/10 grayscale-[0.3]'}`}>
                            <img src={user.avatar} alt={user.username} className="w-full h-full rounded-full object-cover" />

                            {/* Status Indicator */}
                            <div className={`absolute bottom-1 right-1 w-6 h-6 rounded-full border-4 border-[#18181b] ${getStatusColor(user.status)} z-10`}></div>

                            {/* Show MicOff if muted, or Mic if talking. */}
                            {user.isMuted && (
                                <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-red-500 z-20">
                                    <MicOff size={16} />
                                </div>
                            )}
                            {isSpeaking && (
                                <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-green-500 z-20">
                                    <Mic size={16} />
                                </div>
                            )}
                        </div>
                    </div>
                )}

                <div className="absolute bottom-4 left-4 z-20 flex flex-col items-start">
                    <span className="font-bold text-white text-sm bg-black/50 px-3 py-1 rounded-lg backdrop-blur-md flex items-center gap-2">
                        {user.username}
                        {user.isMuted && <MicOff size={12} className="text-red-400"/>}
                    </span>
                </div>

                {/* Animated Background Audio Waves (Fake) - Only if no cam */}
                {!user.isCamOn && isSpeaking && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20">
                        <div className="w-32 h-32 rounded-full border-2 border-green-500 animate-ping absolute"></div>
                        <div className="w-40 h-40 rounded-full border border-green-500 animate-ping animation-delay-500 absolute"></div>
                    </div>
                )}

                <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity z-20">
                    <button className="p-2 bg-black/50 hover:bg-black/80 rounded-full text-white"><MoreHorizontal size={16} /></button>
                </div>
              </div>
            );
        })}

        {/* Invite to Call Button */}
        <div 
            onClick={() => setShowInviteModal(true)}
            className="aspect-video border-2 border-dashed border-white/10 rounded-3xl flex flex-col items-center justify-center cursor-pointer hover:bg-white/5 hover:border-white/20 transition-all group active:scale-95"
        >
            <div className="w-16 h-16 rounded-full bg-white/5 group-hover:bg-white/10 flex items-center justify-center mb-3 transition-colors">
                <UserPlus size={32} className="text-slate-500 group-hover:text-purple-400" />
            </div>
            <span className="text-slate-500 font-bold group-hover:text-white transition-colors">Invite to Call</span>
        </div>
      </div>

      {/* Bottom Controls */}
      <div className="h-24 bg-[#121215]/90 backdrop-blur-xl flex items-center justify-center px-8 border-t border-white/5 relative z-20">

        <div className="absolute left-8 flex items-center gap-4">
             <div className="relative">
                <img src="https://picsum.photos/50/50?random=99" className="w-12 h-12 rounded-2xl border border-white/10" />
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-[#121215]"></div>
             </div>
             <div className="hidden md:block">
                 <div className="font-bold text-white">You</div>
                 <div className="text-xs text-slate-400">Connected</div>
             </div>
        </div>

        <div className="flex items-center gap-4">
            <button 
                onClick={toggleMute} 
                className={`w-14 h-14 rounded-[20px] flex items-center justify-center transition-all duration-300 hover:scale-110 shadow-lg
                ${muted ? 'bg-red-500 text-white shadow-red-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}>
                {muted ? <MicOff size={24} /> : <Mic size={24} />}
            </button>
            <button 
                onClick={() => setDeafened(!deafened)} 
                className={`w-14 h-14 rounded-[20px] flex items-center justify-center transition-all duration-300 hover:scale-110 shadow-lg
                ${deafened ? 'bg-red-500 text-white shadow-red-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}>
                {deafened ? <Volume2 size={24} className="opacity-50" /> : <Headphones size={24} />}
            </button>
            <button 
                onClick={() => setCamera(!camera)} 
                className={`w-14 h-14 rounded-[20px] flex items-center justify-center transition-all duration-300 hover:scale-110 shadow-lg
                ${camera ? 'bg-green-500 text-white shadow-green-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}>
                {camera ? <Video size={24} /> : <VideoOff size={24} />}
            </button>
            <button 
                onClick={() => setSharing(!sharing)} 
                className={`w-14 h-14 rounded-[20px] flex items-center justify-center transition-all duration-300 hover:scale-110 shadow-lg
                ${sharing ? 'bg-blue-500 text-white shadow-blue-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}>
                <Monitor size={24} />
            </button>

             <div className="w-[1px] h-8 bg-white/10 mx-2"></div>

             <button 
                className="w-14 h-14 bg-red-600 hover:bg-red-700 rounded-[20px] text-white shadow-lg shadow-red-600/30 flex items-center justify-center hover:scale-110 transition-transform" 
                onClick={handleLeaveCall}
             >
                <PhoneOff size={24} />
             </button>
        </div>

        <div className="absolute right-8 hidden md:flex items-center gap-4">
             <button className="p-3 bg-white/5 hover:bg-white/10 rounded-xl text-slate-400 hover:text-white transition-colors">
                <Settings size={20} />
             </button>
        </div>
      </div>

      <style>{`
          .animation-delay-500 {
              animation-delay: 0.5s;
          }
          @keyframes zoomIn {
            from { opacity: 0; transform: scale(0.95); }
            to { opacity: 1; transform: scale(1); }
          }
          .animate-zoomIn {
            animation: zoomIn 0.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
          }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { User as UserIcon, Search, Check, X, MessageSquare, MoreVertical, UserPlus, Ghost, Shield, Ban, Unlock, ShieldAlert } from 'lucide-react';
import { User } from '../types';

const INITIAL_REQUESTS = [
  { id: '101', username: 'NoobMaster69', avatar: 'https://picsum.photos/100/100?random=44', status: 'online', mutual: 3 },
  { id: '102', username: 'Jinx_Main', avatar: 'https://picsum.photos/100/100?random=45', status: 'offline', mutual: 12 },
  { id: '103', username: 'ViperLineup', avatar: 'https://picsum.photos/100/100?random=46', status: 'idle', mutual: 0 },
];

const INITIAL_FRIENDS: (User & { activity?: string })[] = [
  { id: '2', username: 'Nelly', avatar: 'https://picsum.photos/100/100?random=10', status: 'online', activity: 'Playing Valorant' },
  { id: '3', username: 'Mallow', avatar: 'https://picsum.photos/100/100?random=11', status: 'online', activity: 'Playing Minecraft' },
  { id: '4', username: 'Graggle', avatar: 'https://picsum.photos/100/100?random=12', status: 'online', activity: 'In Lobby' },
  { id: '13', username: 'Brimstone_Main', avatar: 'https://picsum.photos/100/100?random=13', status: 'online', activity: 'Competitive' },
  { id: '14', username: 'JettLagged', avatar: 'https://picsum.photos/100/100?random=14', status: 'idle', activity: 'Away' },
  { id: '6', username: 'Pixel_Panda', avatar: 'https://picsum.photos/100/100?random=15', status: 'dnd', activity: 'Do Not Disturb' },
  { id: '7', username: 'Sova_Main', avatar: 'https://picsum.photos/100/100?random=16', status: 'offline' },
  { id: '8', username: 'Sage_Res_Me', avatar: 'https://picsum.photos/100/100?random=17', status: 'offline' },
];

type Tab = 'online' | 'all' | 'pending' | 'blocked' | 'add';

interface FriendsViewProps {
    onOpenDM?: (user: User) => void;
}

export const FriendsView: React.FC<FriendsViewProps> = ({ onOpenDM }) => {
  const [activeTab, setActiveTab] = useState<Tab>('online');
  const [friends, setFriends] = useState(INITIAL_FRIENDS);
  const [requests, setRequests] = useState(INITIAL_REQUESTS);
  const [blockedUsers, setBlockedUsers] = useState<User[]>([
      { id: '999', username: 'ToxicPlayer', avatar: 'https://picsum.photos/100/100?random=99', status: 'offline' }
  ]);

  const [addFriendInput, setAddFriendInput] = useState('');
  const [showSuccess, setShowSuccess] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  // Menu & Modal State
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [userToBlock, setUserToBlock] = useState<User | null>(null);

  // Real-time status updates simulation
  useEffect(() => {
    const interval = setInterval(() => {
        setFriends(currentFriends => {
            const updatedFriends = [...currentFriends];
            // Pick 1 random friend to update
            const randomIndex = Math.floor(Math.random() * updatedFriends.length);
            const friend = updatedFriends[randomIndex];

            // Random chance for status change vs activity change
            const r = Math.random();

            let newStatus = friend.status;
            let newActivity = friend.activity;

            if (friend.status === 'offline') {
                // 30% chance to come online
                if (r > 0.7) {
                    newStatus = 'online';
                    newActivity = 'Just started Nexus';
                    // Optional: Play sound for friend coming online if we wanted
                }
            } else {
                // If currently online/idle/dnd
                if (r > 0.9) {
                    // Go offline
                    newStatus = 'offline';
                    newActivity = undefined;
                } else if (r > 0.75) {
                    // Go Idle
                    newStatus = 'idle';
                    newActivity = 'Away';
                } else if (r > 0.65) {
                    // Go DND
                    newStatus = 'dnd';
                    newActivity = 'In Queue';
                } else {
                    // Change Activity while Online
                    newStatus = 'online';
                    const activities = [
                        'Playing Valorant', 
                        'Playing Minecraft', 
                        'Playing Apex Legends', 
                        'Listening to Spotify', 
                        'Visual Studio Code',
                        'In Lobby',
                        'Competitive',
                        'Ranked Match'
                    ];
                    newActivity = activities[Math.floor(Math.random() * activities.length)];
                }
            }

            if (updatedFriends[randomIndex]) {
                updatedFriends[randomIndex] = {
                    ...updatedFriends[randomIndex],
                    status: newStatus,
                    activity: newActivity
                };
            }

            return updatedFriends;
        });
    }, 2500); 

    return () => clearInterval(interval);
  }, []);

  const handleAction = (id: string, action: 'accept' | 'decline') => {
    const audio = new Audio(
        action === 'accept' 
        ? 'https://assets.mixkit.co/sfx/preview/mixkit-positive-interface-beep-2586.mp3'
        : 'https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3'
    );
    audio.volume = 0.4;
    audio.play().catch(() => {});

    const el = document.getElementById(`request-${id}`);
    if (el) {
        if (action === 'accept') {
            el.style.transform = 'translateX(50px) scale(0.95)';
            el.style.opacity = '0';
            el.style.borderColor = '#22c55e'; 
            el.style.backgroundColor = 'rgba(34, 197, 94, 0.1)';
        } else {
            el.style.transform = 'translateX(-50px) scale(0.95)';
            el.style.opacity = '0';
            el.style.borderColor = '#ef4444'; 
            el.style.backgroundColor = 'rgba(239, 68, 68, 0.1)';
        }
    }

    setTimeout(() => {
        if (action === 'accept') {
            const req = requests.find(r => r.id === id);
            if (req) {
                // When accepting, give them a default activity
                setFriends(prev => [...prev, { ...req, status: 'online', activity: 'Online' }]);
            }
        }
        setRequests(requests.filter(r => r.id !== id));
    }, 300);
  };

  const sendFriendRequest = (e: React.FormEvent) => {
    e.preventDefault();
    if (!addFriendInput) return;
    setShowSuccess(true);
    new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {});
    setAddFriendInput('');
    setTimeout(() => setShowSuccess(false), 3000);
  };

  // --- BLOCKING LOGIC ---
  const handleBlockRequest = (user: User) => {
      setOpenMenuId(null);
      setUserToBlock(user);
  };

  const confirmBlock = () => {
      if (userToBlock) {
          // Remove from friends
          setFriends(prev => prev.filter(f => f.id !== userToBlock.id));
          // Add to blocked
          setBlockedUsers(prev => [...prev, { ...userToBlock, status: 'offline' }]);

          new Audio('https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3').play().catch(() => {});
          setUserToBlock(null);
      }
  };

  const handleUnblock = (id: string) => {
      const user = blockedUsers.find(u => u.id === id);
      if (user) {
          setBlockedUsers(prev => prev.filter(u => u.id !== id));
          setFriends(prev => [...prev, { ...user, status: 'online', activity: 'Online' }]);
          new Audio('https://assets.mixkit.co/sfx/preview/mixkit-positive-interface-beep-2586.mp3').play().catch(() => {});
      }
  };

  // Filter Logic
  const filteredFriends = friends.filter(friend => {
      const matchesSearch = friend.username.toLowerCase().includes(searchQuery.toLowerCase());
      if (activeTab === 'online') {
          return matchesSearch && friend.status !== 'offline';
      }
      return matchesSearch;
  });

  return (
    <div className="flex flex-col h-full bg-slate-100 dark:bg-[#1e1f24] transition-colors relative">

      {/* Click-away listener for dropdown */}
      {openMenuId && <div className="fixed inset-0 z-10" onClick={() => setOpenMenuId(null)}></div>}

      {/* --- CONFIRMATION MODAL --- */}
      {userToBlock && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fadeIn">
              <div className="bg-white dark:bg-[#121216] border border-slate-200 dark:border-white/10 rounded-3xl p-6 max-w-sm w-full shadow-2xl transform scale-100 animate-zoomIn">
                  <div className="flex items-center gap-3 mb-4 text-red-500">
                      <ShieldAlert size={32} />
                      <h3 className="text-xl font-bold text-slate-800 dark:text-white">Block User?</h3>
                  </div>
                  <p className="text-slate-500 dark:text-slate-400 text-sm mb-6 leading-relaxed">
                      Are you sure you want to block <strong className="text-slate-800 dark:text-white">{userToBlock.username}</strong>? 
                      They will be removed from your friends list and won't be able to message you.
                  </p>
                  <div className="flex gap-3">
                      <button 
                        onClick={() => setUserToBlock(null)} 
                        className="flex-1 py-3 rounded-xl font-bold text-slate-500 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-white/5 transition-colors"
                      >
                          Cancel
                      </button>
                      <button 
                        onClick={confirmBlock} 
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white rounded-xl font-bold transition-colors shadow-lg shadow-red-600/20 flex items-center justify-center gap-2"
                      >
                          <Ban size={16} /> Block
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Top Header Bar */}
      <div className="h-16 px-6 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-white dark:bg-[#1e1f24] shrink-0 sticky top-0 z-20">
        <div className="flex items-center gap-6 overflow-x-auto no-scrollbar">
          <div className="flex items-center gap-2 pr-4 border-r border-slate-200 dark:border-slate-700">
             <UserIcon className="text-slate-500" />
             <span className="font-bold text-slate-700 dark:text-white">Friends</span>
          </div>

          <div className="flex items-center gap-2">
            {['Online', 'All', 'Pending', 'Blocked'].map((tab) => {
                const tabKey = tab.toLowerCase() as Tab;
                const isPending = tabKey === 'pending';
                return (
                    <button
                        key={tab}
                        onClick={() => { setActiveTab(tabKey); setSearchQuery(''); }}
                        className={`px-3 py-1 rounded-lg font-medium text-sm transition-all relative
                            ${activeTab === tabKey 
                                ? 'bg-slate-200 dark:bg-white/10 text-slate-800 dark:text-white' 
                                : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-white/5 hover:text-slate-700 dark:hover:text-slate-200'}
                        `}
                    >
                        {tab}
                        {isPending && requests.length > 0 && (
                            <span className="ml-2 w-4 h-4 inline-flex items-center justify-center bg-red-500 text-white text-[10px] rounded-full">
                                {requests.length}
                            </span>
                        )}
                    </button>
                )
            })}
            <button
                onClick={() => { setActiveTab('add'); setSearchQuery(''); }}
                className={`ml-2 px-3 py-1 rounded-lg font-bold text-sm transition-all
                    ${activeTab === 'add' 
                        ? 'bg-transparent text-purple-500' 
                        : 'bg-purple-600 text-white hover:bg-purple-700 shadow-md shadow-purple-600/20'}
                `}
            >
                Add Friend
            </button>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-6 overflow-y-auto custom-scrollbar">

        {/* PENDING REQUESTS TAB */}
        {activeTab === 'pending' && (
            <div className="max-w-4xl mx-auto animate-fadeIn">
                <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wide mb-4">
                    Pending — {requests.length}
                </h3>

                {requests.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 text-center opacity-70">
                        <div className="w-40 h-40 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6">
                             <Ghost size={64} className="text-slate-400" />
                        </div>
                        <p className="text-slate-500 dark:text-slate-400">No pending friend requests. You're all caught up!</p>
                    </div>
                ) : (
                    <div className="space-y-2">
                        {requests.map((req) => (
                            <div 
                                key={req.id} 
                                id={`request-${req.id}`}
                                className="group flex items-center justify-between p-3 rounded-2xl bg-white dark:bg-[#2b2d31] hover:bg-slate-50 dark:hover:bg-[#35373c] border border-slate-200 dark:border-slate-800 transition-all duration-300"
                            >
                                <div className="flex items-center gap-4">
                                    <div className="relative">
                                        <img src={req.avatar} alt={req.username} className="w-12 h-12 rounded-2xl object-cover" />
                                        <div className={`absolute -bottom-1 -right-1 w-4 h-4 border-2 border-white dark:border-[#2b2d31] rounded-full 
                                            ${req.status === 'online' ? 'bg-green-500' : req.status === 'idle' ? 'bg-yellow-500' : 'bg-gray-500'}`} 
                                        />
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-slate-800 dark:text-white">{req.username}</h4>
                                        <p className="text-xs text-slate-500 dark:text-slate-400">
                                            {req.mutual > 0 ? `${req.mutual} mutual friends` : 'Incoming Friend Request'}
                                        </p>
                                    </div>
                                </div>

                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={() => handleAction(req.id, 'accept')}
                                        className="w-10 h-10 rounded-full bg-slate-100 dark:bg-[#1e1f24] hover:bg-green-500 dark:hover:bg-green-500 hover:text-white text-slate-400 dark:text-slate-400 flex items-center justify-center transition-all transform active:scale-90 shadow-sm"
                                        title="Accept"
                                    >
                                        <Check size={20} />
                                    </button>
                                    <button 
                                        onClick={() => handleAction(req.id, 'decline')}
                                        className="w-10 h-10 rounded-full bg-slate-100 dark:bg-[#1e1f24] hover:bg-red-500 dark:hover:bg-red-500 hover:text-white text-slate-400 dark:text-slate-400 flex items-center justify-center transition-all transform active:scale-90 shadow-sm"
                                        title="Ignore"
                                    >
                                        <X size={20} />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        )}

        {/* ONLINE/ALL TAB */}
        {(activeTab === 'online' || activeTab === 'all') && (
            <div className="max-w-4xl mx-auto animate-fadeIn">
                <div className="relative mb-6 group">
                    <input 
                        type="text" 
                        placeholder="Search friends..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full bg-white dark:bg-[#1e1f24] border border-slate-200 dark:border-slate-800 rounded-xl py-2.5 px-4 pl-10 pr-10 text-slate-800 dark:text-white outline-none focus:ring-2 focus:ring-purple-500 transition-all shadow-sm group-hover:border-purple-500/30"
                    />
                    <Search className="absolute left-3 top-3 text-slate-400" size={18} />
                    {searchQuery && (
                        <button 
                            onClick={() => setSearchQuery('')}
                            className="absolute right-3 top-3 text-slate-400 hover:text-purple-500 transition-colors"
                        >
                            <X size={18} />
                        </button>
                    )}
                </div>

                <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wide mb-4">
                    {activeTab === 'online' ? 'Online' : 'All Friends'} — {filteredFriends.length}
                </h3>

                <div className="space-y-2">
                    {filteredFriends.length > 0 ? (
