                                <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center shadow-xl">
                                    <Play fill="black" className="ml-1" />
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <style>{`
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

                @keyframes zoomIn {
                    0% { opacity: 0; transform: scale(0.9) translateY(20px); }
                    100% { opacity: 1; transform: scale(1) translateY(0); }
                }
                .animate-zoomIn {
                    animation: zoomIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }
            `}</style>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Mic, MicOff, Headphones, Video, VideoOff, PhoneOff, Monitor, Settings, MoreHorizontal, Signal, UserPlus, Volume2, LogIn, X, Search, Check } from 'lucide-react';
import { User } from '../types';

// ID 1 is reserved for the Local User (Bogdan)
const INITIAL_USERS = [
  { id: '2', username: 'Nelly', avatar: 'https://picsum.photos/100/100?random=10', status: 'online' },
  { id: '3', username: 'Mallow', avatar: 'https://picsum.photos/100/100?random=11', status: 'online' },
  { id: '4', username: 'Graggle', avatar: 'https://picsum.photos/100/100?random=12', status: 'online' },
];

const FRIENDS_TO_INVITE = [
  { id: '11', username: 'Phibi', avatar: 'https://picsum.photos/100/100?random=13', status: 'dnd' },
  { id: '12', username: 'Locke', avatar: 'https://picsum.photos/100/100?random=14', status: 'idle' },
  { id: '6', username: 'Pixel_Panda', avatar: 'https://picsum.photos/100/100?random=15', status: 'online' },
  { id: '7', username: 'Sova_Main', avatar: 'https://picsum.photos/100/100?random=16', status: 'online' },
  { id: '8', username: 'Sage_Res_Me', avatar: 'https://picsum.photos/100/100?random=17', status: 'idle' },
  { id: '9', username: 'JettLagged', avatar: 'https://picsum.photos/100/100?random=14', status: 'dnd' },
  { id: '10', username: 'NoobMaster69', avatar: 'https://picsum.photos/100/100?random=44', status: 'online' },
];

export const VoiceChat: React.FC = () => {
  // Call State
  const [isConnected, setIsConnected] = useState(true);
  const [isExiting, setIsExiting] = useState(false);

  // Local Media State
  const [muted, setMuted] = useState(false);
  const [deafened, setDeafened] = useState(false);
  const [camera, setCamera] = useState(false);
  const [sharing, setSharing] = useState(false);

  // Modal State
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [invitedIds, setInvitedIds] = useState<string[]>([]);
  const [inviteSearch, setInviteSearch] = useState('');

  // Manage remote participants state for dynamic UI
  const [participants, setParticipants] = useState(INITIAL_USERS.map(u => ({
    ...u,
    isMuted: Math.random() > 0.8, // Random initial mute state
    isTalking: false,
    isCamOn: Math.random() > 0.4 // Random camera state
  })));

  // Simulate talking activity
  useEffect(() => {
    const interval = setInterval(() => {
        setParticipants(prev => prev.map(p => {
            // If muted, cannot talk
            if (p.isMuted) return { ...p, isTalking: false };

            // Random talking toggle
            const willTalk = p.isTalking ? Math.random() > 0.6 : Math.random() > 0.7;

            return {
                ...p,
                isTalking: willTalk
            };
        }));
    }, 1200); 

    return () => clearInterval(interval);
  }, []);

  const playSound = (type: 'join' | 'leave' | 'mute' | 'unmute') => {
    let src = '';
    switch(type) {
        case 'join': src = 'https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3'; break;
        case 'leave': src = 'https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3'; break;
        case 'mute': src = 'https://assets.mixkit.co/sfx/preview/mixkit-interface-click-1126.mp3'; break;
        case 'unmute': src = 'https://assets.mixkit.co/sfx/preview/mixkit-sci-fi-click-900.mp3'; break;
    }
    if(src) new Audio(src).play().catch(() => {});
  };

  const toggleMute = () => {
    const newState = !muted;
    setMuted(newState);
    playSound(newState ? 'mute' : 'unmute');
  };

  const handleLeaveCall = () => {
      // 1. Play sound
      playSound('leave');
      // 2. Start Animation
      setIsExiting(true);

      // 3. Wait for animation to finish then change state
      setTimeout(() => {
          setIsConnected(false);
          setIsExiting(false);
          // Reset local states
          setCamera(false);
          setSharing(false);
      }, 500);
  };

  const handleJoinCall = () => {
      playSound('join');
      setIsConnected(true);
  };

  const handleInvite = (friend: typeof FRIENDS_TO_INVITE[0]) => {
      if (invitedIds.includes(friend.id)) return;

      // UI Feedback: Mark as invited
      setInvitedIds(prev => [...prev, friend.id]);

      // Simulate invite sound
      new Audio('https://assets.mixkit.co/sfx/preview/mixkit-positive-interface-beep-2586.mp3').play().catch(() => {});

      // Simulate user joining after 1.5 seconds
      setTimeout(() => {
          setParticipants(prev => {
              // Check if already joined to prevent duplicates
              if (prev.find(p => p.id === friend.id)) return prev;

              return [...prev, {
                ...friend,
                isMuted: false,
                isTalking: false,
                isCamOn: Math.random() > 0.5 
            }];
          });
          playSound('join');
      }, 1500);
  };

  const getStatusColor = (status: string) => {
    switch(status) {
        case 'online': return 'bg-green-500';
        case 'idle': return 'bg-amber-500';
        case 'dnd': return 'bg-red-500';
        default: return 'bg-slate-500';
    }
  };

  // --- Dynamic Layout Logic ---
  const totalParticipants = participants.length + 1; // Local + Remotes

  const getLayoutConfig = () => {
      // 1-2 Users (Large)
      if (totalParticipants <= 2) return {
          grid: 'grid-cols-1 md:grid-cols-2',
          avatar: 'w-32 h-32',
          padding: 'p-12',
          gap: 'gap-8',
          labelSize: 'text-lg'
      };
      // 3-4 Users (Medium)
      if (totalParticipants <= 4) return {
          grid: 'grid-cols-2',
          avatar: 'w-24 h-24',
          padding: 'p-8',
          gap: 'gap-6',
          labelSize: 'text-sm'
      };
      // 5-9 Users (Compact)
      if (totalParticipants <= 9) return {
          grid: 'grid-cols-2 md:grid-cols-3',
          avatar: 'w-16 h-16',
          padding: 'p-4',
          gap: 'gap-4',
          labelSize: 'text-xs'
      };
      // 10+ Users (Dense)
      return {
          grid: 'grid-cols-3 md:grid-cols-4 lg:grid-cols-5',
          avatar: 'w-12 h-12',
          padding: 'p-4',
          gap: 'gap-3',
          labelSize: 'text-[10px]'
      };
  };

  const layout = getLayoutConfig();

  // --- RENDER: JOIN SCREEN (Disconnected) ---
  if (!isConnected) {
      return (
        <div className="flex flex-col h-full items-center justify-center bg-[#0a0a0c] text-white p-6 animate-fadeIn">
            <div className="max-w-md w-full bg-[#121215] rounded-[2rem] p-8 border border-white/5 shadow-2xl text-center relative overflow-hidden group">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-purple-500 to-transparent opacity-50"></div>

                <div className="w-24 h-24 rounded-full bg-white/5 mx-auto mb-6 flex items-center justify-center relative">
                    <Signal size={40} className="text-green-500" />
                    <div className="absolute inset-0 rounded-full border border-white/5 animate-ping opacity-20"></div>
                </div>

                <h2 className="text-2xl font-black mb-2">General Voice</h2>
                <p className="text-slate-400 mb-8">{participants.length} friends are hanging out</p>

                <div className="flex justify-center -space-x-3 mb-8">
                    {participants.slice(0, 5).map(u => (
                        <img key={u.id} src={u.avatar} className="w-10 h-10 rounded-full border-2 border-[#121215]" alt={u.username} />
                    ))}
                    {participants.length > 5 && (
                        <div className="w-10 h-10 rounded-full bg-[#1e1f24] border-2 border-[#121215] flex items-center justify-center text-xs font-bold text-slate-400">
                            +{participants.length - 5}
                        </div>
                    )}
                </div>

                <button 
                    onClick={handleJoinCall}
                    className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-2xl transition-all hover:scale-[1.02] shadow-lg shadow-green-600/20 flex items-center justify-center gap-2 group/btn"
                >
                    <LogIn size={20} className="group-hover/btn:translate-x-1 transition-transform" /> Join Voice
                </button>
            </div>
        </div>
      );
  }

  // --- RENDER: CONNECTED SCREEN ---
  return (
    <div className={`flex flex-col h-full bg-[#0a0a0c] text-white overflow-hidden transition-all duration-500 ${isExiting ? 'scale-95 opacity-0 filter blur-sm' : 'scale-100 opacity-100'}`}>

      {/* --- INVITE MODAL --- */}
      {showInviteModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setShowInviteModal(false)}>
            <div className="w-full max-w-sm bg-[#18181b] rounded-3xl border border-white/10 shadow-2xl overflow-hidden animate-zoomIn" onClick={e => e.stopPropagation()}>
                <div className="p-4 border-b border-white/5 flex justify-between items-center bg-[#202023]">
                    <h3 className="font-bold text-white flex items-center gap-2">
                        <UserPlus size={18} className="text-purple-500"/> Invite Friends
                    </h3>
                    <button onClick={() => setShowInviteModal(false)} className="p-2 hover:bg-white/10 rounded-full text-slate-400 hover:text-white transition-colors">
                        <X size={20} />
                    </button>
                </div>

                <div className="p-4 max-h-[400px] overflow-y-auto custom-scrollbar space-y-2">
                    {/* Search Mock */}
                    <div className="relative mb-4">
                        <Search className="absolute left-3 top-2.5 text-slate-500" size={16} />
                        <input 
                            placeholder="Search friends..." 
                            value={inviteSearch}
                            onChange={(e) => setInviteSearch(e.target.value)}
                            className="w-full bg-[#0a0a0c] border border-white/10 rounded-xl py-2 pl-10 pr-4 text-sm text-white outline-none focus:border-purple-500" 
                        />
                    </div>

                    {FRIENDS_TO_INVITE
                        .filter(f => !participants.find(p => p.id === f.id))
                        .filter(f => f.username.toLowerCase().includes(inviteSearch.toLowerCase()))
                        .map(friend => {
                            const isInvited = invitedIds.includes(friend.id);
                            return (
                                <div key={friend.id} className="flex items-center justify-between p-3 hover:bg-white/5 rounded-xl transition-colors group">
                                    <div className="flex items-center gap-3">
                                        <div className="relative">
                                            <img src={friend.avatar} className="w-10 h-10 rounded-full" alt={friend.username} />
                                            <div className={`absolute -bottom-1 -right-1 w-3 h-3 border-2 border-[#18181b] rounded-full ${getStatusColor(friend.status)}`}></div>
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-sm text-white">{friend.username}</h4>
                                            <p className="text-[10px] text-slate-500 capitalize">{friend.status}</p>
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => handleInvite(friend)}
                                        disabled={isInvited}
                                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1 ${
                                            isInvited 
                                            ? 'bg-green-500/10 text-green-500' 
                                            : 'bg-white/10 hover:bg-purple-600 text-white'
