                 <p className="text-xs text-slate-500">RTC Connected • 14ms Ping</p>
             </div>
         </div>
         <div className="flex -space-x-3">
             {/* Show current user avatar too */}
             <div className="w-8 h-8 rounded-full border-2 border-[#0a0a0c] overflow-hidden relative">
