             </div>
             {participants.slice(0,3).map(u => (
                 <div key={u.id} className="relative">
                    <img src={u.avatar} className="w-8 h-8 rounded-full border-2 border-[#0a0a0c]" />
                    <div className={`absolute bottom-0 right-0 w-2.5 h-2.5 rounded-full border-2 border-[#0a0a0c] ${getStatusColor(u.status)}`}></div>
                 </div>
             ))}
             <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-xs font-bold border-2 border-[#0a0a0c]">{participants.length + 1}</div>
