};

import React, { useState, useEffect } from 'react';
import { User as UserIcon, Search, Check, X, MessageSquare, MoreVertical, UserPlus, Ghost, Shield, Ban, Unlock, ShieldAlert } from 'lucide-react';
import { User } from '../types';

const INITIAL_REQUESTS = [
  { id: '101', username: 'NoobMaster69', avatar: 'https://picsum.photos/100/100?random=44', status: 'online', mutual: 3 },
  { id: '102', username: 'Jinx_Main', avatar: 'https://picsum.photos/100/100?random=45', status: 'offline', mutual: 12 },
  { id: '103', username: 'ViperLineup', avatar: 'https://picsum.photos/100/100?random=46', status: 'idle', mutual: 0 },
];

const INITIAL_FRIENDS: (User & { activity?: string })[] = [
  { id: '2', username: 'Nelly', avatar: 'https://picsum.photos/100/100?random=10', status: 'online', activity: 'Playing Valorant' },
  { id: '3', username: 'Mallow', avatar: 'https://picsum.photos/100/100?random=11', status: 'online', activity: 'Playing Minecraft' },
  { id: '4', username: 'Graggle', avatar: 'https://picsum.photos/100/100?random=12', status: 'online', activity: 'In Lobby' },
  { id: '13', username: 'Brimstone_Main', avatar: 'https://picsum.photos/100/100?random=13', status: 'online', activity: 'Competitive' },
  { id: '14', username: 'JettLagged', avatar: 'https://picsum.photos/100/100?random=14', status: 'idle', activity: 'Away' },
  { id: '6', username: 'Pixel_Panda', avatar: 'https://picsum.photos/100/100?random=15', status: 'dnd', activity: 'Do Not Disturb' },
  { id: '7', username: 'Sova_Main', avatar: 'https://picsum.photos/100/100?random=16', status: 'offline' },
  { id: '8', username: 'Sage_Res_Me', avatar: 'https://picsum.photos/100/100?random=17', status: 'offline' },
];

type Tab = 'online' | 'all' | 'pending' | 'blocked' | 'add';

interface FriendsViewProps {
    onOpenDM?: (user: User) => void;
}

export const FriendsView: React.FC<FriendsViewProps> = ({ onOpenDM }) => {
  const [activeTab, setActiveTab] = useState<Tab>('online');
  const [friends, setFriends] = useState(INITIAL_FRIENDS);
  const [requests, setRequests] = useState(INITIAL_REQUESTS);
  const [blockedUsers, setBlockedUsers] = useState<User[]>([
      { id: '999', username: 'ToxicPlayer', avatar: 'https://picsum.photos/100/100?random=99', status: 'offline' }
  ]);

  const [addFriendInput, setAddFriendInput] = useState('');
  const [showSuccess, setShowSuccess] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  // Menu & Modal State
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [userToBlock, setUserToBlock] = useState<User | null>(null);

  // Real-time status updates simulation
  useEffect(() => {
    const interval = setInterval(() => {
        setFriends(currentFriends => {
            const updatedFriends = [...currentFriends];
            // Pick 1 random friend to update
            const randomIndex = Math.floor(Math.random() * updatedFriends.length);
            const friend = updatedFriends[randomIndex];

            // Random chance for status change vs activity change
            const r = Math.random();

            let newStatus = friend.status;
            let newActivity = friend.activity;

            if (friend.status === 'offline') {
                // 30% chance to come online
                if (r > 0.7) {
                    newStatus = 'online';
                    newActivity = 'Just started Nexus';
                    // Optional: Play sound for friend coming online if we wanted
                }
            } else {
                // If currently online/idle/dnd
                if (r > 0.9) {
                    // Go offline
                    newStatus = 'offline';
                    newActivity = undefined;
                } else if (r > 0.75) {
                    // Go Idle
                    newStatus = 'idle';
                    newActivity = 'Away';
                } else if (r > 0.65) {
                    // Go DND
                    newStatus = 'dnd';
                    newActivity = 'In Queue';
                } else {
                    // Change Activity while Online
                    newStatus = 'online';
                    const activities = [
                        'Playing Valorant', 
                        'Playing Minecraft', 
                        'Playing Apex Legends', 
                        'Listening to Spotify', 
                        'Visual Studio Code',
                        'In Lobby',
                        'Competitive',
                        'Ranked Match'
                    ];
                    newActivity = activities[Math.floor(Math.random() * activities.length)];
                }
            }

            if (updatedFriends[randomIndex]) {
                updatedFriends[randomIndex] = {
                    ...updatedFriends[randomIndex],
                    status: newStatus,
                    activity: newActivity
                };
            }

            return updatedFriends;
        });
    }, 2500); 

    return () => clearInterval(interval);
  }, []);

  const handleAction = (id: string, action: 'accept' | 'decline') => {
    const audio = new Audio(
        action === 'accept' 
        ? 'https://assets.mixkit.co/sfx/preview/mixkit-positive-interface-beep-2586.mp3'
        : 'https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3'
    );
    audio.volume = 0.4;
    audio.play().catch(() => {});

    const el = document.getElementById(`request-${id}`);
    if (el) {
        if (action === 'accept') {
            el.style.transform = 'translateX(50px) scale(0.95)';
            el.style.opacity = '0';
            el.style.borderColor = '#22c55e'; 
            el.style.backgroundColor = 'rgba(34, 197, 94, 0.1)';
        } else {
            el.style.transform = 'translateX(-50px) scale(0.95)';
            el.style.opacity = '0';
            el.style.borderColor = '#ef4444'; 
            el.style.backgroundColor = 'rgba(239, 68, 68, 0.1)';
        }
    }

    setTimeout(() => {
        if (action === 'accept') {
            const req = requests.find(r => r.id === id);
            if (req) {
                // When accepting, give them a default activity
                setFriends(prev => [...prev, { ...req, status: 'online', activity: 'Online' }]);
            }
        }
        setRequests(requests.filter(r => r.id !== id));
    }, 300);
  };

  const sendFriendRequest = (e: React.FormEvent) => {
    e.preventDefault();
    if (!addFriendInput) return;
    setShowSuccess(true);
    new Audio('https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3').play().catch(() => {});
    setAddFriendInput('');
    setTimeout(() => setShowSuccess(false), 3000);
  };

  // --- BLOCKING LOGIC ---
  const handleBlockRequest = (user: User) => {
      setOpenMenuId(null);
      setUserToBlock(user);
  };

  const confirmBlock = () => {
      if (userToBlock) {
          // Remove from friends
          setFriends(prev => prev.filter(f => f.id !== userToBlock.id));
          // Add to blocked
          setBlockedUsers(prev => [...prev, { ...userToBlock, status: 'offline' }]);

          new Audio('https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3').play().catch(() => {});
          setUserToBlock(null);
      }
  };

  const handleUnblock = (id: string) => {
      const user = blockedUsers.find(u => u.id === id);
      if (user) {
          setBlockedUsers(prev => prev.filter(u => u.id !== id));
          setFriends(prev => [...prev, { ...user, status: 'online', activity: 'Online' }]);
          new Audio('https://assets.mixkit.co/sfx/preview/mixkit-positive-interface-beep-2586.mp3').play().catch(() => {});
      }
  };

  // Filter Logic
  const filteredFriends = friends.filter(friend => {
      const matchesSearch = friend.username.toLowerCase().includes(searchQuery.toLowerCase());
      if (activeTab === 'online') {
          return matchesSearch && friend.status !== 'offline';
      }
      return matchesSearch;
  });

  return (
    <div className="flex flex-col h-full bg-slate-100 dark:bg-[#1e1f24] transition-colors relative">

      {/* Click-away listener for dropdown */}
      {openMenuId && <div className="fixed inset-0 z-10" onClick={() => setOpenMenuId(null)}></div>}

      {/* --- CONFIRMATION MODAL --- */}
      {userToBlock && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fadeIn">
              <div className="bg-white dark:bg-[#121216] border border-slate-200 dark:border-white/10 rounded-3xl p-6 max-w-sm w-full shadow-2xl transform scale-100 animate-zoomIn">
                  <div className="flex items-center gap-3 mb-4 text-red-500">
                      <ShieldAlert size={32} />
                      <h3 className="text-xl font-bold text-slate-800 dark:text-white">Block User?</h3>
                  </div>
                  <p className="text-slate-500 dark:text-slate-400 text-sm mb-6 leading-relaxed">
                      Are you sure you want to block <strong className="text-slate-800 dark:text-white">{userToBlock.username}</strong>? 
                      They will be removed from your friends list and won't be able to message you.
                  </p>
                  <div className="flex gap-3">
                      <button 
                        onClick={() => setUserToBlock(null)} 
                        className="flex-1 py-3 rounded-xl font-bold text-slate-500 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-white/5 transition-colors"
                      >
                          Cancel
                      </button>
                      <button 
                        onClick={confirmBlock} 
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white rounded-xl font-bold transition-colors shadow-lg shadow-red-600/20 flex items-center justify-center gap-2"
                      >
                          <Ban size={16} /> Block
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Top Header Bar */}
      <div className="h-16 px-6 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-white dark:bg-[#1e1f24] shrink-0 sticky top-0 z-20">
        <div className="flex items-center gap-6 overflow-x-auto no-scrollbar">
          <div className="flex items-center gap-2 pr-4 border-r border-slate-200 dark:border-slate-700">
             <UserIcon className="text-slate-500" />
             <span className="font-bold text-slate-700 dark:text-white">Friends</span>
          </div>

          <div className="flex items-center gap-2">
            {['Online', 'All', 'Pending', 'Blocked'].map((tab) => {
                const tabKey = tab.toLowerCase() as Tab;
                const isPending = tabKey === 'pending';
                return (
                    <button
                        key={tab}
                        onClick={() => { setActiveTab(tabKey); setSearchQuery(''); }}
                        className={`px-3 py-1 rounded-lg font-medium text-sm transition-all relative
                            ${activeTab === tabKey 
                                ? 'bg-slate-200 dark:bg-white/10 text-slate-800 dark:text-white' 
                                : 'text-slate-500 hover:bg-slate-100 dark:hover:bg-white/5 hover:text-slate-700 dark:hover:text-slate-200'}
                        `}
                    >
                        {tab}
                        {isPending && requests.length > 0 && (
                            <span className="ml-2 w-4 h-4 inline-flex items-center justify-center bg-red-500 text-white text-[10px] rounded-full">
                                {requests.length}
                            </span>
                        )}
                    </button>
                )
            })}
            <button
                onClick={() => { setActiveTab('add'); setSearchQuery(''); }}
                className={`ml-2 px-3 py-1 rounded-lg font-bold text-sm transition-all
                    ${activeTab === 'add' 
                        ? 'bg-transparent text-purple-500' 
                        : 'bg-purple-600 text-white hover:bg-purple-700 shadow-md shadow-purple-600/20'}
                `}
            >
                Add Friend
            </button>
          </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-6 overflow-y-auto custom-scrollbar">

        {/* PENDING REQUESTS TAB */}
        {activeTab === 'pending' && (
            <div className="max-w-4xl mx-auto animate-fadeIn">
                <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wide mb-4">
                    Pending — {requests.length}
                </h3>

                {requests.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 text-center opacity-70">
                        <div className="w-40 h-40 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6">
                             <Ghost size={64} className="text-slate-400" />
                        </div>
                        <p className="text-slate-500 dark:text-slate-400">No pending friend requests. You're all caught up!</p>
                    </div>
                ) : (
                    <div className="space-y-2">
                        {requests.map((req) => (
                            <div 
                                key={req.id} 
                                id={`request-${req.id}`}
                                className="group flex items-center justify-between p-3 rounded-2xl bg-white dark:bg-[#2b2d31] hover:bg-slate-50 dark:hover:bg-[#35373c] border border-slate-200 dark:border-slate-800 transition-all duration-300"
                            >
                                <div className="flex items-center gap-4">
                                    <div className="relative">
                                        <img src={req.avatar} alt={req.username} className="w-12 h-12 rounded-2xl object-cover" />
                                        <div className={`absolute -bottom-1 -right-1 w-4 h-4 border-2 border-white dark:border-[#2b2d31] rounded-full 
                                            ${req.status === 'online' ? 'bg-green-500' : req.status === 'idle' ? 'bg-yellow-500' : 'bg-gray-500'}`} 
                                        />
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-slate-800 dark:text-white">{req.username}</h4>
                                        <p className="text-xs text-slate-500 dark:text-slate-400">
                                            {req.mutual > 0 ? `${req.mutual} mutual friends` : 'Incoming Friend Request'}
                                        </p>
                                    </div>
                                </div>

                                <div className="flex items-center gap-2">
                                    <button 
                                        onClick={() => handleAction(req.id, 'accept')}
                                        className="w-10 h-10 rounded-full bg-slate-100 dark:bg-[#1e1f24] hover:bg-green-500 dark:hover:bg-green-500 hover:text-white text-slate-400 dark:text-slate-400 flex items-center justify-center transition-all transform active:scale-90 shadow-sm"
                                        title="Accept"
                                    >
                                        <Check size={20} />
                                    </button>
                                    <button 
                                        onClick={() => handleAction(req.id, 'decline')}
                                        className="w-10 h-10 rounded-full bg-slate-100 dark:bg-[#1e1f24] hover:bg-red-500 dark:hover:bg-red-500 hover:text-white text-slate-400 dark:text-slate-400 flex items-center justify-center transition-all transform active:scale-90 shadow-sm"
                                        title="Ignore"
                                    >
                                        <X size={20} />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        )}

        {/* ONLINE/ALL TAB */}
        {(activeTab === 'online' || activeTab === 'all') && (
            <div className="max-w-4xl mx-auto animate-fadeIn">
                <div className="relative mb-6 group">
                    <input 
                        type="text" 
                        placeholder="Search friends..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full bg-white dark:bg-[#1e1f24] border border-slate-200 dark:border-slate-800 rounded-xl py-2.5 px-4 pl-10 pr-10 text-slate-800 dark:text-white outline-none focus:ring-2 focus:ring-purple-500 transition-all shadow-sm group-hover:border-purple-500/30"
                    />
                    <Search className="absolute left-3 top-3 text-slate-400" size={18} />
                    {searchQuery && (
                        <button 
                            onClick={() => setSearchQuery('')}
                            className="absolute right-3 top-3 text-slate-400 hover:text-purple-500 transition-colors"
                        >
                            <X size={18} />
                        </button>
                    )}
                </div>

                <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wide mb-4">
                    {activeTab === 'online' ? 'Online' : 'All Friends'} — {filteredFriends.length}
                </h3>

                <div className="space-y-2">
                    {filteredFriends.length > 0 ? (
                        filteredFriends.map(friend => (
                            <div key={friend.id} className="group flex items-center justify-between p-3 rounded-2xl hover:bg-white dark:hover:bg-[#2b2d31] transition-colors cursor-pointer border border-transparent hover:border-slate-200 dark:hover:border-slate-700 relative z-0">
                                 <div className="flex items-center gap-4">
                                    <div className="relative">
                                        <img src={friend.avatar} alt={friend.username} className="w-10 h-10 rounded-full object-cover" />
                                        <div className={`absolute bottom-0 right-0 w-3 h-3 border-2 border-slate-100 dark:border-[#1e1f24] rounded-full 
                                            ${friend.status === 'online' ? 'bg-green-500' : friend.status === 'idle' ? 'bg-yellow-500' : friend.status === 'dnd' ? 'bg-red-500' : 'bg-gray-500'}`} 
                                        />
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-slate-800 dark:text-white text-sm">{friend.username}</h4>
                                        <p className="text-xs text-slate-500 dark:text-slate-400">
                                            {friend.activity ? friend.activity : (friend.status === 'online' ? 'Online' : 'Offline')}
                                        </p>
                                    </div>
                                 </div>

                                 <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); onOpenDM && onOpenDM(friend); }}
                                        className="w-9 h-9 rounded-full bg-slate-100 dark:bg-[#1e1f24] flex items-center justify-center text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-200 dark:hover:bg-white/10"
                                    >
                                        <MessageSquare size={16} />
                                    </button>

                                    {/* DROPDOWN MENU TRIGGER */}
                                    <div className="relative">
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === friend.id ? null : friend.id); }}
                                            className={`w-9 h-9 rounded-full bg-slate-100 dark:bg-[#1e1f24] flex items-center justify-center text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-200 dark:hover:bg-white/10 ${openMenuId === friend.id ? 'bg-slate-200 dark:bg-white/10 text-slate-900 dark:text-white' : ''}`}
                                        >
                                            <MoreVertical size={16} />
                                        </button>

                                        {/* DROPDOWN MENU */}
                                        {openMenuId === friend.id && (
                                            <div className="absolute right-0 top-10 w-40 bg-white dark:bg-[#18181b] border border-slate-200 dark:border-white/10 rounded-xl shadow-2xl z-50 overflow-hidden animate-fadeIn origin-top-right">
                                                <button onClick={() => setOpenMenuId(null)} className="w-full text-left px-4 py-2.5 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-white/5 text-sm font-medium flex items-center gap-2">
                                                    <UserIcon size={14} /> Profile
                                                </button>
                                                <div className="h-px bg-slate-200 dark:bg-white/5 mx-2 my-1"></div>
                                                <button 
                                                    onClick={(e) => { e.stopPropagation(); handleBlockRequest(friend); }} 
                                                    className="w-full text-left px-4 py-2.5 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 text-sm font-bold flex items-center gap-2"
                                                >
                                                    <Ban size={14} /> Block
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                 </div>
                            </div>
                        ))
                    ) : (
                         <div className="flex flex-col items-center justify-center py-12 text-center opacity-70">
                            <Search size={48} className="text-slate-300 dark:text-slate-600 mb-4" />
                            <p className="text-slate-500 dark:text-slate-400 font-medium">No friends found matching "{searchQuery}"</p>
                        </div>
                    )}
                </div>
            </div>
        )}

        {/* BLOCKED TAB */}
        {activeTab === 'blocked' && (
             <div className="max-w-4xl mx-auto animate-fadeIn">
                <div className="mb-4">
                    <h3 className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wide">
                        Blocked — {blockedUsers.length}
                    </h3>
                    <p className="text-xs text-slate-400 mt-1">You can't see their messages, and they can't see yours.</p>
                </div>

                {blockedUsers.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 text-center opacity-70">
                        <div className="w-40 h-40 bg-slate-200 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6">
                             <Shield size={64} className="text-slate-400" />
                        </div>
                        <p className="text-slate-500 dark:text-slate-400">No blocked users. Good vibes only!</p>
                    </div>
                ) : (
                    <div className="space-y-2">
                        {blockedUsers.map(user => (
                            <div key={user.id} className="flex items-center justify-between p-3 rounded-2xl bg-white dark:bg-[#2b2d31] border border-slate-200 dark:border-slate-800">
                                <div className="flex items-center gap-4">
                                    <div className="relative opacity-50">
                                        <img src={user.avatar} className="w-10 h-10 rounded-full object-cover grayscale" alt={user.username} />
                                    </div>
                                    <div>
                                        <h4 className="font-bold text-slate-800 dark:text-white text-sm">{user.username}</h4>
                                        <p className="text-xs text-red-500 font-bold uppercase">Blocked</p>
                                    </div>
                                </div>
                                <button 
                                    onClick={() => handleUnblock(user.id)}
                                    className="px-4 py-2 bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 rounded-xl text-xs font-bold text-slate-600 dark:text-slate-300 transition-colors flex items-center gap-2"
                                >
                                    <Unlock size={14} /> Unblock
                                </button>
                            </div>
                        ))}
                    </div>
                )}
             </div>
        )}

        {/* ADD FRIEND TAB */}
        {activeTab === 'add' && (
            <div className="max-w-4xl mx-auto animate-fadeIn">
                <div className="mb-6">
                    <h2 className="text-xl font-bold text-slate-800 dark:text-white mb-2 uppercase">Add Friend</h2>
                    <p className="text-slate-500 dark:text-slate-400 text-sm">You can add friends with their Nexus Tag. It's cAsE sEnSiTiVe!</p>
                </div>

                <form onSubmit={sendFriendRequest} className="relative group">
                    <input 
                        type="text"
                        value={addFriendInput}
                        onChange={(e) => setAddFriendInput(e.target.value)}
                        placeholder="Enter a Username#0000" 
                        className={`w-full h-14 bg-white dark:bg-[#1e1f24] border-2 rounded-2xl px-6 text-slate-800 dark:text-white outline-none font-medium transition-all
                            ${showSuccess ? 'border-green-500 focus:border-green-500' : 'border-slate-200 dark:border-black focus:border-purple-500'}
                        `}
                    />
                    <button 
                        type="submit"
                        disabled={!addFriendInput}
                        className="absolute right-2 top-2 h-10 px-6 bg-purple-600 hover:bg-purple-500 disabled:bg-slate-300 dark:disabled:bg-slate-700 disabled:cursor-not-allowed text-white rounded-xl font-bold text-sm transition-colors flex items-center gap-2"
                    >
                         {showSuccess ? 'Sent!' : 'Send Request'}
                    </button>
                </form>

                {showSuccess && (
                    <div className="mt-4 p-3 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-900 rounded-xl text-green-600 dark:text-green-400 text-sm font-bold flex items-center gap-2 animate-bounce">
                        <Check size={16} /> Friend request sent to {addFriendInput || 'user'}!
                    </div>
                )}

                <div className="mt-12">
                    <div className="flex flex-col items-center justify-center text-center py-10 opacity-50">
                         <UserPlus size={80} className="text-slate-300 dark:text-slate-600 mb-6" strokeWidth={1} />
                         <h3 className="text-lg font-bold text-slate-400 dark:text-slate-500">Wumpus is waiting on friends. You don't have to though!</h3>
                    </div>
                </div>
            </div>
        )}
      </div>

      <style>{`
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(5px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
            animation: fadeIn 0.3s ease-out forwards;
        }
        @keyframes zoomIn {
            from { opacity: 0; transform: scale(0.9); }
            to { opacity: 1; transform: scale(1); }
        }
        .animate-zoomIn {
            animation: zoomIn 0.2s cubic-bezier(0.16, 1, 0.3, 1);
        }
        .no-scrollbar::-webkit-scrollbar {
            display: none;
        }
        .no-scrollbar {
            -ms-overflow-style: none;
            scrollbar-width: none;
        }
      `}</style>
    </div>
  );
};

