        <div className="absolute inset-0 bg-black/20 group-hover:bg-black/40 transition-colors"></div>
        <button className="absolute top-4 right-4 bg-black/50 hover:bg-black/70 text-white px-4 py-2 rounded-full backdrop-blur-md flex items-center gap-2 transition-all opacity-0 group-hover:opacity-100 font-medium">
          <Camera size={16} /> Change Cover
        </button>
      </div>

      <div className="px-4 md:px-8 max-w-7xl mx-auto -mt-20 relative z-10">
        <div className="flex flex-col xl:flex-row gap-8">

          {/* Left Column: Profile & Socials */}
          <div className="flex-1 space-y-8">
            {/* Profile Header */}
            <div className="flex flex-col md:flex-row items-start md:items-end gap-6 mb-4">
              <div 
                className="relative group cursor-pointer"
                onClick={handleAvatarClick}
              >
                <img 
                  src={profile.avatar} 
                  className="w-32 h-32 rounded-3xl border-4 border-white dark:border-[#0f1014] shadow-2xl object-cover bg-slate-200" 
                  alt="Avatar"
                />
                <div className="absolute inset-0 bg-black/60 rounded-3xl flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity backdrop-blur-[2px] text-white">
                   <Upload size={24} className="mb-1" />
                   <span className="text-[10px] font-bold uppercase tracking-wider">Upload</span>
                </div>
                <div className="absolute -bottom-2 -right-2 bg-purple-500 text-white p-2 rounded-full border-4 border-[#0f1014] shadow-lg group-hover:scale-110 transition-transform">
                    <Camera size={14} />
                </div>
              </div>
              <div className="pb-2">
                <h1 className="text-3xl font-black text-slate-800 dark:text-white">{profile.displayName}</h1>
                <p className="text-purple-500 font-bold">Level 42 • Pro Member</p>
              </div>
            </div>

            {/* Profile Form */}
            <div className="bg-white dark:bg-[#1e1f24] p-8 rounded-3xl shadow-xl border border-slate-100 dark:border-slate-800/50">
               <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-6 flex items-center gap-2">
                 Personal Information
               </h3>

               <div className="space-y-6">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="space-y-2">
                     <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">Display Name</label>
                     <input 
                        value={profile.displayName}
                        onChange={(e) => setProfile({...profile, displayName: e.target.value})}
                        className="w-full p-4 bg-slate-50 dark:bg-black/20 rounded-xl border border-transparent focus:border-purple-500 outline-none font-semibold text-slate-700 dark:text-white transition-all"
                     />
                   </div>
                   <div className="space-y-2">
                     <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">Email (Private)</label>
                     <div className="relative">
                        <input 
                            value={profile.email}
                            disabled
                            className="w-full p-4 bg-slate-100 dark:bg-black/40 rounded-xl border border-transparent outline-none font-semibold text-slate-500 dark:text-slate-500 cursor-not-allowed pl-12"
                        />
                        <Lock className="absolute left-4 top-4 text-slate-400" size={20} />
                     </div>
                   </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-xs font-bold uppercase text-slate-400 tracking-wider">Bio</label>
                    <textarea 
                        value={profile.bio}
                        onChange={(e) => setProfile({...profile, bio: e.target.value})}
                        className="w-full p-4 bg-slate-50 dark:bg-black/20 rounded-xl border border-transparent focus:border-purple-500 outline-none font-medium text-slate-700 dark:text-white h-32 resize-none transition-all"
                    />
                 </div>
               </div>
            </div>

            {/* Social Connections */}
            <div className="bg-white dark:bg-[#1e1f24] p-8 rounded-3xl shadow-xl border border-slate-100 dark:border-slate-800/50">
               <h3 className="text-xl font-bold text-slate-800 dark:text-white mb-6">Social Connections</h3>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 {/* Existing Inputs */}
                 <div className="flex items-center gap-4 p-4 bg-blue-50 dark:bg-blue-900/10 rounded-2xl border border-blue-100 dark:border-blue-900/30">
                    <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center text-white">
                        <Twitter size={20} />
                    </div>
                    <input 
                        value={profile.twitter}
                        onChange={(e) => setProfile({...profile, twitter: e.target.value})}
                        className="bg-transparent outline-none font-bold text-slate-700 dark:text-blue-100 w-full placeholder-blue-300"
                        placeholder="@username"
                    />
                 </div>
                 <div className="flex items-center gap-4 p-4 bg-purple-50 dark:bg-purple-900/10 rounded-2xl border border-purple-100 dark:border-purple-900/30">
                    <div className="w-10 h-10 bg-purple-600 rounded-xl flex items-center justify-center text-white">
                        <Twitch size={20} />
                    </div>
                    <input 
                        value={profile.twitch}
                        onChange={(e) => setProfile({...profile, twitch: e.target.value})}
                        className="bg-transparent outline-none font-bold text-slate-700 dark:text-purple-100 w-full placeholder-purple-300"
                        placeholder="channel"
                    />
                 </div>

                 {/* Discord Link */}
                 <div className={`flex items-center justify-between p-4 rounded-2xl border transition-all ${profile.discord ? 'bg-[#5865F2]/10 border-[#5865F2]/50' : 'bg-slate-50 dark:bg-black/20 border-transparent hover:border-slate-300 dark:hover:border-slate-700'}`}>
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-[#5865F2] rounded-xl flex items-center justify-center text-white">
                            <DiscordIcon />
                        </div>
                        <div>
                            <div className="font-bold text-slate-700 dark:text-white text-sm">Discord</div>
                            {profile.discord ? (
                                <div className="text-xs font-bold text-emerald-500 flex items-center gap-1">
                                    <Check size={12} strokeWidth={3} /> {profile.discord}
                                </div>
                            ) : (
                                <div className="text-xs font-medium text-slate-500 dark:text-slate-400">Not Connected</div>
                            )}
                        </div>
                    </div>
                    <button 
                        onClick={() => handleSocialConnect('discord')}
                        className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${
                            profile.discord
                            ? 'bg-slate-200 dark:bg-white/10 text-slate-600 dark:text-slate-300 hover:bg-red-500 hover:text-white'
                            : 'bg-white dark:bg-black/20 text-slate-700 dark:text-white hover:bg-[#5865F2] hover:text-white shadow-sm'
                        }`}
                    >
                        {profile.discord ? <><Unlink size={14} /> Unlink</> : <><Link2 size={14} /> Link</>}
                    </button>
                 </div>

                 {/* Steam Link */}
                 <div className={`flex items-center justify-between p-4 rounded-2xl border transition-all ${profile.steam ? 'bg-[#171a21]/10 dark:bg-[#171a21]/50 border-[#171a21]/50 dark:border-white/20' : 'bg-slate-50 dark:bg-black/20 border-transparent hover:border-slate-300 dark:hover:border-slate-700'}`}>
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-[#171a21] rounded-xl flex items-center justify-center text-white">
                            <SteamIcon />
                        </div>
                        <div>
                            <div className="font-bold text-slate-700 dark:text-white text-sm">Steam</div>
                            {profile.steam ? (
                                <div className="text-xs font-bold text-emerald-500 flex items-center gap-1">
                                    <Check size={12} strokeWidth={3} /> {profile.steam}
                                </div>
                            ) : (
                                <div className="text-xs font-medium text-slate-500 dark:text-slate-400">Not Connected</div>
                            )}
