                    <div 
                        onClick={onSimulateCall}
                        className="flex items-center justify-between p-4 hover:bg-slate-50 dark:hover:bg-black/20 rounded-xl cursor-pointer transition-colors group border border-purple-500/20 mt-4"
                    >
                        <div className="flex items-center gap-3 text-slate-600 dark:text-slate-300">
                            <PhoneIncoming size={20} className="text-purple-500 animate-bounce" />
                            <span className="font-semibold text-purple-400">Simulate Call</span>
                        </div>
                        <div className="px-2 py-1 bg-purple-500/20 rounded text-[10px] font-bold text-purple-400 uppercase">
                            Test
                        </div>
                    </div>
                )}

                <div className="pt-4 mt-4 border-t border-slate-100 dark:border-slate-800">
                    <button 
                        onClick={onLogout}
                        className="w-full p-4 flex items-center justify-center gap-2 text-red-500 font-bold bg-red-50 dark:bg-red-900/10 hover:bg-red-100 dark:hover:bg-red-900/20 rounded-xl transition-colors"
                    >
                        <LogOut size={20} /> Log Out
                    </button>
                </div>
             </div>
          </div>

        </div>
      </div>

      <style>{`
        .mask-gradient-b {
            mask-image: linear-gradient(to bottom, black 50%, transparent 100%);
            -webkit-mask-image: linear-gradient(to bottom, black 50%, transparent 100%);
        }
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
            animation: fadeIn 0.4s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Mic, MicOff, Headphones, Video, VideoOff, PhoneOff, Monitor, Settings, MoreHorizontal, Signal, UserPlus, Volume2, LogIn, X, Search, Check } from 'lucide-react';
import { User } from '../types';

interface VoiceChatProps {
    onEndCall?: () => void;
}

// ID 1 is reserved for the Local User (Bogdan)
const INITIAL_USERS = [
  { id: '2', username: 'Nelly', avatar: 'https://picsum.photos/100/100?random=10', status: 'online' },
  { id: '3', username: 'Mallow', avatar: 'https://picsum.photos/100/100?random=11', status: 'online' },
  { id: '4', username: 'Graggle', avatar: 'https://picsum.photos/100/100?random=12', status: 'online' },
];

const FRIENDS_TO_INVITE = [
  { id: '11', username: 'Phibi', avatar: 'https://picsum.photos/100/100?random=13', status: 'dnd' },
  { id: '12', username: 'Locke', avatar: 'https://picsum.photos/100/100?random=14', status: 'idle' },
  { id: '6', username: 'Pixel_Panda', avatar: 'https://picsum.photos/100/100?random=15', status: 'online' },
  { id: '7', username: 'Sova_Main', avatar: 'https://picsum.photos/100/100?random=16', status: 'online' },
  { id: '8', username: 'Sage_Res_Me', avatar: 'https://picsum.photos/100/100?random=17', status: 'idle' },
  { id: '9', username: 'JettLagged', avatar: 'https://picsum.photos/100/100?random=14', status: 'dnd' },
  { id: '10', username: 'NoobMaster69', avatar: 'https://picsum.photos/100/100?random=44', status: 'online' },
];

export const VoiceChat: React.FC<VoiceChatProps> = ({ onEndCall }) => {
  // Call State
  const [isConnected, setIsConnected] = useState(true);
  const [isExiting, setIsExiting] = useState(false);

  // Local Media State
  const [muted, setMuted] = useState(false);
  const [deafened, setDeafened] = useState(false);
  const [camera, setCamera] = useState(false);
  const [sharing, setSharing] = useState(false);
  const [screenStream, setScreenStream] = useState<MediaStream | null>(null);

  // Modal State
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [invitedIds, setInvitedIds] = useState<string[]>([]);
  const [inviteSearch, setInviteSearch] = useState('');

  // Manage remote participants state for dynamic UI
  const [participants, setParticipants] = useState(INITIAL_USERS.map(u => ({
    ...u,
    isMuted: Math.random() > 0.8, // Random initial mute state
    isTalking: false,
    isCamOn: Math.random() > 0.4 // Random camera state
  })));

  // Simulate talking activity
  useEffect(() => {
    const interval = setInterval(() => {
        setParticipants(prev => prev.map(p => {
            // If muted, cannot talk
            if (p.isMuted) return { ...p, isTalking: false };

            // Random talking toggle
            const willTalk = p.isTalking ? Math.random() > 0.6 : Math.random() > 0.7;

            return {
                ...p,
                isTalking: willTalk
            };
        }));
    }, 1200); 

    return () => clearInterval(interval);
  }, []);

  const playSound = (type: 'join' | 'leave' | 'mute' | 'unmute') => {
    let src = '';
    switch(type) {
        case 'join': src = 'https://assets.mixkit.co/sfx/preview/mixkit-software-interface-start-2574.mp3'; break;
        case 'leave': src = 'https://assets.mixkit.co/sfx/preview/mixkit-simple-game-countdown-921.mp3'; break;
        case 'mute': src = 'https://assets.mixkit.co/sfx/preview/mixkit-interface-click-1126.mp3'; break;
        case 'unmute': src = 'https://assets.mixkit.co/sfx/preview/mixkit-sci-fi-click-900.mp3'; break;
    }
    if(src) new Audio(src).play().catch(() => {});
  };

  const toggleMute = () => {
    const newState = !muted;
    setMuted(newState);
    playSound(newState ? 'mute' : 'unmute');
  };

  const toggleScreenShare = async () => {
      if (sharing) {
          // Stop sharing
          if (screenStream) {
              screenStream.getTracks().forEach(track => track.stop());
          }
          setScreenStream(null);
          setSharing(false);
      } else {
          // Start sharing
          try {
              // @ts-ignore
              const stream = await navigator.mediaDevices.getDisplayMedia({ video: true, audio: false });
              setScreenStream(stream);
              setSharing(true);

              // Handle system stop sharing UI
              stream.getVideoTracks()[0].onended = () => {
                  setSharing(false);
                  setScreenStream(null);
              };
          } catch (e) {
              console.log("Screen share cancelled");
          }
      }
  };

  const handleLeaveCall = () => {
      // 1. Play sound
      playSound('leave');
      // 2. Start Animation
      setIsExiting(true);

      // Stop screen share if active
      if (screenStream) {
          screenStream.getTracks().forEach(track => track.stop());
      }

      // 3. Wait for animation to finish then change state
      setTimeout(() => {
          setIsConnected(false);
          setIsExiting(false);
          // Reset local states
          setCamera(false);
          setSharing(false);
          setScreenStream(null);
          if (onEndCall) onEndCall();
      }, 500);
  };

  const handleJoinCall = () => {
      playSound('join');
      setIsConnected(true);
  };

  const handleInvite = (friend: typeof FRIENDS_TO_INVITE[0]) => {
      if (invitedIds.includes(friend.id)) return;

      // UI Feedback: Mark as invited
      setInvitedIds(prev => [...prev, friend.id]);

      // Simulate invite sound
      new Audio('https://assets.mixkit.co/sfx/preview/mixkit-positive-interface-beep-2586.mp3').play().catch(() => {});

      // Simulate user joining after 1.5 seconds
      setTimeout(() => {
          setParticipants(prev => {
              // Check if already joined to prevent duplicates
              if (prev.find(p => p.id === friend.id)) return prev;

              return [...prev, {
                ...friend,
                isMuted: false,
                isTalking: false,
                isCamOn: Math.random() > 0.5 
            }];
          });
          playSound('join');
      }, 1500);
  };

  const getStatusColor = (status: string) => {
    switch(status) {
        case 'online': return 'bg-green-500';
        case 'idle': return 'bg-amber-500';
        case 'dnd': return 'bg-red-500';
        default: return 'bg-slate-500';
    }
  };

  // --- Dynamic Layout Logic ---
  const totalParticipants = participants.length + 1; // Local + Remotes

  const getLayoutConfig = () => {
      // 1-2 Users (Large)
      if (totalParticipants <= 2) return {
          grid: 'grid-cols-1 md:grid-cols-2',
          avatar: 'w-32 h-32',
          padding: 'p-12',
          gap: 'gap-8',
          labelSize: 'text-lg'
      };
      // 3-4 Users (Medium)
      if (totalParticipants <= 4) return {
          grid: 'grid-cols-2',
          avatar: 'w-24 h-24',
          padding: 'p-8',
          gap: 'gap-6',
          labelSize: 'text-sm'
      };
      // 5-9 Users (Compact)
      if (totalParticipants <= 9) return {
          grid: 'grid-cols-2 md:grid-cols-3',
          avatar: 'w-16 h-16',
          padding: 'p-4',
          gap: 'gap-4',
          labelSize: 'text-xs'
      };
      // 10+ Users (Dense)
      return {
          grid: 'grid-cols-3 md:grid-cols-4 lg:grid-cols-5',
          avatar: 'w-12 h-12',
          padding: 'p-4',
          gap: 'gap-3',
          labelSize: 'text-[10px]'
      };
  };

  const layout = getLayoutConfig();

  // --- RENDER: JOIN SCREEN (Disconnected) ---
  if (!isConnected) {
      return (
        <div className="flex flex-col h-full items-center justify-center bg-[#0a0a0c] text-white p-6 animate-fadeIn">
            <div className="max-w-md w-full bg-[#121215] rounded-[2rem] p-8 border border-white/5 shadow-2xl text-center relative overflow-hidden group">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-purple-500 to-transparent opacity-50"></div>

                <div className="w-24 h-24 rounded-full bg-white/5 mx-auto mb-6 flex items-center justify-center relative">
                    <Signal size={40} className="text-green-500" />
                    <div className="absolute inset-0 rounded-full border border-white/5 animate-ping opacity-20"></div>
                </div>

                <h2 className="text-2xl font-black mb-2">General Voice</h2>
                <p className="text-slate-400 mb-8">{participants.length} friends are hanging out</p>

                <div className="flex justify-center -space-x-3 mb-8">
                    {participants.slice(0, 5).map(u => (
                        <img key={u.id} src={u.avatar} className="w-10 h-10 rounded-full border-2 border-[#121215]" alt={u.username} />
                    ))}
                    {participants.length > 5 && (
                        <div className="w-10 h-10 rounded-full bg-[#1e1f24] border-2 border-[#121215] flex items-center justify-center text-xs font-bold text-slate-400">
                            +{participants.length - 5}
                        </div>
                    )}
                </div>

                <button 
                    onClick={handleJoinCall}
                    className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-2xl transition-all hover:scale-[1.02] shadow-lg shadow-green-600/20 flex items-center justify-center gap-2 group/btn"
                >
                    <LogIn size={20} className="group-hover/btn:translate-x-1 transition-transform" /> Join Voice
                </button>
            </div>
        </div>
      );
  }

  // --- RENDER: CONNECTED SCREEN ---
  return (
    <div className={`flex flex-col h-full bg-[#0a0a0c] text-white overflow-hidden transition-all duration-500 ${isExiting ? 'scale-95 opacity-0 filter blur-sm' : 'scale-100 opacity-100'}`}>

      {/* --- INVITE MODAL --- */}
      {showInviteModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fadeIn" onClick={() => setShowInviteModal(false)}>
            <div className="w-full max-w-sm bg-[#18181b] rounded-3xl border border-white/10 shadow-2xl overflow-hidden animate-zoomIn" onClick={e => e.stopPropagation()}>
                <div className="p-4 border-b border-white/5 flex justify-between items-center bg-[#202023]">
                    <h3 className="font-bold text-white flex items-center gap-2">
                        <UserPlus size={18} className="text-purple-500"/> Invite Friends
                    </h3>
                    <button onClick={() => setShowInviteModal(false)} className="p-2 hover:bg-white/10 rounded-full text-slate-400 hover:text-white transition-colors">
                        <X size={20} />
                    </button>
                </div>

                <div className="p-4 max-h-[400px] overflow-y-auto custom-scrollbar space-y-2">
                    {/* Search Mock */}
                    <div className="relative mb-4">
                        <Search className="absolute left-3 top-2.5 text-slate-500" size={16} />
                        <input 
                            placeholder="Search friends..." 
                            value={inviteSearch}
                            onChange={(e) => setInviteSearch(e.target.value)}
                            className="w-full bg-[#0a0a0c] border border-white/10 rounded-xl py-2 pl-10 pr-4 text-sm text-white outline-none focus:border-purple-500" 
                        />
                    </div>

                    {FRIENDS_TO_INVITE
                        .filter(f => !participants.find(p => p.id === f.id))
                        .filter(f => f.username.toLowerCase().includes(inviteSearch.toLowerCase()))
                        .map(friend => {
                            const isInvited = invitedIds.includes(friend.id);
                            return (
                                <div key={friend.id} className="flex items-center justify-between p-3 hover:bg-white/5 rounded-xl transition-colors group">
                                    <div className="flex items-center gap-3">
                                        <div className="relative">
                                            <img src={friend.avatar} className="w-10 h-10 rounded-full" alt={friend.username} />
                                            <div className={`absolute -bottom-1 -right-1 w-3 h-3 border-2 border-[#18181b] rounded-full ${getStatusColor(friend.status)}`}></div>
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-sm text-white">{friend.username}</h4>
                                            <p className="text-[10px] text-slate-500 capitalize">{friend.status}</p>
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => handleInvite(friend)}
                                        disabled={isInvited}
                                        className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1 ${
                                            isInvited 
                                            ? 'bg-green-500/10 text-green-500' 
                                            : 'bg-white/10 hover:bg-purple-600 text-white'
                                        }`}
                                    >
                                        {isInvited ? <><Check size={12} /> Sent</> : 'Invite'}
                                    </button>
                                </div>
                            );
                    })}

                    {FRIENDS_TO_INVITE.every(f => participants.find(p => p.id === f.id)) && (
                        <div className="text-center py-8 text-slate-500 text-sm">
                            <p>Everyone is already here! 🎉</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
      )}

      {/* Header Channel Info */}
      <div className="h-16 border-b border-white/5 flex items-center justify-between px-6 bg-white/[0.02]">
         <div className="flex items-center gap-3">
             <Signal className="text-green-500" />
             <div>
                 <h2 className="font-bold text-lg leading-tight">General Voice</h2>
                 <p className="text-xs text-slate-500">RTC Connected • 14ms Ping</p>
             </div>
         </div>
         <div className="flex -space-x-3">
             {/* Show current user avatar too */}
             <div className="w-8 h-8 rounded-full border-2 border-[#0a0a0c] overflow-hidden relative">
                <img src="https://picsum.photos/50/50?random=99" className="w-full h-full object-cover" />
             </div>
             {participants.slice(0,3).map(u => (
                 <div key={u.id} className="relative">
                    <img src={u.avatar} className="w-8 h-8 rounded-full border-2 border-[#0a0a0c]" />
                    <div className={`absolute bottom-0 right-0 w-2.5 h-2.5 rounded-full border-2 border-[#0a0a0c] ${getStatusColor(u.status)}`}></div>
                 </div>
             ))}
             <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-xs font-bold border-2 border-[#0a0a0c]">{participants.length + 1}</div>
         </div>
      </div>

      {/* Main Stage - Grid of Users */}
      <div className={`flex-1 overflow-y-auto custom-scrollbar content-start grid ${layout.grid} ${layout.gap} ${layout.padding} transition-all duration-500 ease-in-out`}>

        {/* Local User Tile */}
        <div className={`relative aspect-video bg-[#18181b] rounded-3xl flex flex-col items-center justify-center group overflow-hidden transition-all duration-500 hover:scale-[1.02] shadow-xl border ${muted ? 'border-red-500/30' : 'border-white/5'}`}>
            {/* Screen Share, Camera Feed or Avatar */}
            {sharing && screenStream ? (
                <div className="absolute inset-0 bg-black">
                    <video 
                        ref={video => { if (video) video.srcObject = screenStream }}
                        autoPlay 
                        playsInline 
                        muted 
                        className="w-full h-full object-contain"
                    />
                    <div className="absolute top-3 left-3 bg-blue-600/90 backdrop-blur-md text-white text-[10px] font-bold px-2 py-1 rounded-lg flex items-center gap-1.5 shadow-lg z-10">
                        <Monitor size={12} /> You are sharing
                    </div>
                </div>
            ) : camera ? (
                <div className="absolute inset-0 bg-slate-800">
                    <img src="https://images.unsplash.com/photo-1595152772835-219674b2a8a6?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover opacity-80" alt="Camera Feed" />
                    <div className="absolute top-2 right-2 bg-red-600 w-3 h-3 rounded-full animate-pulse"></div>
                </div>
            ) : (
                <div className="relative z-10 transition-all duration-500">
                    <div className={`relative ${layout.avatar} rounded-full mb-4 ring-2 ring-white/10 transition-all duration-500`}>
                        <img src="https://picsum.photos/100/100?random=99" alt="You" className="w-full h-full rounded-full object-cover" />
                        <div className={`absolute bottom-1 right-1 w-[20%] h-[20%] rounded-full border-4 border-[#18181b] ${getStatusColor('online')}`}></div>
                        {muted && (
                            <div className="absolute -bottom-1 -right-1 w-[30%] h-[30%] bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-red-500 z-10">
                                <MicOff size={16} className="w-full h-full p-1" />
                            </div>
                        )}
                    </div>
                </div>
            )}

            <div className="absolute bottom-4 left-4 z-20">
                <span className={`font-bold text-white bg-black/50 px-3 py-1 rounded-lg backdrop-blur-md ${layout.labelSize} transition-all duration-500`}>You {muted && '(Muted)'}</span>
            </div>
        </div>

        {/* Remote Participants */}
        {participants.map((user) => {
            const isSpeaking = user.isTalking && !user.isMuted;

            return (
              <div key={user.id} className={`relative aspect-video bg-[#18181b] rounded-3xl flex flex-col items-center justify-center group overflow-hidden transition-all duration-500 hover:scale-[1.02] shadow-xl border-2 ${isSpeaking ? 'border-green-500 shadow-[0_0_20px_rgba(34,197,94,0.2)]' : 'border-transparent border-white/5'}`}>

                {/* Talking Indicator Glow (Only if not muted and talking) */}
                <div className={`absolute inset-0 bg-green-500/10 transition-opacity duration-300 ${isSpeaking ? 'opacity-100' : 'opacity-0'}`}></div>
                <div className={`absolute bottom-0 left-0 right-0 h-1 bg-green-500 transition-transform duration-100 ${isSpeaking ? 'scale-x-100' : 'scale-x-0'}`}></div>

                {user.isCamOn ? (
                     <div className="absolute inset-0">
                         {/* Fake camera feed images based on ID to be consistent */}
                        <img 
                            src={`https://images.unsplash.com/photo-${user.id === '2' ? '1534528741775-53994a69daeb' : user.id === '3' ? '1506794778202-cad84cf45f1d' : '1531427186611-ecfd6d936c79'}?auto=format&fit=crop&q=80&w=800`} 
                            className="w-full h-full object-cover opacity-90" 
                            alt="Cam" 
                        />
                     </div>
                ) : (
                    <div className="relative z-10 transition-all duration-500">
                        <div className={`relative ${layout.avatar} rounded-full mb-4 transition-all duration-500
                            ${isSpeaking ? 'ring-4 ring-green-500 shadow-[0_0_30px_rgba(34,197,94,0.4)] scale-105' : 'ring-2 ring-white/10 grayscale-[0.3]'}`}>
                            <img src={user.avatar} alt={user.username} className="w-full h-full rounded-full object-cover" />

                            {/* Status Indicator */}
                            <div className={`absolute bottom-1 right-1 w-[20%] h-[20%] rounded-full border-4 border-[#18181b] ${getStatusColor(user.status)} z-10`}></div>

                            {/* Show MicOff if muted, or Mic if talking. */}
                            {user.isMuted && (
                                <div className="absolute -bottom-1 -right-1 w-[30%] h-[30%] bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-red-500 z-20">
                                    <MicOff size={16} className="w-full h-full p-1" />
                                </div>
                            )}
                            {isSpeaking && (
                                <div className="absolute -bottom-1 -right-1 w-[30%] h-[30%] bg-[#18181b] rounded-full flex items-center justify-center border-2 border-[#18181b] text-green-500 z-20">
                                    <Mic size={16} className="w-full h-full p-1" />
                                </div>
                            )}
                        </div>
                    </div>
                )}

                <div className="absolute bottom-4 left-4 z-20 flex flex-col items-start">
                    <span className={`font-bold text-white bg-black/50 px-3 py-1 rounded-lg backdrop-blur-md flex items-center gap-2 ${layout.labelSize} transition-all duration-500`}>
                        {user.username}
                        {user.isMuted && <MicOff size={12} className="text-red-400"/>}
                    </span>
                </div>

                {/* Animated Background Audio Waves (Fake) - Only if no cam */}
                {!user.isCamOn && isSpeaking && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-20">
                        <div className="w-32 h-32 rounded-full border-2 border-green-500 animate-ping absolute"></div>
                        <div className="w-40 h-40 rounded-full border border-green-500 animate-ping animation-delay-500 absolute"></div>
                    </div>
                )}

                <div className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity z-20">
                    <button className="p-2 bg-black/50 hover:bg-black/80 rounded-full text-white"><MoreHorizontal size={16} /></button>
                </div>
              </div>
            );
        })}

        {/* Invite to Call Button */}
        <div 
            onClick={() => setShowInviteModal(true)}
            className="aspect-video border-2 border-dashed border-white/10 rounded-3xl flex flex-col items-center justify-center cursor-pointer hover:bg-white/5 hover:border-white/20 transition-all group active:scale-95"
        >
            <div className="w-16 h-16 rounded-full bg-white/5 group-hover:bg-white/10 flex items-center justify-center mb-3 transition-colors">
                <UserPlus size={32} className="text-slate-500 group-hover:text-purple-400" />
            </div>
            <span className="text-slate-500 font-bold group-hover:text-white transition-colors">Invite to Call</span>
        </div>
      </div>

      {/* Bottom Controls */}
      <div className="h-24 bg-[#121215]/90 backdrop-blur-xl flex items-center justify-center px-8 border-t border-white/5 relative z-20">

        <div className="absolute left-8 flex items-center gap-4">
             <div className="relative">
                <img src="https://picsum.photos/50/50?random=99" className="w-12 h-12 rounded-2xl border border-white/10" />
                <div className="absolute -top-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-[#121215]"></div>
             </div>
             <div className="hidden md:block">
                 <div className="font-bold text-white">You</div>
                 <div className="text-xs text-slate-400">Connected</div>
             </div>
        </div>

        <div className="flex items-center gap-4">
            <button 
                onClick={toggleMute} 
                className={`w-14 h-14 rounded-[20px] flex items-center justify-center transition-all duration-300 hover:scale-110 shadow-lg
                ${muted ? 'bg-red-500 text-white shadow-red-500/20' : 'bg-white/10 hover:bg-white/20 text-white'}`}>
                {muted ? <MicOff size={24} /> : <Mic size={24} />}
            </button>
            <button 
                onClick={() => setDeafened(!deafened)} 
