export const ChatView: React.FC<ChatViewProps> = ({ initialFriend, onClearFriend, onNavigate, onCall }) => {
  // State
  const [activeMode, setActiveMode] = useState<ChatMode>(initialFriend ? 'DM' : 'CHANNEL');
